// Test spec types

const Suite = enum(u8) {
    platforms,
    subcommands,
    echo,
    glue,
    snapshot_programs,

    fn cliName(self: Suite) []const u8 {
        return switch (self) {
            .platforms => "platforms",
            .subcommands => "subcommands",
            .echo => "echo",
            .glue => "glue",
            .snapshot_programs => "snapshot-programs",
        };
    }

    fn displayName(self: Suite) []const u8 {
        return switch (self) {
            .platforms => "platforms",
            .subcommands => "subcommands",
            .echo => "echo",
            .glue => "glue",
            .snapshot_programs => "snapshot programs",
        };
    }
};

const suite_count = @typeInfo(Suite).@"enum".field_names.len;
const all_suites = [_]Suite{ .platforms, .subcommands, .echo, .glue, .snapshot_programs };

const SuiteSelection = struct {
    enabled: [suite_count]bool = @as([suite_count]bool, @splat(false)),

    fn all() SuiteSelection {
        var result = SuiteSelection{};
        for (&result.enabled) |*slot| slot.* = true;
        return result;
    }

    fn add(self: *SuiteSelection, suite: Suite) void {
        self.enabled[@backingInt(suite)] = true;
    }

    fn addAll(self: *SuiteSelection) void {
        self.* = SuiteSelection.all();
    }

    fn includes(self: SuiteSelection, suite: Suite) bool {
        return self.enabled[@backingInt(suite)];
    }

    fn isEmpty(self: SuiteSelection) bool {
        for (self.enabled) |enabled| {
            if (enabled) return false;
        }
        return true;
    }

    fn includesOnly(self: SuiteSelection, selected: Suite) bool {
        for (self.enabled, 0..) |enabled, index| {
            if (enabled != (index == @backingInt(selected))) return false;
        }
        return true;
    }
};

const OptMode = enum(u8) {
    interpreter,
    dev,
    size,
    speed,

    fn cliName(self: OptMode) []const u8 {
        return switch (self) {
            .interpreter => "interpreter",
            .dev => "dev",
            .size => "size",
            .speed => "speed",
        };
    }
};

const base_test_opts = [_]OptMode{ .interpreter, .dev };
const llvm_test_opts = [_]OptMode{ .size, .speed };

/// Which execution modes a runner invocation builds cases for.
const BackendSelection = enum {
    /// The interpreter, the dev backend, and cases with no execution mode.
    base,
    /// Every case.
    base_and_llvm,
    /// Only the cases that run the LLVM backend's size or speed mode.
    llvm,

    fn admits(self: BackendSelection, backend: ?OptMode) bool {
        const is_llvm = backend == .size or backend == .speed;
        return switch (self) {
            .base => !is_llvm,
            .base_and_llvm => true,
            .llvm => is_llvm,
        };
    }
};

const GlueExecutionMode = enum(u8) {
    default,
    dev,
    size,
    speed,

    fn cliName(self: GlueExecutionMode) []const u8 {
        return switch (self) {
            .default => "default",
            .dev => "dev",
            .size => "size",
            .speed => "speed",
        };
    }

    fn optArg(self: GlueExecutionMode) ?[]const u8 {
        return switch (self) {
            .default => null,
            .dev => "--opt=dev",
            .size => "--opt=size",
            .speed => "--opt=speed",
        };
    }
};

const GlueLanguage = enum(u8) {
    zig,
    rust,
    c,

    fn displayName(self: GlueLanguage) []const u8 {
        return switch (self) {
            .zig => "ZigGlue",
            .rust => "RustGlue",
            .c => "CGlue",
        };
    }

    fn glueSpec(self: GlueLanguage) []const u8 {
        return switch (self) {
            .zig => "src/glue/src/ZigGlue.roc",
            .rust => "src/glue/src/RustGlue.roc",
            .c => "src/glue/src/CGlue.roc",
        };
    }

    fn generatedFileName(self: GlueLanguage) []const u8 {
        return switch (self) {
            .zig => "roc_platform_abi.zig",
            .rust => "roc_platform_abi.rs",
            .c => "roc_platform_abi.h",
        };
    }

    fn hostFileName(self: GlueLanguage) []const u8 {
        return switch (self) {
            .zig => "host.zig",
            .rust => "host.rs",
            .c => "host.c",
        };
    }
};

const GlueRunnerOptions = struct {
    execution_mode: GlueExecutionMode = .default,
};

const Stream = enum {
    stdout,
    stderr,
};

const OutputNeedle = struct {
    stream: Stream,
    text: []const u8,
    /// Set for text with renderer-controlled whitespace, including aligned
    /// counter columns and word-wrapped prose. The wrap point moves
    /// with the length of the absolute paths a report embeds, so a phrase that
    /// sits on one line locally can straddle a newline on another machine. When
    /// set, each space in `text` matches any run of whitespace in the output.
    wrapped: bool = false,
};

const OutputOccurrence = struct {
    stream: Stream,
    text: []const u8,
    count: usize,
};

const OutputNeedleSet = struct {
    needles: []const OutputNeedle,
};

