const Skip = union(enum) {
    never,
    always: []const u8,
    windows: []const u8,
};

/// The roc binary under test is built in this runner's optimize mode, and
/// only a Debug compiler honors ROC_DEBUG_FORCE_ICE.
const forced_ice_skip: Skip = if (builtin.mode == .debug) .never else .{ .always = "ROC_DEBUG_FORCE_ICE requires a Debug compiler" };

/// A wasm dev build composes its output from unit images only on a Linux host
/// (`wasmFastLinkApplies` in src/cli/main.zig); elsewhere LLD links it, so a
/// case checking what the composer reports runs only on Linux.
const wasm_composed_link_skip: Skip = if (builtin.os.tag == .linux) .never else .{ .always = "the wasm dev build composes its output only on Linux hosts" };

/// The roc binary under test is also built with this runner's
/// `-Ddev-diagnostics`, so `build_options.dev_diagnostics` says whether it
/// honors the developer-diagnostic environment variables. Each case listed
/// here sets one of them and checks what it changes or prints.
const dev_diagnostics_cases = [_]CustomCase{
    .issue_12569_specialized_callables,
    .native_build_excerpt_round_trip,
    .optimized_multi_module_compiles_once,
};

fn devDiagnosticsSkip(custom: CustomCase) ?[]const u8 {
    if (comptime build_options.dev_diagnostics) return null;
    for (dev_diagnostics_cases) |case| {
        if (case == custom) return "requires a compiler with developer diagnostics (a Debug build, or -Ddev-diagnostics)";
    }
    return null;
}
/// How a forced-ICE report spells the module paths of test/cli/ice_context,
/// relative to the working directory. The root module's path is the test's
/// forward-slash path as written on the command line, and the compiler joins
/// an imported module's file name with the host's separator.
const ice_main_path_tail = "(test/cli/ice_context/Main.roc)";
const ice_helper_path_tail = "ice_context" ++ std.fs.path.sep_str ++ "Helper.roc)";

/// A single CLI test operation—one matrix cell of work.
const CliCase = struct {
    /// Unique id within this runner invocation. This keeps generated binary
    /// names distinct even on hosts that run all specs in the same process.
    id: usize,
    suite: Suite,
    /// Human-readable name, e.g. "test/fx/hello_world.roc [dev]"
    name: []const u8,
    /// Execution mode when the case has one.
    backend: ?OptMode = null,
    skip: Skip = .never,
    /// Optional per-case wall-clock bound, overriding the runner-wide
    /// `--timeout` default: perf-regression guards tighten it to fail fast,
    /// while known-slow cases (e.g. the JSON round-trip) loosen it.
    timeout_ms: ?u64 = null,
    /// Wall-clock scaling comparisons require no competing runner cases.
    scheduling: enum { parallel, exclusive } = .parallel,
    body: Body,

    const Body = union(enum) {
        platform: PlatformCase,
        command: CommandCase,
        custom: CustomCase,
        glue_runtime: GlueRuntimeCase,
        snapshot_program: SnapshotProgramCase,
    };
};

/// A snapshot's source, checked as a program. Most snapshot sources are
/// rejected programs, and `roc check` lowers every program it checks, so the
/// snapshot corpus doubles as a corpus of erroneous programs that checking
/// must report without the compiler crashing.
const SnapshotProgramCase = struct {
    snapshot_path: []const u8,
    /// The snapshot's source as a file `roc check` accepts: a `file` source
    /// as written, a `snippet` given a `main!` when it has none, and an
    /// `expr` bound to a top-level value that `main!` inspects.
    source: []const u8,
};

const snapshots_dir = "test/snapshots";

// Spec generation

fn buildCases(
    io: std.Io,
    allocator: Allocator,
    filters: []const []const u8,
    backends: BackendSelection,
    suites: SuiteSelection,
    glue_options: GlueRunnerOptions,
    cross_target: ?[]const u8,
) CliRunnerError![]const CliCase {
    var cases: std.ArrayListUnmanaged(CliCase) = .empty;

    if (suites.includes(.platforms)) {
        for (&platform_config.platforms) |platform| {
            if (cross_target) |target| {
                const target_info = platform_config.findTarget(platform, target) orelse continue;
                if (target_info.requires_linux and builtin.os.tag != .linux) continue;
                try appendCrossCompilePlatformSpecs(allocator, &cases, platform, target, filters);
            } else {
                for (&(base_test_opts ++ llvm_test_opts)) |opt| {
                    if (!backends.admits(opt)) continue;
                    try appendPlatformSpecs(allocator, &cases, platform, opt, filters);
                }
            }
        }
    }

    if (suites.includes(.echo)) {
        try appendStaticCases(allocator, &cases, &echo_cases, filters, backends);
    }
    if (suites.includes(.glue)) {
        try appendStaticCases(allocator, &cases, &glue_cases, filters, backends);
        // Glue runtime cases choose their execution mode with --glue-opt.
        if (backends.admits(null)) try appendGlueRuntimeCases(allocator, &cases, filters, glue_options);
    }
    if (suites.includes(.subcommands)) {
        try appendStaticCases(allocator, &cases, &subcommand_cases, filters, backends);
    }
    if (suites.includes(.snapshot_programs) and backends.admits(null)) {
        try appendSnapshotProgramCases(io, allocator, &cases, filters);
    }

    return try cases.toOwnedSlice(allocator);
}

fn appendSnapshotProgramCases(
    io: std.Io,
    allocator: Allocator,
    cases: *std.ArrayListUnmanaged(CliCase),
    filters: []const []const u8,
) CliRunnerError!void {
    var dir = try std.Io.Dir.cwd().openDir(io, snapshots_dir, .{ .iterate = true });
    defer dir.close(io);

    // Sorted, so every worker process rebuilds the same case order.
    var paths: std.ArrayListUnmanaged([]const u8) = .empty;
    var walker = try dir.walk(allocator);
    defer walker.deinit();
    while (try walker.next(io)) |entry| {
        if (entry.kind != .file or !std.mem.endsWith(u8, entry.basename, ".md")) continue;
        try paths.append(allocator, try std.fs.path.join(allocator, &.{ snapshots_dir, entry.path }));
    }
    std.mem.sort([]const u8, paths.items, {}, stringLessThan);

    for (paths.items) |path| {
        const contents = try std.Io.Dir.cwd().readFileAlloc(io, path, allocator, .limited(16 * 1024 * 1024));
        const source = try snapshotProgramSource(allocator, contents) orelse continue;
        const case = CliCase{
            .id = cases.items.len,
            .suite = .snapshot_programs,
            .name = try std.fmt.allocPrint(allocator, "snapshot program: {s}", .{path}),
            .body = .{ .snapshot_program = .{ .snapshot_path = path, .source = source } },
        };
        if (matchesFilters(case, filters)) try cases.append(allocator, case);
    }
}

fn stringLessThan(_: void, a: []const u8, b: []const u8) bool {
    return std.mem.lessThan(u8, a, b);
}

/// The program `roc check` compiles for a snapshot, or null for a snapshot
/// kind that is not source text (REPL sessions, docs, headers, and the rest).
fn snapshotProgramSource(allocator: Allocator, contents: []const u8) Allocator.Error!?[]const u8 {
    const meta = snapshotSection(contents, "# META\n~~~ini\n", "~~~") orelse return null;
    const kind = snapshotMetaType(meta) orelse return null;
    const written_source = snapshotSection(contents, "# SOURCE\n~~~roc\n", "\n~~~\n") orelse return null;
    // An escaped source writes each carriage return as `\r`.
    const source = if (std.mem.find(u8, meta, "source_escapes=true") != null)
        try std.mem.replaceOwned(u8, allocator, written_source, "\\r", "\r")
    else
        written_source;

    if (std.mem.eql(u8, kind, "file")) return source;
    if (std.mem.eql(u8, kind, "snippet")) {
        if (std.mem.find(u8, source, "main!") != null) return source;
        return try std.fmt.allocPrint(allocator, "{s}\n\nmain! = |_| Ok({{}})\n", .{source});
    }
    if (std.mem.eql(u8, kind, "expr")) {
        var program: std.ArrayListUnmanaged(u8) = .empty;
        try program.appendSlice(allocator, "snapshot_value =\n");
        var lines = std.mem.splitScalar(u8, source, '\n');
        while (lines.next()) |line| {
            try program.appendSlice(allocator, "    ");
            try program.appendSlice(allocator, line);
            try program.append(allocator, '\n');
        }
        try program.appendSlice(allocator, "\nmain! = |_| {\n    echo!(Str.inspect(snapshot_value))\n    Ok({})\n}\n");
        return try program.toOwnedSlice(allocator);
    }
    return null;
}

fn snapshotSection(contents: []const u8, open: []const u8, close: []const u8) ?[]const u8 {
    const start = (std.mem.find(u8, contents, open) orelse return null) + open.len;
    const end = std.mem.findPos(u8, contents, start, close) orelse return null;
    return contents[start..end];
}

fn snapshotMetaType(meta: []const u8) ?[]const u8 {
    var lines = std.mem.splitScalar(u8, meta, '\n');
    while (lines.next()) |line| {
        if (std.mem.startsWith(u8, line, "type=")) return std.mem.trim(u8, line["type=".len..], " \r");
    }
    return null;
}

fn appendGlueRuntimeCases(
    allocator: Allocator,
    cases: *std.ArrayListUnmanaged(CliCase),
    filters: []const []const u8,
    glue_options: GlueRunnerOptions,
) CliRunnerError!void {
    for (glue_runtime_platforms) |platform| {
        // The broad glue contract corpus has checked-in musl inputs. The ABI
        // probe additionally owns native macOS and Windows targets so those
        // systems execute the exact cross-language vector boundary matrix.
        if (builtin.os.tag == .linux or std.mem.eql(u8, platform.name, "layout-probe")) {
            inline for (.{ GlueLanguage.zig, GlueLanguage.rust, GlueLanguage.c }) |language| {
                const target: GlueRuntimeTarget = .native;
                const name = try std.fmt.allocPrint(
                    allocator,
                    "glue runtime: {s} {s} [{s}, glue-opt={s}]",
                    .{ language.displayName(), platform.name, target.displayName(), glue_options.execution_mode.cliName() },
                );
                const case = CliCase{
                    .id = cases.items.len,
                    .suite = .glue,
                    .name = name,
                    .body = .{ .glue_runtime = .{
                        .language = language,
                        .platform = platform,
                        .target = target,
                        .execution_mode = glue_options.execution_mode,
                    } },
                };
                if (matchesFilters(case, filters)) {
                    try cases.append(allocator, case);
                }
            }
        }

        inline for (.{ GlueLanguage.zig, GlueLanguage.rust, GlueLanguage.c }) |wasm_language| {
            const wasm_target: GlueRuntimeTarget = .wasm32;
            const wasm_name = try std.fmt.allocPrint(
                allocator,
                "glue runtime: {s} {s} [{s}, glue-opt={s}]",
                .{ wasm_language.displayName(), platform.name, wasm_target.displayName(), glue_options.execution_mode.cliName() },
            );
            const wasm_case = CliCase{
                .id = cases.items.len,
                .suite = .glue,
                .name = wasm_name,
                .body = .{ .glue_runtime = .{
                    .language = wasm_language,
                    .platform = platform,
                    .target = wasm_target,
                    .execution_mode = glue_options.execution_mode,
                } },
            };
            if (matchesFilters(wasm_case, filters)) {
                try cases.append(allocator, wasm_case);
            }
        }
    }
}

fn appendStaticCases(
    allocator: Allocator,
    cases: *std.ArrayListUnmanaged(CliCase),
    source: []const CliCase,
    filters: []const []const u8,
    backends: BackendSelection,
) CliRunnerError!void {
    for (source) |source_case| {
        if (!backends.admits(source_case.backend)) continue;
        if (!matchesFilters(source_case, filters)) continue;
        var case = source_case;
        case.id = cases.items.len;
        try cases.append(allocator, case);
    }
}

fn appendPlatformSpecs(
    allocator: Allocator,
    cases: *std.ArrayListUnmanaged(CliCase),
    platform: platform_config.PlatformConfig,
    opt: OptMode,
    filters: []const []const u8,
) CliRunnerError!void {
    switch (platform.test_apps) {
        .single => |app_name| {
            const roc_file = try std.fmt.allocPrint(allocator, "{s}/{s}", .{ platform.base_dir, app_name });
            const name = try fmtTestName(allocator, roc_file, opt);
            const case = CliCase{
                .id = cases.items.len,
                .suite = .platforms,
                .name = name,
                .backend = opt,
                .body = .{ .platform = .{
                    .roc_file = roc_file,
                    .platform = platform.name,
                    .test_kind = .native_run,
                } },
            };
            if (matchesFilters(case, filters)) {
                try cases.append(allocator, case);
            }
        },
        .spec_list => |io_specs| {
            for (io_specs) |spec| {
                if (skipIoSpecOnHost(spec)) continue;

                const name = try fmtTestName(allocator, spec.roc_file, opt);
                const case = CliCase{
                    .id = cases.items.len,
                    .suite = .platforms,
                    .name = name,
                    .backend = opt,
                    .body = .{ .platform = .{
                        .roc_file = spec.roc_file,
                        .platform = platform.name,
                        .expected_build_stderr_contains = spec.expected_build_stderr_contains,
                        .test_kind = .{ .io_spec = spec.io_spec },
                    } },
                };
                if (matchesFilters(case, filters)) {
                    try cases.append(allocator, case);
                }
            }
        },
        .simple_list => |simple_specs| {
            for (simple_specs) |spec| {
                const name = try fmtTestName(allocator, spec.roc_file, opt);
                const case = CliCase{
                    .id = cases.items.len,
                    .suite = .platforms,
                    .name = name,
                    .backend = opt,
                    .body = .{ .platform = .{
                        .roc_file = spec.roc_file,
                        .platform = platform.name,
                        .test_kind = .native_run,
                    } },
                };
                if (matchesFilters(case, filters)) {
                    try cases.append(allocator, case);
                }
            }
        },
    }
}

fn appendCrossCompilePlatformSpecs(
    allocator: Allocator,
    cases: *std.ArrayListUnmanaged(CliCase),
    platform: platform_config.PlatformConfig,
    target: []const u8,
    filters: []const []const u8,
) CliRunnerError!void {
    switch (platform.test_apps) {
        .single => |app_name| {
            const roc_file = try std.fmt.allocPrint(allocator, "{s}/{s}", .{ platform.base_dir, app_name });
            try appendCrossCompileCase(allocator, cases, platform.name, target, roc_file, &.{}, filters);
        },
        .spec_list => |specs| {
            for (specs) |spec| {
                try appendCrossCompileCase(
                    allocator,
                    cases,
                    platform.name,
                    target,
                    spec.roc_file,
                    spec.expected_build_stderr_contains,
                    filters,
                );
            }
        },
        .simple_list => |specs| {
            for (specs) |spec| {
                try appendCrossCompileCase(allocator, cases, platform.name, target, spec.roc_file, &.{}, filters);
            }
        },
    }
}

fn appendCrossCompileCase(
    allocator: Allocator,
    cases: *std.ArrayListUnmanaged(CliCase),
    platform: []const u8,
    target: []const u8,
    roc_file: []const u8,
    expected_build_stderr_contains: []const []const u8,
    filters: []const []const u8,
) CliRunnerError!void {
    const name = try std.fmt.allocPrint(allocator, "{s} [cross {s}]", .{ roc_file, target });
    const case = CliCase{
        .id = cases.items.len,
        .suite = .platforms,
        .name = name,
        .body = .{ .platform = .{
            .roc_file = roc_file,
            .platform = platform,
            .expected_build_stderr_contains = expected_build_stderr_contains,
            .test_kind = .{ .cross_compile = target },
        } },
    };
    if (matchesFilters(case, filters)) {
        try cases.append(allocator, case);
    }
}

fn skipIoSpecOnHost(spec: @import("fx_test_specs.zig").TestSpec) bool {
    if (spec.skip) return true;
    return spec.skip_on_windows and builtin.os.tag == .windows;
}

fn fmtTestName(allocator: Allocator, roc_file: []const u8, opt: OptMode) CliRunnerError![]const u8 {
    return std.fmt.allocPrint(allocator, "{s} [{s}]", .{ roc_file, opt.cliName() });
}

fn caseRocFile(case: CliCase) ?[]const u8 {
    return switch (case.body) {
        .platform => |platform| platform.roc_file,
        .command => |command| command.roc_file,
        .custom => null,
        .glue_runtime => |runtime| runtime.platform.dir_path,
        .snapshot_program => |program| program.snapshot_path,
    };
}

fn matchesFilters(case: CliCase, filters: []const []const u8) bool {
    if (filters.len == 0) return true;
    for (filters) |f| {
        if (std.mem.find(u8, case.name, f) != null) return true;
        if (std.mem.find(u8, case.suite.cliName(), f) != null) return true;
        if (case.backend) |backend| {
            if (std.mem.find(u8, backend.cliName(), f) != null) return true;
        }
        if (caseRocFile(case)) |roc_file| {
            if (std.mem.find(u8, roc_file, f) != null) return true;
        }
    }
    return false;
}

