    \\    int temp_len = snprintf(temp_path, sizeof(temp_path), "%s.tmp", path);
    \\    if (temp_len < 0 || (size_t)temp_len >= sizeof(temp_path)) return 1;
    \\    FILE *file = fopen(temp_path, "wb");
    \\    if (file == NULL) {
    \\        perror("fopen app");
    \\        return 1;
    \\    }
    \\    fprintf(file,
    \\        "app [Model, main] { pf: platform \"./platform/main.roc\" }\n\n"
