        return failureFromRun(allocator, timer, built, "boxy dev build did not succeed");
    }
    return runRawAndCheck(io, allocator, env, timer, timeout_ms, &.{exe}, env.dirs.work_dir, .{
        .args = &.{},
        .stdout_exact =
        \\Ok(1)
        \\Ok("1")
        \\Err(InvalidJson("Invalid JSON"))
        \\Ok("1")
        \\Ok(1)
        \\Err(InvalidJson("Invalid JSON"))
        \\Ok(["1"])
        \\"1"
        \\{"a":"1"}
        \\[1]
        \\[["1"]]
        \\["1"]
        \\Ok("items=2:7;1;")
        \\Ok("nested=2:2:7;1;;0:;")
        \\Ok("tagged=<7|1|>")
        \\prefixed=#5#1
        \\Ok("ints=5;1;")
        \\Ok("alias=5;1;")
        \\Ok("held=5;1;")
        \\Ok("records=a=5 b=1 ;")
        \\
        ,
    });
