    if (stageEditableApp(io, allocator, env, timer, .{
        .dir_name = "issue_11627_static_data_names",
        .platform = "test/fx-open/platform/main.roc",
        .platform_spelling = "../../fx-open/platform/main.roc",
        .sources = &.{ "test/cli/issue_11627_static_data_names/Lib.roc", "test/cli/issue_11627_static_data_names/main.roc" },
        .app_name = "main.roc",
    }, &app)) |failure| return failure;
    return storeBuildsBehaveIdentically(io, allocator, env, timer, timeout_ms, app, env.dirs.work_dir, "issue_11627", .{
        .uncached_baseline = true,
        .edit_between_builds = true,
        .stdout = "[1, 2]\n[[10, 20]]\n",
    });
}

/// An app whose sources a case copies into its work directory so it can edit
/// them between builds.
const EditableApp = struct {
    /// Directory under the case's work directory that receives the sources.
    dir_name: []const u8,
    /// The platform's path from the repository root.
    platform: []const u8,
    /// How the sources spell the platform path in their headers.
    platform_spelling: []const u8,
    /// Every source file, as paths from the repository root.
    sources: []const []const u8,
    /// The basename of the app module among `sources`.
    app_name: []const u8,
};

/// Runtime-only specialization must not hide semantic obligations from check.
fn customDemandCtfeDiagnostics(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
) ?TestResult {
    const fixtures = [_]struct { path: []const u8, diagnostic: []const u8 }{
        .{ .path = "test/cli/demand_ctfe/RejectedNumeral.roc", .diagnostic = "invalid number" },
        .{ .path = "test/cli/demand_ctfe/NestedLiteral.roc", .diagnostic = "invalid string" },
        .{ .path = "test/cli/demand_ctfe/RejectedDispatch.roc", .diagnostic = "describe" },
        .{ .path = "test/cli/demand_ctfe/EmpiricalMatch.roc", .diagnostic = "This match expression doesn't cover all possible cases." },
        .{ .path = "test/cli/demand_ctfe/UnusedTopLevelExpect.roc", .diagnostic = "This expect failed during compile-time evaluation." },
    };
    for (fixtures) |entry| {
        const fixture = .{ .name = std.fs.path.basename(entry.path), .diagnostic = entry.diagnostic };
        const path = entry.path;
        var app: []const u8 = undefined;
        if (stageEditableApp(io, allocator, env, timer, .{
            .dir_name = fixture.name,
            .platform = "test/fx-open/platform/main.roc",
            .platform_spelling = "../../fx-open/platform/main.roc",
            .sources = &.{path},
            .app_name = fixture.name,
        }, &app)) |failure| return failure;

        // Separate the fixtures' producers. Within each fixture check first
        // publishes its partial work, then each backend consumes that cache.
        const cache = std.fmt.allocPrint(allocator, "{s}/demand-cache-{s}", .{ env.dirs.work_dir, fixture.name }) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate demand cache: {}", .{err});
        var isolated = CaseEnv{
            .dirs = env.dirs,
            .env_map = env.env_map.clone(allocator) catch |err|
                return customInfraFailure(allocator, timer, "failed to clone demand environment: {}", .{err}),
        };
        defer isolated.env_map.deinit();
        isolated.env_map.put("ROC_CACHE_DIR", cache) catch |err|
            return customInfraFailure(allocator, timer, "failed to isolate demand cache: {}", .{err});
        var baseline: ?[]const u8 = null;
        const commands = [_][]const []const u8{
            &.{ "check", "--no-cache", "--no-color" },
            &.{ "check", "--no-color" },
            &.{ "check", "--no-color" },
            &.{ "build", "--opt=dev", "--no-color" },
            &.{ "build", "--no-color" },
        };
        for (commands) |args| {
            const remaining = childCommandTimeoutMs(timer, timeout_ms) orelse
                return timeoutFailure(allocator, timer, .run, "demand fixture timeout exhausted");
            const run = runRocInEnv(io, allocator, &isolated, args, app, .relative, &.{}, null, remaining) catch |err|
                return customInfraFailure(allocator, timer, "demand fixture spawn error: {}", .{err});
            if (processSucceeded(run.term) or std.mem.find(u8, run.stderr, fixture.diagnostic) == null or
                std.mem.find(u8, run.stderr, "panic") != null or std.mem.find(u8, run.stderr, "invariant violated") != null)
            {
                return failureFromRun(allocator, timer, run, "runtime specialization omitted its semantic diagnostic");
            }
            const reports = parityNormalizedReports(allocator, run.stderr) catch |err|
                return customInfraFailure(allocator, timer, "demand diagnostic normalization failed: {}", .{err});
            if (baseline) |expected| {
                if (!std.mem.eql(u8, expected, reports)) return failureFromRun(allocator, timer, run, "check and build changed the specialization diagnostic");
            } else {
                baseline = reports;
            }
        }
    }
    // A literal in a generic definition nothing instantiates is never
    // converted, so it reports nothing.
    var uninstantiated_app: []const u8 = undefined;
    if (stageEditableApp(io, allocator, env, timer, .{
        .dir_name = "demand-uninstantiated",
        .platform = "test/fx-open/platform/main.roc",
        .platform_spelling = "../../fx-open/platform/main.roc",
        .sources = &.{"test/cli/demand_ctfe/UninstantiatedLiteral.roc"},
        .app_name = "UninstantiatedLiteral.roc",
    }, &uninstantiated_app)) |failure| return failure;
    for (0..2) |_| {
        if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
            .args = &.{ "check", "--no-color" },
            .roc_file = uninstantiated_app,
            .stderr_exact = "",
        })) |failure| return failure;
    }
    var runtime_app: []const u8 = undefined;
    if (stageEditableApp(io, allocator, env, timer, .{
        .dir_name = "demand-runtime-only",
        .platform = "test/fx-open/platform/main.roc",
        .platform_spelling = "../../fx-open/platform/main.roc",
        .sources = &.{"test/cli/demand_ctfe/RuntimeOnly.roc"},
        .app_name = "RuntimeOnly.roc",
    }, &runtime_app)) |failure| return failure;
    for (0..2) |_| {
        if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
            .args = &.{ "check", "--no-color" },
            .roc_file = runtime_app,
            .stderr_exact = "",
        })) |failure| return failure;
    }
    for ([_]bool{ true, false }) |dev| {
        const exe = std.fmt.allocPrint(allocator, "{s}/demand-runtime-{s}", .{ env.dirs.work_dir, if (dev) "dev" else "llvm" }) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate demand executable: {}", .{err});
        const out_arg = outputArg(allocator, exe) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate demand output argument: {}", .{err});
        if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
            .args = if (dev) &.{ "build", "--opt=dev", "--no-color", out_arg } else &.{ "build", "--no-color", out_arg },
            .roc_file = runtime_app,
            .stderr_exact = "",
        })) |failure| return failure;
        // Two runtime inputs ensure the reachable helper is not replaced by
        // the result of one accidental compile-time invocation.
        for ([_][]const []const u8{ &.{exe}, &.{ exe, "one", "two" } }) |argv| {
            if (runRawAndCheck(io, allocator, env, timer, timeout_ms, argv, env.dirs.work_dir, .{
                .args = &.{},
                .stdout_exact = "runtime only correct\n",
                .stderr_exact = "",
            })) |failure| return failure;
        }
    }
    return null;
}

/// A helper that reads a checked constant runs while evaluating a constant and
/// at runtime. Uncached, cold and warm dev builds of each app share one cache
/// and must all link and print the same result.
fn customCtfeStaticCacheRuntime(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
) ?TestResult {
    const apps = [_]struct { path: []const u8, stdout: []const u8 }{
        .{ .path = "test/cli/ctfe_static_cache/CompileTimeAndRuntime.roc", .stdout = "237\n" },
        .{ .path = "test/cli/ctfe_static_cache/RuntimeSeed.roc", .stdout = "472\n" },
    };
    for (apps) |entry| {
        const name = std.fs.path.basename(entry.path);
        var app: []const u8 = undefined;
        if (stageEditableApp(io, allocator, env, timer, .{
            .dir_name = name,
            .platform = "test/fx/platform/main.roc",
            .platform_spelling = "../../fx/platform/main.roc",
            .sources = &.{ "test/cli/ctfe_static_cache/Static.roc", entry.path },
            .app_name = name,
        }, &app)) |failure| return failure;
        const cache = std.fmt.allocPrint(allocator, "{s}/static-cache-{s}", .{ env.dirs.work_dir, name }) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate cache root: {}", .{err});
        var isolated = CaseEnv{
            .dirs = env.dirs,
            .env_map = env.env_map.clone(allocator) catch |err|
                return customInfraFailure(allocator, timer, "failed to clone the environment: {}", .{err}),
        };
        defer isolated.env_map.deinit();
        isolated.env_map.put("ROC_CACHE_DIR", cache) catch |err|
            return customInfraFailure(allocator, timer, "failed to isolate the cache: {}", .{err});
        for ([_][]const u8{ "uncached", "cold", "warm" }) |label| {
            const exe = std.fmt.allocPrint(allocator, "{s}/static-{s}-{s}", .{ env.dirs.work_dir, name, label }) catch |err|
                return customInfraFailure(allocator, timer, "failed to allocate executable path: {}", .{err});
            const out_arg = outputArg(allocator, exe) catch |err|
                return customInfraFailure(allocator, timer, "failed to allocate output argument: {}", .{err});
            const uncached = std.mem.eql(u8, label, "uncached");
            if (runRocAndCheck(io, allocator, &isolated, timer, timeout_ms, .{
                .args = if (uncached) &.{ "build", "--opt=dev", "--no-cache", "--no-color", out_arg } else &.{ "build", "--opt=dev", "--no-color", out_arg },
                .roc_file = app,
            })) |failure| return failure;
            if (runRawAndCheck(io, allocator, env, timer, timeout_ms, &.{exe}, env.dirs.work_dir, .{
                .args = &.{},
                .stdin = "ab\n",
                .stdout_exact = entry.stdout,
            })) |failure| return failure;
        }
    }
    return null;
}

/// Compile-time evaluation runs each value after the values it reads: a value
/// read through a callback, mutually recursive functions, and a guarded
/// failure that is not reached all check and run their tests, and a guarded
/// failure that is reached and an eager value cycle report the same
/// diagnostics, uncached, seeding the cache, repeated, and after an edit.
fn customCtfeEvaluationOrder(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
) ?TestResult {
    const fixtures = [_][]const u8{ "Forward.roc", "Functions.roc", "Guarded.roc", "FailedGuard.roc", "Cycle.roc" };
    var sources: [fixtures.len][]const u8 = undefined;
    for (fixtures, &sources) |name, *source| {
        source.* = std.fmt.allocPrint(allocator, "test/cli/ctfe_evaluation_order/{s}", .{name}) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate fixture path: {}", .{err});
    }
    var first: []const u8 = undefined;
    if (stageEditableApp(io, allocator, env, timer, .{
        .dir_name = "ctfe_evaluation_order",
        .platform = "test/fx-open/platform/main.roc",
        .platform_spelling = "../../fx-open/platform/main.roc",
        .sources = &sources,
        .app_name = fixtures[0],
    }, &first)) |failure| return failure;
    const dir = std.fs.path.dirname(first).?;
    var isolated = CaseEnv{
        .dirs = env.dirs,
        .env_map = env.env_map.clone(allocator) catch |err|
            return customInfraFailure(allocator, timer, "failed to clone the environment: {}", .{err}),
    };
    defer isolated.env_map.deinit();
    const cache = std.fmt.allocPrint(allocator, "{s}/evaluation-order-cache", .{env.dirs.work_dir}) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate cache root: {}", .{err});
    isolated.env_map.put("ROC_CACHE_DIR", cache) catch |err|
        return customInfraFailure(allocator, timer, "failed to isolate the cache: {}", .{err});

    for (fixtures[0..3]) |name| {
        const path = std.fs.path.join(allocator, &.{ dir, name }) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate fixture path: {}", .{err});
        for ([_][]const []const u8{ &.{ "check", "--no-cache", "--no-color" }, &.{ "check", "--no-color" }, &.{ "check", "--no-color" } }) |args| {
            if (runRocAndCheck(io, allocator, &isolated, timer, timeout_ms, .{ .args = args, .roc_file = path })) |failure| return failure;
        }
        // Editing the module makes its evaluation run again rather than
        // restore the checked result before running its test natively.
        const source = std.Io.Dir.cwd().readFileAlloc(io, path, allocator, .limited(1024 * 1024)) catch |err|
            return customInfraFailure(allocator, timer, "failed to read fixture: {}", .{err});
        const edited = std.fmt.allocPrint(allocator, "{s}\n# Check the same dependencies in an edited module.\n", .{source}) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate edit: {}", .{err});
        std.Io.Dir.cwd().writeFile(io, .{ .sub_path = path, .data = edited }) catch |err|
            return customInfraFailure(allocator, timer, "failed to edit fixture: {}", .{err});
        if (runRocAndCheck(io, allocator, &isolated, timer, timeout_ms, .{
            .args = &.{ "test", "--opt=dev", "--no-color" },
            .roc_file = path,
            .contains = &.{.{ .stream = .stdout, .text = "All (1) tests passed" }},
        })) |failure| return failure;
    }

    const failing = [_]struct { name: []const u8, diagnostic: []const u8 }{
        .{ .name = "FailedGuard.roc", .diagnostic = "I64 division by zero" },
        .{ .name = "Cycle.roc", .diagnostic = "circular value definition" },
    };
    for (failing) |entry| {
        const path = std.fs.path.join(allocator, &.{ dir, entry.name }) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate fixture path: {}", .{err});
        var baseline: ?std.process.RunResult = null;
        for ([_][]const []const u8{ &.{ "check", "--no-cache", "--no-color" }, &.{ "check", "--no-color" }, &.{ "check", "--no-color" } }) |args| {
            const run = switch (captureRocRun(io, allocator, &isolated, timer, timeout_ms, .{ .args = args, .roc_file = path, .exit = .failure })) {
                .result => |run| run,
                .failure => |failure| return failure,
            };
            if (baseline) |expected| {
                if (!std.mem.eql(u8, expected.stdout, run.stdout) or !std.mem.eql(u8, expected.stderr, run.stderr)) {
                    return failureFromRun(allocator, timer, run, "a cached check changed its compile-time diagnostic");
                }
            } else {
                if (std.mem.find(u8, run.stderr, entry.diagnostic) == null) return failureFromRun(allocator, timer, run, "an uncached check did not report its compile-time diagnostic");
                baseline = run;
            }
        }
    }
    return null;
}

/// A cached ownership anchor still supplies nominal declarations to fresh CTFE.
/// A cache hit supplies code and capture metadata, never the earlier caller's
/// captured values. A producer-body edit must also change the called code.
fn customCtfeCachedFunctionUnits(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
) ?TestResult {
    const dir = createWorkSubdir(io, allocator, env, "cached_function_units") catch |err|
        return customInfraFailure(allocator, timer, "failed to create the case directory: {}", .{err});
    const cache = std.fs.path.join(allocator, &.{ dir, "cache" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate the cache root: {}", .{err});
    const main_path = std.fs.path.join(allocator, &.{ dir, "Main.roc" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate the entrypoint: {}", .{err});
    var isolated = CaseEnv{ .dirs = env.dirs, .env_map = env.env_map.clone(allocator) catch |err|
        return customInfraFailure(allocator, timer, "failed to clone the environment: {}", .{err}) };
    defer isolated.env_map.deinit();
    isolated.env_map.put("ROC_CACHE_DIR", cache) catch |err|
        return customInfraFailure(allocator, timer, "failed to isolate the cache: {}", .{err});
    for ([_]struct { capture: u8, extra: u8 }{
        .{ .capture = 7, .extra = 0 },
        .{ .capture = 7, .extra = 0 },
        .{ .capture = 8, .extra = 0 },
        .{ .capture = 8, .extra = 0 },
        .{ .capture = 8, .extra = 1 },
        .{ .capture = 8, .extra = 1 },
    }) |step| {
        const producer = std.fmt.allocPrint(
            allocator,
            "Factory := [].{{\n    make : I64 -> (I64 -> I64)\n    make = |captured| |value| captured + value + {d}\n}}\n",
            .{step.extra},
        ) catch |err| return customInfraFailure(allocator, timer, "failed to format producer: {}", .{err});
        defer allocator.free(producer);
        if (writeCaseFile(io, allocator, timer, dir, "Factory.roc", producer)) |failure| return failure;
        const caller = std.fmt.allocPrint(
            allocator,
            "import Factory\nsaved = Factory.make({d})\nexpect saved(5) == {d}\n",
            .{ step.capture, step.capture + 5 + step.extra },
        ) catch |err| return customInfraFailure(allocator, timer, "failed to format caller: {}", .{err});
        defer allocator.free(caller);
        if (writeCaseFile(io, allocator, timer, dir, "Main.roc", caller)) |failure| return failure;
        if (runRocAndCheck(io, allocator, &isolated, timer, timeout_ms, .{
            .args = &.{ "test", "--opt=dev", "--specialize=no", "--no-color", "--jobs=2" },
            .roc_file = main_path,
            .contains = &.{.{ .stream = .stdout, .text = "All (1) tests passed" }},
            .stderr_exact = "",
        })) |failure| return failure;
    }
    return null;
}

/// An unchanged generic module's cached needs bind to its current checked
/// snapshot after an implementation-only edit in a nongeneric dependency.
fn customCtfeCachedNeedsDependencies(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
) ?TestResult {
    const dir = createWorkSubdir(io, allocator, env, "cached_needs_dependencies") catch |err|
        return customInfraFailure(allocator, timer, "failed to create the case directory: {}", .{err});
    const cache = std.fs.path.join(allocator, &.{ dir, "cache" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate the cache root: {}", .{err});
    const main_path = std.fs.path.join(allocator, &.{ dir, "Main.roc" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate the entrypoint: {}", .{err});
    var isolated = CaseEnv{ .dirs = env.dirs, .env_map = env.env_map.clone(allocator) catch |err|
        return customInfraFailure(allocator, timer, "failed to clone the environment: {}", .{err}) };
    defer isolated.env_map.deinit();
    isolated.env_map.put("ROC_CACHE_DIR", cache) catch |err|
        return customInfraFailure(allocator, timer, "failed to isolate the cache: {}", .{err});
    if (writeCaseFile(io, allocator, timer, dir, "Factory.roc",
        \\import Dependency
        \\Factory := [].{
        \\    make : a -> ({} -> a)
        \\    make = |captured| |token| {
        \\        _ = Dependency.touch(token)
        \\        captured
        \\    }
        \\}
        \\
    )) |failure| return failure;
    if (writeCaseFile(io, allocator, timer, dir, "Main.roc",
        \\import Factory
        \\saved = Factory.make("captured")
        \\expect saved({}) == "captured"
        \\
    )) |failure| return failure;
    const dependency =
        \\Dependency := [].{
        \\    touch : {} -> {}
        \\    touch = |value| value
        \\}
        \\
    ;
    for ([_][]const u8{ dependency, dependency, dependency ++ "# A new checked identity, with the same exported interface.\n", dependency }) |source| {
        if (writeCaseFile(io, allocator, timer, dir, "Dependency.roc", source)) |failure| return failure;
        if (runRocAndCheck(io, allocator, &isolated, timer, timeout_ms, .{
            .args = &.{ "test", "--opt=dev", "--specialize=no", "--no-color", "--jobs=2" },
            .roc_file = main_path,
            .contains = &.{.{ .stream = .stdout, .text = "All (1) tests passed" }},
            .stderr_exact = "",
        })) |failure| return failure;
    }
    return null;
}

/// Preserve local override callables through both table-producer domains,
/// through a caller edit with a warm producer, and through uncached evaluation.
fn customCtfeStoredScopedCaptures(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
) ?TestResult {
    const dir = createWorkSubdir(io, allocator, env, "stored_scoped_captures") catch |err|
        return customInfraFailure(allocator, timer, "failed to create fixture directory: {}", .{err});
    const cache = std.fs.path.join(allocator, &.{ dir, "cache" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate cache path: {}", .{err});
    var isolated = CaseEnv{ .dirs = env.dirs, .env_map = env.env_map.clone(allocator) catch |err|
        return customInfraFailure(allocator, timer, "failed to clone environment: {}", .{err}) };
    defer isolated.env_map.deinit();
    isolated.env_map.put("ROC_CACHE_DIR", cache) catch |err|
        return customInfraFailure(allocator, timer, "failed to isolate cache: {}", .{err});
    for ([_][]const u8{ "Factory.roc", "Direct.roc", "Main.roc" }) |name| {
        const from = std.fs.path.join(allocator, &.{ project_root_path, "test/cli/boxy_stored_scoped_captures", name }) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate source path: {}", .{err});
        defer allocator.free(from);
        const source = std.Io.Dir.cwd().readFileAlloc(io, from, allocator, .limited(1024 * 1024)) catch |err|
            return customInfraFailure(allocator, timer, "failed to read fixture: {}", .{err});
        defer allocator.free(source);
        if (writeCaseFile(io, allocator, timer, dir, name, source)) |failure| return failure;
    }
    const direct = std.fs.path.join(allocator, &.{ dir, "Direct.roc" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate direct control path: {}", .{err});
    if (runRocAndCheck(io, allocator, &isolated, timer, timeout_ms, .{
        .args = &.{ "test", "--opt=dev", "--specialize=no", "--no-color", "--jobs=2", "--no-cache" },
        .roc_file = direct,
        .contains = &.{.{ .stream = .stdout, .text = "All (2) tests passed" }},
        .stderr_exact = "",
    })) |failure| return failure;
    const main_path = std.fs.path.join(allocator, &.{ dir, "Main.roc" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate stored control path: {}", .{err});
    for ([_]u32{ 7, 7, 11, 11 }) |captured| {
        const source = std.fmt.allocPrint(
            allocator,
            "import Factory\nsaved = Factory.make({d}.U64)\nclosed_saved = Factory.closed({{}})\nexpect saved({{}}) == \"Local({d})\"\nexpect closed_saved({{}}) == \"Local(7)\"\n",
            .{ captured, captured },
        ) catch |err| return customInfraFailure(allocator, timer, "failed to format caller: {}", .{err});
        defer allocator.free(source);
        if (writeCaseFile(io, allocator, timer, dir, "Main.roc", source)) |failure| return failure;
        if (runRocAndCheck(io, allocator, &isolated, timer, timeout_ms, .{
            .args = &.{ "test", "--opt=dev", "--specialize=no", "--no-color", "--jobs=2" },
            .roc_file = main_path,
            .contains = &.{.{ .stream = .stdout, .text = "All (2) tests passed" }},
            .stderr_exact = "",
        })) |failure| return failure;
    }
    return runRocAndCheck(io, allocator, &isolated, timer, timeout_ms, .{
        .args = &.{ "test", "--opt=dev", "--specialize=no", "--no-color", "--jobs=2", "--no-cache" },
        .roc_file = main_path,
        .contains = &.{.{ .stream = .stdout, .text = "All (2) tests passed" }},
        .stderr_exact = "",
    });
}

fn customCtfeCachedNominalAnchor(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
) ?TestResult {
    const dir = createWorkSubdir(io, allocator, env, "cached_nominal_anchor") catch |err|
        return customInfraFailure(allocator, timer, "failed to create the case directory: {}", .{err});
    const cache = std.fs.path.join(allocator, &.{ dir, "cache" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate the cache root: {}", .{err});
    const main_path = std.fs.path.join(allocator, &.{ dir, "Main.roc" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate the entrypoint: {}", .{err});
    var isolated = CaseEnv{ .dirs = env.dirs, .env_map = env.env_map.clone(allocator) catch |err|
        return customInfraFailure(allocator, timer, "failed to clone the environment: {}", .{err}) };
    defer isolated.env_map.deinit();
    isolated.env_map.put("ROC_CACHE_DIR", cache) catch |err|
        return customInfraFailure(allocator, timer, "failed to isolate the cache: {}", .{err});
    if (writeCaseFile(io, allocator, timer, dir, "Main.roc", "import Anchor\nimport Consumer\n")) |failure| return failure;
    if (writeCaseFile(io, allocator, timer, dir, "Anchor.roc",
        \\Anchor := { value : I64 }.{
        \\    make : I64 -> Anchor
        \\    make = |n| { value: n }
        \\    get : Anchor -> I64
        \\    get = |r| r.value
        \\}
        \\expect Anchor.get(Anchor.make(1)) == 1
        \\
    )) |failure| return failure;
    const consumer =
        \\Consumer := []
        \\import Anchor
        \\value = Anchor.make(42)
        \\
    ;
    // Anchor owns the test program, but after the edit its checked artifact
    // is cached and it has no pending roots. Consumer's fresh constant still
    // needs Anchor's nominal backing when selecting its CTFE evaluator.
    for ([_][]const u8{
        consumer ++ "expect Anchor.get(value) == 42\n",
        consumer ++ "expect Anchor.get(value) == 42\n",
        consumer ++ "expect Anchor.get(value) == 41 + 1\n",
        consumer ++ "expect Anchor.get(value) == 41 + 1\n",
    }) |source| {
        if (writeCaseFile(io, allocator, timer, dir, "Consumer.roc", source)) |failure| return failure;
        if (runRocAndCheck(io, allocator, &isolated, timer, timeout_ms, .{
            .args = &.{ "test", "--opt=dev", "--specialize=no", "--no-color" },
            .roc_file = main_path,
            .contains = &.{.{ .stream = .stdout, .text = "All (2) tests passed" }},
            .stderr_exact = "",
        })) |failure| return failure;
    }
    return null;
}

/// Compile-time results read from a cache other commands filled match the
/// uncached ones: tests of callable values a checked producer froze pass when
/// only their consumer is evaluated again, and a compile-time failure inside a
/// helper a runtime build cached reports the same diagnostic as an uncached
/// check.
fn customCtfeCacheMixing(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
) ?TestResult {
    var isolated = CaseEnv{
        .dirs = env.dirs,
        .env_map = env.env_map.clone(allocator) catch |err|
            return customInfraFailure(allocator, timer, "failed to clone the environment: {}", .{err}),
    };
    defer isolated.env_map.deinit();
    const cache = std.fmt.allocPrint(allocator, "{s}/cache-mixing-cache", .{env.dirs.work_dir}) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate cache root: {}", .{err});
    isolated.env_map.put("ROC_CACHE_DIR", cache) catch |err|
        return customInfraFailure(allocator, timer, "failed to isolate the cache: {}", .{err});

    // The callable fixture is a headerless test entrypoint; a nominal module
    // header makes `check` treat the staged copy as a library.
    var callable: []const u8 = undefined;
    if (stageEditableApp(io, allocator, env, timer, .{
        .dir_name = "cache_mixing_callable",
        .platform = "test/fx-open/platform/main.roc",
        .platform_spelling = "../../fx-open/platform/main.roc",
        .sources = &.{ "test/cli/issue_11344_shared_ctfe/CallableHelper.roc", "test/cli/issue_11344_shared_ctfe/callable.roc" },
        .app_name = "callable.roc",
    }, &callable)) |failure| return failure;
    const callable_source = std.Io.Dir.cwd().readFileAlloc(io, callable, allocator, .limited(1024 * 1024)) catch |err|
        return customInfraFailure(allocator, timer, "failed to read callable fixture: {}", .{err});
    if (std.mem.count(u8, callable_source, "import CallableHelper\n") != 1) return customInfraFailure(allocator, timer, "callable fixture changed its import", .{});
    const library = std.mem.replaceOwned(u8, allocator, callable_source, "import CallableHelper\n", "import CallableHelper\n\nCallable := [].{}\n") catch |err|
        return customInfraFailure(allocator, timer, "failed to add a module header: {}", .{err});
    const library_path = std.fs.path.join(allocator, &.{ std.fs.path.dirname(callable).?, "Callable.roc" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate library path: {}", .{err});
    // On a case-insensitive file system `Callable.roc` would otherwise replace
    // the staged entrypoint's contents under its lowercase spelling.
    std.Io.Dir.cwd().deleteFile(io, callable) catch |err|
        return customInfraFailure(allocator, timer, "failed to remove the staged entrypoint: {}", .{err});
    std.Io.Dir.cwd().writeFile(io, .{ .sub_path = library_path, .data = library }) catch |err|
        return customInfraFailure(allocator, timer, "failed to write library: {}", .{err});
    if (runRocAndCheck(io, allocator, &isolated, timer, timeout_ms, .{ .args = &.{ "check", "--no-color" }, .roc_file = library_path })) |failure| return failure;
    // Editing only the consumer evaluates it again against its producer's
    // frozen values before the tests run natively.
    const edited = std.fmt.allocPrint(allocator, "{s}\n# Check the consumer again without changing its imported callable.\n", .{library}) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate edit: {}", .{err});
    std.Io.Dir.cwd().writeFile(io, .{ .sub_path = library_path, .data = edited }) catch |err|
        return customInfraFailure(allocator, timer, "failed to edit library: {}", .{err});
    for (0..2) |_| {
        if (runRocAndCheck(io, allocator, &isolated, timer, timeout_ms, .{
            .args = &.{ "test", "--opt=dev", "--no-color" },
            .roc_file = library_path,
            .contains = &.{.{ .stream = .stdout, .text = "All (6) tests passed" }},
        })) |failure| return failure;
    }

    // A runtime build caches the code of the helpers it reads; a check of a
    // module that calls them with inputs that fail at compile time must report
    // exactly what an uncached check does.
    var seed: []const u8 = undefined;
    if (stageEditableApp(io, allocator, env, timer, .{
        .dir_name = "cache_mixing_static",
        .platform = "test/fx/platform/main.roc",
        .platform_spelling = "../../fx/platform/main.roc",
        .sources = &.{ "test/cli/ctfe_static_cache/Static.roc", "test/cli/ctfe_static_cache/RuntimeSeed.roc", "test/cli/ctfe_static_cache/Overflow.roc", "test/cli/ctfe_static_cache/FailedGuard.roc" },
        .app_name = "RuntimeSeed.roc",
    }, &seed)) |failure| return failure;
    const seed_exe = std.fmt.allocPrint(allocator, "{s}/cache-mixing-seed", .{env.dirs.work_dir}) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate executable path: {}", .{err});
    const seed_out = outputArg(allocator, seed_exe) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate output argument: {}", .{err});
    if (runRocAndCheck(io, allocator, &isolated, timer, timeout_ms, .{ .args = &.{ "build", "--opt=dev", "--no-color", seed_out }, .roc_file = seed })) |failure| return failure;
    const failing = [_]struct { name: []const u8, diagnostic: []const u8 }{
        .{ .name = "Overflow.roc", .diagnostic = "Integer addition overflowed" },
        .{ .name = "FailedGuard.roc", .diagnostic = "I64 division by zero" },
    };
    for (failing) |entry| {
        const path = std.fs.path.join(allocator, &.{ std.fs.path.dirname(seed).?, entry.name }) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate fixture path: {}", .{err});
        var baseline: ?std.process.RunResult = null;
        for ([_][]const []const u8{ &.{ "check", "--no-cache", "--no-color" }, &.{ "check", "--no-color" }, &.{ "check", "--no-color" } }) |args| {
            const run = switch (captureRocRun(io, allocator, &isolated, timer, timeout_ms, .{ .args = args, .roc_file = path, .exit = .failure })) {
                .result => |run| run,
                .failure => |failure| return failure,
            };
            if (baseline) |expected| {
                if (!std.mem.eql(u8, expected.stdout, run.stdout) or !std.mem.eql(u8, expected.stderr, run.stderr)) {
                    return failureFromRun(allocator, timer, run, "a cached check changed a compile-time failure's source or classification");
                }
            } else {
                if (std.mem.find(u8, run.stderr, entry.diagnostic) == null or std.mem.find(u8, run.stderr, "module Static") == null) {
                    return failureFromRun(allocator, timer, run, "an uncached check did not report the helper's compile-time failure");
                }
                baseline = run;
            }
        }
    }
    return null;
}

fn stageEditableApp(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, app: EditableApp, staged_app: *[]const u8) ?TestResult {
    const staged_dir = std.fs.path.join(allocator, &.{ env.dirs.work_dir, app.dir_name }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate staged app dir: {}", .{err});
    std.Io.Dir.cwd().createDirPath(io, staged_dir) catch |err|
        return customInfraFailure(allocator, timer, "failed to create {s}: {}", .{ staged_dir, err });
    const platform_path = absoluteFromProjectRoot(allocator, app.platform) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate platform path: {}", .{err});
    const platform_relative = std.fs.path.relative(allocator, project_root_path, null, staged_dir, platform_path) catch |err|
        return customInfraFailure(allocator, timer, "failed to relate the platform path: {}", .{err});
    // Windows accepts forward slashes, which need no escaping in Roc strings.
    if (builtin.os.tag == .windows) std.mem.replaceScalar(u8, platform_relative, '\\', '/');
    for (app.sources) |source_path| {
        const name = std.fs.path.basename(source_path);
        const from = absoluteFromProjectRoot(allocator, source_path) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate app source path: {}", .{err});
        const source = std.Io.Dir.cwd().readFileAlloc(io, from, allocator, .limited(1024 * 1024)) catch |err|
            return customInfraFailure(allocator, timer, "failed to read {s}: {}", .{ from, err });
        const staged = std.mem.replaceOwned(u8, allocator, source, app.platform_spelling, platform_relative) catch |err|
            return customInfraFailure(allocator, timer, "failed to rewrite the platform path: {}", .{err});
        const to = std.fs.path.join(allocator, &.{ staged_dir, name }) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate staged path: {}", .{err});
        std.Io.Dir.cwd().writeFile(io, .{ .sub_path = to, .data = staged }) catch |err|
            return customInfraFailure(allocator, timer, "failed to write {s}: {}", .{ to, err });
    }
    staged_app.* = std.fs.path.join(allocator, &.{ staged_dir, app.app_name }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate staged app path: {}", .{err});
    return null;
}

/// Expected cache consumption and behavior across store builds.
const StoreExpectations = struct {
    extra_args: []const []const u8 = &.{},
    /// Append a comment to the app between the builds, so the second build
    /// checks it again instead of reusing its cached checked artifact.
    edit_between_builds: bool = false,
    /// Change an evaluated expression as well as the comment. A comment alone
    /// can reuse stored values and never demand the procedure being tested.
    source_edit: ?struct { from: []const u8, to: []const u8 } = null,
    /// Root debug output must appear once on every build, including cache reuse.
    compile_debug: ?[]const u8 = null,
    /// An undemanded root must produce no observation.
    /// Run an uncached build before populating the store.
    uncached_baseline: bool = false,
    /// Require every execution to produce this exact output.
    stdout: ?[]const u8 = null,
    stderr: ?[]const u8 = null,
};

/// Builds `roc_file` twice with the object cache on under the case's cache
/// root, optionally after an uncached baseline. Requires the selected build
/// to report pack hits and every execution to succeed and behave identically.
fn storeBuildsBehaveIdentically(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
    roc_file: []const u8,
    out_dir: []const u8,
    prefix: []const u8,
    expect: StoreExpectations,
) ?TestResult {
    const store_exes: []const []const u8 = if (expect.uncached_baseline) &.{ "uncached", "a", "b" } else &.{ "a", "b" };
    var store_runs: [3]std.process.RunResult = undefined;
    for (store_exes, 0..) |name, index| {
        const exe = std.fmt.allocPrint(allocator, "{s}/{s}_{s}", .{ out_dir, prefix, name }) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate output path: {}", .{err});
        const out_arg = outputArg(allocator, exe) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate output arg: {}", .{err});
        const build_timeout = childCommandTimeoutMs(timer, timeout_ms) orelse
            return timeoutFailure(allocator, timer, .run, "case timeout exhausted before a store build");
        const last = index == store_exes.len - 1;
        if (last and expect.edit_between_builds) {
            const source = std.Io.Dir.cwd().readFileAlloc(io, roc_file, allocator, .limited(1024 * 1024)) catch |err|
                return customInfraFailure(allocator, timer, "failed to read {s}: {}", .{ roc_file, err });
            const changed_source = if (expect.source_edit) |edit|
                std.mem.replaceOwned(u8, allocator, source, edit.from, edit.to) catch |err|
                    return customInfraFailure(allocator, timer, "failed to edit the compile-time expression: {}", .{err})
            else
                source;
            const edited = std.fmt.allocPrint(allocator, "{s}\n# Edited between builds, so this build checks the app again.\n", .{changed_source}) catch |err|
                return customInfraFailure(allocator, timer, "failed to allocate the edited app: {}", .{err});
            std.Io.Dir.cwd().writeFile(io, .{ .sub_path = roc_file, .data = edited }) catch |err|
                return customInfraFailure(allocator, timer, "failed to write {s}: {}", .{ roc_file, err });
        }
        const build_args: []const []const u8 = if (expect.uncached_baseline and index == 0)
            &.{ "build", "--no-cache", "--opt=dev", out_arg }
        else
            &.{ "build", "--opt=dev", out_arg };
        const all_args = std.mem.concat(allocator, []const u8, &.{ build_args, expect.extra_args }) catch |err|
            return customInfraFailure(allocator, timer, "build arguments: {}", .{err});
        const built = runRocInEnv(io, allocator, env, all_args, roc_file, .relative, &.{}, null, build_timeout) catch |err|
            return customInfraFailure(allocator, timer, "store build spawn error: {}", .{err});
        if (!processSucceeded(built.term) or std.mem.find(u8, built.stdout, "successfully building") == null or std.mem.find(u8, built.stderr, "panic") != null) {
            return failureFromRun(allocator, timer, built, "build with the object cache did not succeed");
        }
        if (expect.compile_debug) |message| {
            if (std.mem.count(u8, built.stderr, message) != 1) {
                return failureFromRun(allocator, timer, built, "compile-time debug output was not preserved exactly once");
            }
        }
        const exe_timeout = childCommandTimeoutMs(timer, timeout_ms) orelse
            return timeoutFailure(allocator, timer, .run, "case timeout exhausted before running a store build");
        store_runs[index] = runRawInEnv(io, allocator, env, &.{exe}, env.dirs.work_dir, "", exe_timeout) catch |err|
            return customInfraFailure(allocator, timer, "store program spawn error: {}", .{err});
    }
    for (store_runs[0..store_exes.len]) |run| {
        if (!processSucceeded(run.term) or !std.mem.eql(u8, store_runs[0].stdout, run.stdout)) {
            return failureFromRun(allocator, timer, run, "program served from the object cache failed or behaves differently from the baseline");
        }
        if (expect.stdout) |expected| if (!std.mem.eql(u8, expected, run.stdout)) {
            return failureFromRun(allocator, timer, run, "object-cache program output disagrees with the expected result");
        };
        if (expect.stderr) |expected| if (!std.mem.eql(u8, expected, run.stderr)) {
            return failureFromRun(allocator, timer, run, "object-cache program stderr disagrees with the expected result");
        };
    }
    return null;
}

/// Read one exact counter from its named diagnostic group. Missing counters
/// are not zero: a test must fail when instrumentation was not enabled.
fn timingCounter(stderr: []const u8, group: []const u8, counter: []const u8) ?u64 {
    var lines = std.mem.splitScalar(u8, stderr, '\n');
    while (lines.next()) |line| {
        if (!std.mem.eql(u8, std.mem.trim(u8, line, " \r"), group)) continue;
        while (lines.next()) |row| {
            if (!std.mem.startsWith(u8, row, "      ")) return null;
            const text = std.mem.trim(u8, row, " \r");
            if (!std.mem.startsWith(u8, text, counter)) continue;
            const rest = text[counter.len..];
            if (rest.len == 0 or rest[0] != ' ') continue;
            return std.fmt.parseInt(u64, std.mem.trim(u8, rest, " "), 10) catch null;
        }
    }
    return null;
}

test "Monotype work counter requires the exact group and counter" {
    const text = "  Runtime Monotype body + dispatch\n      Body contexts created 99\n  Shared Monotype body + dispatch\n      Body contexts created     42\n";
    try std.testing.expectEqual(@as(?u64, 42), timingCounter(text, "Shared Monotype body + dispatch", "Body contexts created"));
    try std.testing.expectEqual(@as(?u64, null), timingCounter(text, "Missing", "Body contexts created"));
    try std.testing.expectEqual(@as(?u64, null), timingCounter(text, "Shared Monotype body + dispatch", "Body contexts"));
}

fn validateWasmOutput(
    io: std.Io,
    allocator: Allocator,
    timer: *harness.Timer,
    path: []const u8,
) ?TestResult {
    const wasm_bytes = std.Io.Dir.cwd().readFileAlloc(io, path, allocator, .unlimited) catch |err|
        return customInfraFailure(allocator, timer, "failed to read wasm output {s}: {}", .{ path, err });
    defer allocator.free(wasm_bytes);

    var module_def = bytebox.createModuleDefinition(allocator, .{ .debug_name = "cli_wasm_output" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to create wasm validator: {}", .{err});
    defer module_def.destroy();
    module_def.decode(wasm_bytes) catch |err|
        return customFailure(allocator, timer, "generated invalid wasm {s}: {}", .{ path, err });
    return null;
}

/// Fail unless the wasm module at `path` uses nothing past WebAssembly 1.0:
/// no instruction, value type, multiple result, or block signature from a
/// later proposal.
fn validateWasm10Output(
    io: std.Io,
    allocator: Allocator,
    timer: *harness.Timer,
    path: []const u8,
) ?TestResult {
    const wasm_bytes = std.Io.Dir.cwd().readFileAlloc(io, path, allocator, .unlimited) catch |err|
        return customInfraFailure(allocator, timer, "failed to read wasm output {s}: {}", .{ path, err });
    defer allocator.free(wasm_bytes);
    var module_def = bytebox.createModuleDefinition(allocator, .{ .debug_name = "cli_wasm_1_0_output" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to create wasm validator: {}", .{err});
    defer module_def.destroy();
    module_def.decode(wasm_bytes) catch |err|
        return customFailure(allocator, timer, "generated invalid wasm {s}: {}", .{ path, err });
    if (wasm10Violation(module_def)) |violation| {
        return customFailure(allocator, timer, "{s} is not WebAssembly 1.0: {s}", .{ path, violation });
    }
    return null;
}

fn wasm10ValType(vt: bytebox.ValType) bool {
    return switch (vt) {
        .I32, .I64, .F32, .F64 => true,
        .V128, .FuncRef, .ExternRef => false,
    };
}

/// What in a decoded module is past WebAssembly 1.0, or null.
fn wasm10Violation(module_def: anytype) ?[]const u8 {
    for (module_def.types.items) |func_type| {
        if (func_type.getReturns().len > 1) return "a function type with several results";
        for (func_type.types.items) |vt| if (!wasm10ValType(vt)) return "a function type with a non-numeric value";
    }
    for (module_def.code.locals.items) |vt| if (!wasm10ValType(vt)) return "a non-numeric local";
    for (module_def.globals.items) |global| if (!wasm10ValType(global.valtype)) return "a non-numeric global";
    const instructions = module_def.code.instructions.items;
    const immediates = module_def.code.validation_immediates.items;
    if (immediates.len != instructions.len) return "instructions the check cannot pair with their block types";
    const Opcode = @FieldType(@TypeOf(instructions[0]), "opcode");
    for (instructions, immediates) |instruction, immediate| {
        const opcode = instruction.opcode;
        // bytebox orders its opcodes with every later proposal's after the
        // 1.0 conversions, from sign extension on.
        if (@backingInt(opcode) >= @backingInt(Opcode.I32_Extend8_S)) return @tagName(opcode);
        const later_opcodes = [_]Opcode{ .Select_T, .Table_Get, .Table_Set, .Drop_V128, .Select_V128, .Local_Get_V128, .Local_Set_V128, .Local_Tee_V128, .Global_Get_V128, .Global_Set_V128 };
        if (std.mem.findScalar(Opcode, &later_opcodes, opcode) != null) return @tagName(opcode);
        const block_opcodes = [_]Opcode{ .Block, .Loop, .If, .IfNoElse };
        if (std.mem.findScalar(Opcode, &block_opcodes, opcode) != null and immediate.BlockOrIf.block_type == .TypeIndex) return "a block with a signature type";
    }
    return null;
}

fn customWasmPostLlvmPipeline(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
) ?TestResult {
    if (!@import("cli_test_options").binaryen) {
        return .{ .status = .skip, .phase = .setup, .message = "requires bundled Binaryen" };
    }

    var trace_env = CaseEnv{
        .dirs = env.dirs,
        .env_map = env.env_map.clone(allocator) catch |err|
            return customInfraFailure(allocator, timer, "failed to clone wasm test environment: {}", .{err}),
    };
    defer trace_env.env_map.deinit();
    trace_env.env_map.put("BINARYEN_PASS_DEBUG", "1") catch |err|
        return customInfraFailure(allocator, timer, "failed to enable Binaryen pass tracing: {}", .{err});

    const wasm_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "pipeline.wasm" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate wasm output path: {}", .{err});
    defer allocator.free(wasm_path);
    const output_arg = outputArg(allocator, wasm_path) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate wasm output argument: {}", .{err});
    defer allocator.free(output_arg);

    const modes = [_]struct { opt: OptMode, debug: bool }{
        .{ .opt = .speed, .debug = false },
        .{ .opt = .speed, .debug = true },
        .{ .opt = .size, .debug = false },
        .{ .opt = .size, .debug = true },
    };
    for (modes) |mode| {
        const speed = mode.opt == .speed;
        const opt_arg = if (speed) "--opt=speed" else "--opt=size";
        const args = [_][]const u8{ "build", "--target=wasm32", "--no-cache", opt_arg, output_arg, "--debug" };
        const contains = [_]OutputNeedle{
            .{ .stream = .stderr, .text = "running pass: remove-unused-module-elements" },
            .{ .stream = .stderr, .text = "running pass: memory-packing" },
            .{ .stream = .stderr, .text = "(final validation)" },
            .{ .stream = .stderr, .text = if (speed) "running pass: vacuum" else "running pass: coalesce-locals" },
        };
        const not_contains = [_]OutputNeedle{
            .{ .stream = .stderr, .text = "running pass: coalesce-locals" },
            .{ .stream = .stderr, .text = "running pass: merge-locals" },
            .{ .stream = .stderr, .text = "running pass: precompute" },
            .{ .stream = .stderr, .text = "running pass: inlining-optimizing" },
        };
        const occurrences = [_]OutputOccurrence{
            .{ .stream = .stderr, .text = "running pass: strip-debug", .count = @intFromBool(!mode.debug) },
            .{ .stream = .stderr, .text = "running pass: strip-dwarf", .count = @intFromBool(!mode.debug) },
            .{ .stream = .stderr, .text = "running pass: strip-producers", .count = 1 },
            .{ .stream = .stderr, .text = "running pass: strip-target-features", .count = @intFromBool(!speed and !mode.debug) },
        };
        if (runRocAndCheck(io, allocator, &trace_env, timer, timeout_ms, .{
            .args = args[0..if (mode.debug) args.len else args.len - 1],
            .roc_file = "test/wasm/str_concat_join_static_lib_app.roc",
            .contains = &contains,
            .not_contains = if (speed) &not_contains else &.{},
            .occurrences = &occurrences,
        })) |failure| return failure;
        if (validateWasmOutput(io, allocator, timer, wasm_path)) |failure| return failure;
    }
    return null;
}

fn customIssue10733WasmBoxyDevSealedObject(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
) ?TestResult {
    const first_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "boxed-first.wasm" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate first wasm output path: {}", .{err});
    defer allocator.free(first_path);
    const second_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "boxed-second.wasm" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate second wasm output path: {}", .{err});
    defer allocator.free(second_path);
    const first_output_arg = outputArg(allocator, first_path) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate first wasm output argument: {}", .{err});
    defer allocator.free(first_output_arg);
    const second_output_arg = outputArg(allocator, second_path) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate second wasm output argument: {}", .{err});
    defer allocator.free(second_output_arg);

    const contains = [_]OutputNeedle{.{ .stream = .stdout, .text = "successfully building" }};
    const not_contains = [_]OutputNeedle{
        .{ .stream = .stderr, .text = "DuplicateSymbol" },
        .{ .stream = .stderr, .text = "UnresolvedBuiltinImport" },
        .{ .stream = .stderr, .text = "panic" },
    };
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "build", "--target=wasm32", "--opt=dev", "--no-cache", first_output_arg },
        .roc_file = "test/wasm/boxed_closure_app.roc",
        .exit = .success,
        .contains = &contains,
        .not_contains = &not_contains,
    })) |failure| return failure;
    if (validateWasmOutput(io, allocator, timer, first_path)) |failure| return failure;

    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "build", "--target=wasm32", "--opt=dev", "--no-cache", second_output_arg },
        .roc_file = "test/wasm/boxed_closure_app.roc",
        .exit = .success,
        .contains = &contains,
        .not_contains = &not_contains,
    })) |failure| return failure;
    if (validateWasmOutput(io, allocator, timer, second_path)) |failure| return failure;

    const first_bytes = std.Io.Dir.cwd().readFileAlloc(io, first_path, allocator, .unlimited) catch |err|
        return customInfraFailure(allocator, timer, "failed to reread first wasm output: {}", .{err});
    defer allocator.free(first_bytes);
    const second_bytes = std.Io.Dir.cwd().readFileAlloc(io, second_path, allocator, .unlimited) catch |err|
        return customInfraFailure(allocator, timer, "failed to reread second wasm output: {}", .{err});
    defer allocator.free(second_bytes);
    if (!std.mem.eql(u8, first_bytes, second_bytes)) {
        return customFailure(allocator, timer, "sealed Roc object changed the final wasm bytes", .{});
    }
    const has_main = wasmHasExport(first_bytes, "wasm_main") catch |err|
        return customFailure(allocator, timer, "failed to read final wasm exports: {}", .{err});
    const exports_init = wasmHasExport(first_bytes, "roc_boxy_init_embedded") catch |err|
        return customFailure(allocator, timer, "failed to read final wasm exports: {}", .{err});
    const exports_concat = wasmHasExport(first_bytes, "roc_builtins_str_concat") catch |err|
        return customFailure(allocator, timer, "failed to read final wasm exports: {}", .{err});
    if (!has_main) {
        return customFailure(allocator, timer, "final wasm lost its declared platform export", .{});
    }
    if (exports_init or exports_concat) {
        return customFailure(allocator, timer, "sealed Roc object leaked runtime internals into final wasm exports", .{});
    }

    return null;
}

/// Runtime symbol names can occur in the embedded LIR's data section; only
/// entries in the wasm export section cross the platform boundary.
fn wasmHasExport(bytes: []const u8, wanted: []const u8) (std.Io.Reader.TakeLeb128Error || error{InvalidWasmHeader})!bool {
    var module = std.Io.Reader.fixed(bytes);
    if (!std.mem.eql(u8, try module.take(8), "\x00asm\x01\x00\x00\x00")) return error.InvalidWasmHeader;
    while (module.bufferedLen() != 0) {
        const section_id = try module.takeByte();
        const section_size = try module.takeLeb128(u32);
        const payload = try module.take(section_size);
        if (section_id != 7) continue;
        var exports = std.Io.Reader.fixed(payload);
        const count = try exports.takeLeb128(u32);
        for (0..count) |_| {
            const name_len = try exports.takeLeb128(u32);
            const name = try exports.take(name_len);
            _ = try exports.takeByte();
            _ = try exports.takeLeb128(u32);
            if (std.mem.eql(u8, name, wanted)) return true;
        }
        return false;
    }
    return false;
}

/// Build a program of generic tail-call cycles for wasm32 without
/// specialization and run it. The interpreter's stack is far smaller than
/// the cycles are deep, so a cycle that kept its frames would overflow it.
fn customIssue12029WasmBoxyTailCalls(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
) ?TestResult {
    const output_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "boxy-tail-calls.wasm" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate wasm output path: {}", .{err});
    defer allocator.free(output_path);
    const output_arg = outputArg(allocator, output_path) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate wasm output argument: {}", .{err});
    defer allocator.free(output_arg);

    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "build", "--target=wasm32", "--opt=dev", "--specialize=no", "--no-cache", output_arg },
        .roc_file = "test/wasm/boxy_generic_tail_calls_app.roc",
        .exit = .success,
        .contains = &.{.{ .stream = .stdout, .text = "successfully building" }},
        .not_contains = &.{.{ .stream = .stderr, .text = "panic" }},
    })) |failure| return failure;
    if (validateWasmOutput(io, allocator, timer, output_path)) |failure| return failure;

    var wasm = setupGlueRuntimeWasm(io, allocator, output_path) catch |err|
        return customFailure(allocator, timer, "failed to load the boxy tail call wasm module: {}", .{err});
    defer wasm.deinit();
    const result = callGlueRuntimeWasmMain(&wasm, allocator) catch |err|
        return customFailure(allocator, timer, "boxy tail call wasm execution failed: {}", .{err});
    const expected = "a result string long enough to live on the heap!";
    if (!std.mem.eql(u8, result, expected)) {
        return customFailure(allocator, timer, "boxy tail call wasm returned \"{s}\"", .{result});
    }
    return null;
}

/// A `.boxy` dev build of a wasm32 app with a cache files a wasm unit per
/// module and one for the root, and a second build of the same sources
/// restores every one of them and writes the same module, which runs.
fn customWasmUnitsWarm(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
) ?TestResult {
    var isolated = CaseEnv{ .dirs = env.dirs, .env_map = env.env_map.clone(allocator) catch |err| return customInfraFailure(allocator, timer, "clone environment: {}", .{err}) };
    defer isolated.env_map.deinit();
    const cache_root = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "wasm_unit_cache" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate the cache root: {}", .{err});
    for ([_][]const u8{ "ROC_CACHE_DIR", "XDG_CACHE_HOME" }) |key| {
        isolated.env_map.put(key, cache_root) catch |err| return customInfraFailure(allocator, timer, "failed to set the cache root: {}", .{err});
    }
    var built_units: ?[]const u8 = null;
    var first_bytes: ?[]const u8 = null;
    for ([_][]const u8{ "cold", "warm" }) |name| {
        const output_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, name }) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate wasm output path: {}", .{err});
        const output_path_wasm = std.fmt.allocPrint(allocator, "{s}.wasm", .{output_path}) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate wasm output path: {}", .{err});
        const output_arg = outputArg(allocator, output_path_wasm) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate wasm output argument: {}", .{err});
        const remaining = childCommandTimeoutMs(timer, timeout_ms) orelse return timeoutFailure(allocator, timer, .run, "wasm unit cache test timed out");
        const run = runRocInEnv(io, allocator, &isolated, &.{ "build", "--target=wasm32", "--opt=dev", "--specialize=no", "--no-color", "--verbose", output_arg }, "test/wasm/boxy_generic_tail_calls_app.roc", .relative, &.{}, null, remaining) catch |err|
            return customInfraFailure(allocator, timer, "build: {}", .{err});
        if (!processSucceeded(run.term)) return failureFromRun(allocator, timer, run, "the build failed");
        const prefix = "Wasm units: ";
        const at = std.mem.find(u8, run.stdout, prefix) orelse return failureFromRun(allocator, timer, run, "the build reported no wasm units");
        const line = run.stdout[at + prefix.len ..];
        const summary = line[0 .. std.mem.findScalar(u8, line, '\n') orelse line.len];
        if (built_units) |count| {
            const expected = std.fmt.allocPrint(allocator, "{s} cached, 0 built", .{count}) catch |err|
                return customInfraFailure(allocator, timer, "summary: {}", .{err});
            if (!std.mem.eql(u8, summary, expected)) return failureFromRun(allocator, timer, run, "the warm build did not restore every wasm unit the cold build filed");
        } else {
            const zero = "0 cached, ";
            if (!std.mem.startsWith(u8, summary, zero)) return failureFromRun(allocator, timer, run, "the cold build restored wasm units from an empty cache");
            const count = summary[zero.len .. std.mem.find(u8, summary, " built") orelse return failureFromRun(allocator, timer, run, "the cold build's wasm unit summary does not read")];
            if (std.mem.eql(u8, count, "0")) return failureFromRun(allocator, timer, run, "the cold build filed no wasm units");
            built_units = count;
        }
        if (validateWasmOutput(io, allocator, timer, output_path_wasm)) |failure| return failure;
        const bytes = std.Io.Dir.cwd().readFileAlloc(io, output_path_wasm, allocator, .limited(64 * 1024 * 1024)) catch |err| return customInfraFailure(allocator, timer, "read wasm module: {}", .{err});
        if (first_bytes) |expected| {
            if (!std.mem.eql(u8, expected, bytes)) return customFailure(allocator, timer, "the warm build's wasm module differs from the cold build's", .{});
        } else first_bytes = bytes;
        var wasm = setupGlueRuntimeWasm(io, allocator, output_path_wasm) catch |err|
            return customFailure(allocator, timer, "failed to load the wasm module: {}", .{err});
        defer wasm.deinit();
        const result = callGlueRuntimeWasmMain(&wasm, allocator) catch |err|
            return customFailure(allocator, timer, "wasm execution failed: {}", .{err});
        if (!std.mem.eql(u8, result, "a result string long enough to live on the heap!")) return customFailure(allocator, timer, "the wasm module returned \"{s}\"", .{result});
    }
    return null;
}

