fn customMacosOutputBasenameReproducible(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
) ?TestResult {
    if (builtin.os.tag != .macos) {
        return .{ .status = .skip, .phase = .setup, .duration_ns = timer.read(), .message = "macOS Mach-O reproducibility test only runs on macOS" };
    }

    const default_app_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "default_platform_macos_repro.roc" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate default platform app path: {}", .{err});
    std.Io.Dir.cwd().writeFile(io, .{ .sub_path = default_app_path, .data = default_platform_echo_app }) catch |err|
        return customInfraFailure(allocator, timer, "failed to write default platform app: {}", .{err});

    const opts = [_][]const u8{ "dev", "speed", "size" };
    for (opts) |opt| {
        if (checkMacosOutputBasenameReproducible(io, allocator, env, timer, timeout_ms, opt, "real_platform", "test/fx/hello_world.roc", "Hello, world!\n")) |failure| return failure;
        if (checkMacosOutputBasenameReproducible(io, allocator, env, timer, timeout_ms, opt, "default_platform", default_app_path, "Hello, World!")) |failure| return failure;
    }

    return null;
}

fn checkMacosOutputBasenameReproducible(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
    opt: []const u8,
    label: []const u8,
    roc_file: []const u8,
    expected_stdout: []const u8,
) ?TestResult {
    const short_output = std.fmt.allocPrint(allocator, "{s}/{s}_a_{s}", .{ env.dirs.work_dir, label, opt }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate short macOS output path: {}", .{err});
    const long_output = std.fmt.allocPrint(allocator, "{s}/very-long-{s}-output-name-for-macos-repro-{s}", .{ env.dirs.work_dir, label, opt }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate long macOS output path: {}", .{err});
    const opt_arg = std.fmt.allocPrint(allocator, "--opt={s}", .{opt}) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate opt arg: {}", .{err});
    const short_out_arg = outputArg(allocator, short_output) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate short output arg: {}", .{err});
    const long_out_arg = outputArg(allocator, long_output) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate long output arg: {}", .{err});

    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "build", "--no-cache", opt_arg, short_out_arg },
        .roc_file = roc_file,
        .contains = &.{.{ .stream = .stdout, .text = "successfully building" }},
    })) |failure| return failure;
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "build", "--no-cache", opt_arg, long_out_arg },
        .roc_file = roc_file,
        .contains = &.{.{ .stream = .stdout, .text = "successfully building" }},
    })) |failure| return failure;

    const short_bytes = std.Io.Dir.cwd().readFileAlloc(io, short_output, allocator, .limited(256 * 1024 * 1024)) catch |err|
        return customInfraFailure(allocator, timer, "failed to read short macOS output {s}: {}", .{ short_output, err });
    defer allocator.free(short_bytes);
    const long_bytes = std.Io.Dir.cwd().readFileAlloc(io, long_output, allocator, .limited(256 * 1024 * 1024)) catch |err|
        return customInfraFailure(allocator, timer, "failed to read long macOS output {s}: {}", .{ long_output, err });
    defer allocator.free(long_bytes);

    if (!std.mem.eql(u8, short_bytes, long_bytes)) {
        return customFailure(allocator, timer, "macOS {s} {s} output bytes changed when only the output basename changed", .{ label, opt });
    }

    if (runRawAndCheck(io, allocator, env, timer, timeout_ms, &.{short_output}, env.dirs.work_dir, .{
        .args = &.{},
        .stdout_exact = expected_stdout,
        .stderr_exact = "",
    })) |failure| return failure;

    return null;
}

fn customDefaultPlatformDebugBacktrace(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
    target: DefaultPlatformTarget,
    kind: DefaultPlatformDiagnosticKind,
) ?TestResult {
    if (!target.canRunOnHost()) {
        const message = std.fmt.allocPrint(
            allocator,
            "{s} debug-backtrace check runs only on a matching host",
            .{target.cliName()},
        ) catch "debug-backtrace check runs only on a matching host";
        return .{ .status = .skip, .phase = .setup, .duration_ns = timer.read(), .message = message };
    }

    if (target != .x64musl and target != .arm64musl) {
        const message = std.fmt.allocPrint(
            allocator,
            "{s} default-platform diagnostics runtime is not implemented yet",
            .{target.cliName()},
        ) catch "default-platform diagnostics runtime is not implemented yet";
        return .{ .status = .skip, .phase = .setup, .duration_ns = timer.read(), .message = message };
    }

    if (target == .arm64musl) {
        return .{ .status = .skip, .phase = .setup, .duration_ns = timer.read(), .message = "arm64musl default-platform diagnostics need ARM64 unwinding support" };
    }

    const app_filename = std.fmt.allocPrint(allocator, "default_platform_{s}_{s}.roc", .{ kind.fileStem(), target.cliName() }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate default platform app filename: {}", .{err});
    const app_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, app_filename }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate default platform app path: {}", .{err});
    const output_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "default_platform_diagnostic" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate default platform output path: {}", .{err});
    const target_arg = std.fmt.allocPrint(allocator, "--target={s}", .{target.cliName()}) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate target arg: {}", .{err});
    const out_arg = outputArg(allocator, output_path) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate output arg: {}", .{err});

    std.Io.Dir.cwd().writeFile(io, .{ .sub_path = app_path, .data = kind.source() }) catch |err|
        return customInfraFailure(allocator, timer, "failed to write default platform app: {}", .{err});

    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "build", "--opt=speed", "--debug", "--no-cache", target_arg, out_arg },
        .roc_file = app_path,
        .contains = &.{.{ .stream = .stdout, .text = "successfully building" }},
    })) |failure| return failure;

    const executable_path = runnableOutputPath(io, allocator, output_path) catch |err|
        return customInfraFailure(allocator, timer, "failed to find built executable: {}", .{err});
    const child_timeout_ms = childCommandTimeoutMs(timer, timeout_ms) orelse
        return timeoutFailure(allocator, timer, .run, "case timeout exhausted before default platform app started");
    const run_result = runRawInEnv(io, allocator, env, &.{executable_path}, env.dirs.work_dir, null, child_timeout_ms) catch |err|
        return customInfraFailure(allocator, timer, "default platform app spawn error: {}", .{err});

    const expected_contains: []const OutputNeedle = switch (kind) {
        .crash => &.{
            .{ .stream = .stderr, .text = "Roc application crashed with this message:\n\n\tdefault platform crash contract\n\n" },
            .{ .stream = .stderr, .text = "Backtrace:" },
            .{ .stream = .stderr, .text = "\x1b[94mtrigger!\x1b[0m" },
            .{ .stream = .stderr, .text = "\x1b[94mmain!\x1b[0m" },
            .{ .stream = .stderr, .text = " main:" },
        },
        .stack_overflow => &.{
            .{ .stream = .stderr, .text = "Roc application overflowed its stack memory\n\n" },
            .{ .stream = .stderr, .text = "Backtrace:" },
            .{ .stream = .stderr, .text = "\x1b[94mrecurse\x1b[0m" },
        },
    };

    if (checkCommandExpectation(allocator, run_result, .{
        .args = &.{},
        .exit = .failure,
        .stderr_min_len = 1,
        .contains = expected_contains,
        .not_contains = &.{
            .{ .stream = .stderr, .text = "Segmentation fault" },
            .{ .stream = .stderr, .text = "panic" },
            .{ .stream = .stderr, .text = "Roc " ++ "crashed:" },
            .{ .stream = .stderr, .text = "Stack overflow" },
            .{ .stream = .stderr, .text = " at " },
            .{ .stream = .stderr, .text = "  0x" },
        },
    })) |message| return failureFromRun(allocator, timer, run_result, message);

    return null;
}

fn runnableOutputPath(io: std.Io, allocator: Allocator, output_path: []const u8) CliRunnerError![]const u8 {
    std.Io.Dir.cwd().access(io, output_path, .{}) catch |err| {
        if (builtin.os.tag != .windows) return err;
        const exe_path = try std.fmt.allocPrint(allocator, "{s}.exe", .{output_path});
        std.Io.Dir.cwd().access(io, exe_path, .{}) catch return err;
        return exe_path;
    };
    return output_path;
}

const GeneratedModuleGraphConfig = struct {
    roc_file_count: usize,
    symbols_per_file: usize,
};

/// Regression test for builtin inlining: a native `--opt=speed` archive build must
/// inline list builtins (link builtins.bc) rather than leave them as opaque external
/// calls. If the builtin symbol naming ever drifts between the codegen and the
/// bitcode, the inlining silently stops; this catches that by asserting the archive's
/// app object has no remaining reference to `roc_builtins_list_append_unsafe`.
fn customListBuiltinInlined(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
) ?TestResult {
    const plat_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "inline_plat.roc" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate platform path: {}", .{err});
    const app_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "inline_app.roc" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate app path: {}", .{err});
    const archive_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "inline_app.a" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate archive path: {}", .{err});
    const output_arg = std.fmt.allocPrint(allocator, "--output={s}", .{archive_path}) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate output arg: {}", .{err});

    const plat_src =
        \\platform ""
        \\    requires {} { main! : () => List(I32) }
        \\    exposes []
        \\    packages {}
        \\    provides { "roc_main": main_for_host! }
        \\    targets: {
        \\        inputs_dir: "targets/",
        \\        arm64mac: { inputs: [app], output: Archive },
        \\        x64mac: { inputs: [app], output: Archive },
        \\        arm64musl: { inputs: [app], output: Archive },
        \\        arm64v1musl: { inputs: [app], output: Archive },
        \\        x64musl: { inputs: [app], output: Archive },
        \\        x64v1musl: { inputs: [app], output: Archive },
        \\        arm64glibc: { inputs: [app], output: Archive },
        \\        x64glibc: { inputs: [app], output: Archive },
        \\        arm64win: { inputs: [app], output: Archive },
        \\        x64win: { inputs: [app], output: Archive },
        \\    }
        \\
        \\main_for_host! : () => List(I32)
        \\main_for_host! = || main!()
        \\
    ;
    const app_src =
        \\app [main!] { pf: platform "./inline_plat.roc" }
        \\
        \\main! : () => List(I32)
        \\main! = || [1.I32, 2, 3].map(|x| x + 1)
        \\
    ;
    std.Io.Dir.cwd().writeFile(io, .{ .sub_path = plat_path, .data = plat_src }) catch |err|
        return customInfraFailure(allocator, timer, "failed to write platform: {}", .{err});
    std.Io.Dir.cwd().writeFile(io, .{ .sub_path = app_path, .data = app_src }) catch |err|
        return customInfraFailure(allocator, timer, "failed to write app: {}", .{err});

    const child_timeout_ms = childCommandTimeoutMs(timer, timeout_ms) orelse
        return timeoutFailure(allocator, timer, .run, "case timeout exhausted before roc build started");
    const result = runRocInEnv(io, allocator, env, &.{ "build", "--opt=speed", "--no-cache", output_arg }, app_path, .absolute, &.{}, null, child_timeout_ms) catch |err|
        return customInfraFailure(allocator, timer, "roc build spawn error: {}", .{err});
    if (checkCommandExpectation(allocator, result, .{ .args = &.{"build"}, .exit = .success })) |message| {
        return failureFromRun(allocator, timer, result, message);
    }

    const archive_bytes = std.Io.Dir.cwd().readFileAlloc(io, archive_path, allocator, .limited(64 * 1024 * 1024)) catch |err|
        return customInfraFailure(allocator, timer, "failed to read archive {s}: {}", .{ archive_path, err });
    if (std.mem.find(u8, archive_bytes, BuiltinFn.list_append_unsafe.symbolName()) != null) {
        return customFailure(allocator, timer, "list_append_unsafe was not inlined into the --opt=speed archive object (it still references the builtin symbol)", .{});
    }
    return null;
}

fn customGeneratedModuleGraph(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
    config: GeneratedModuleGraphConfig,
) ?TestResult {
    if (writeGeneratedModuleGraphProject(io, allocator, env.dirs.work_dir, config)) |main_path| {
        const cache_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "roc-cache" }) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate cache path: {}", .{err});
        const child_timeout_ms = childCommandTimeoutMs(timer, timeout_ms) orelse
            return timeoutFailure(allocator, timer, .run, "case timeout exhausted before roc check started");
        const result = runRocInEnv(io, allocator, env, &.{"check"}, main_path, .absolute, &.{}, null, child_timeout_ms) catch |err|
            return customInfraFailure(allocator, timer, "roc check spawn error: {}", .{err});
        if (checkCommandExpectation(allocator, result, .{ .args = &.{"check"}, .exit = .success })) |message| {
            return failureFromRun(allocator, timer, result, message);
        }
        const cached_module_count = countModuleCacheFiles(io, allocator, cache_path, "mod") catch |err|
            return customInfraFailure(allocator, timer, "failed to count checked module cache files: {}", .{err});
        if (cached_module_count != config.roc_file_count) {
            return customFailure(allocator, timer, "expected {d} checked module cache files, found {d}", .{ config.roc_file_count, cached_module_count });
        }
        // Each module also stores exactly one canonicalized entry, keyed on its
        // own source alone.
        const canonicalized_module_count = countModuleCacheFiles(io, allocator, cache_path, "can") catch |err|
            return customInfraFailure(allocator, timer, "failed to count canonicalized module cache files: {}", .{err});
        if (canonicalized_module_count != config.roc_file_count) {
            return customFailure(allocator, timer, "expected {d} canonicalized module cache files, found {d}", .{ config.roc_file_count, canonicalized_module_count });
        }
    } else |err| {
        return customInfraFailure(allocator, timer, "failed to write generated module graph: {}", .{err});
    }
    return null;
}

fn writeGeneratedModuleGraphProject(
    io: std.Io,
    allocator: Allocator,
    dir_path: []const u8,
    config: GeneratedModuleGraphConfig,
) CliRunnerError![]const u8 {
    if (config.roc_file_count == 0 or config.symbols_per_file == 0) return error.InvalidGeneratedGraphConfig;

    var dir = try std.Io.Dir.openDirAbsolute(io, dir_path, .{});
    defer dir.close(io);

    try writeGeneratedPackageModule(io, dir, config);

    var module_idx: usize = 1;
    while (module_idx < config.roc_file_count) : (module_idx += 1) {
        try writeGeneratedTypeModule(io, allocator, dir, config, module_idx);
    }

    return try std.fs.path.join(allocator, &.{ dir_path, "main.roc" });
}

fn writeGeneratedPackageModule(io: std.Io, dir: std.Io.Dir, config: GeneratedModuleGraphConfig) CliRunnerError!void {
    var file = try dir.createFile(io, "main.roc", .{});
    defer file.close(io);

    var write_buffer: [4096]u8 = undefined;
    var writer = file.writer(io, &write_buffer);
    const out = &writer.interface;

    const type_module_count = config.roc_file_count - 1;
    try out.writeAll("package [\n");
    var module_idx: usize = 1;
    while (module_idx <= type_module_count) : (module_idx += 1) {
        try out.print("    T{d},\n", .{module_idx});
    }
    try out.writeAll("] {}\n\n");

    module_idx = 1;
    while (module_idx <= type_module_count) : (module_idx += 1) {
        try out.print("import T{d}\n", .{module_idx});
    }
    try out.writeAll("\n");

    var symbol_idx: usize = 1;
    while (symbol_idx <= config.symbols_per_file) : (symbol_idx += 1) {
        try out.print("p{d} : {{}}\n", .{symbol_idx});
        if (symbol_idx == 1) {
            if (type_module_count > 0) {
                try out.writeAll("p1 = T1.s1\n\n");
            } else {
                try out.writeAll("p1 = {}\n\n");
            }
        } else {
            try out.print("p{d} = p{d}\n\n", .{ symbol_idx, symbol_idx - 1 });
        }
    }
    try out.flush();
}

fn writeGeneratedTypeModule(
    io: std.Io,
    allocator: Allocator,
    dir: std.Io.Dir,
    config: GeneratedModuleGraphConfig,
    module_idx: usize,
) CliRunnerError!void {
    const file_name = try std.fmt.allocPrint(allocator, "T{d}.roc", .{module_idx});
    var file = try dir.createFile(io, file_name, .{});
    defer file.close(io);

    var write_buffer: [4096]u8 = undefined;
    var writer = file.writer(io, &write_buffer);
    const out = &writer.interface;

    if (module_idx > 1) {
        try out.writeAll("import T1\n\n");
    }

    try out.print("T{d} := [].{{\n", .{module_idx});
    var symbol_idx: usize = 1;
    while (symbol_idx <= config.symbols_per_file) : (symbol_idx += 1) {
        try out.print("    s{d} : {{}}\n", .{symbol_idx});
        if (symbol_idx == 1) {
            if (module_idx > 1) {
                try out.writeAll("    s1 = T1.s1\n\n");
            } else {
                try out.writeAll("    s1 = {}\n\n");
            }
        } else {
            try out.print("    s{d} = s{d}\n\n", .{ symbol_idx, symbol_idx - 1 });
        }
    }
    try out.writeAll("}\n");
    try out.flush();
}

/// Count published entries of the explicitly selected module-cache family.
/// Count committed entries in one module cache section (`mod` or `can`),
/// using the section's own scope as the cache manager files them.
fn countModuleCacheFiles(io: std.Io, allocator: Allocator, cache_path: []const u8, section: []const u8) CliRunnerError!usize {
    const family: artifact_store.Family = if (std.mem.eql(u8, section, "mod")) .checked else .canonicalized;
    const scope = try std.fs.path.join(allocator, &.{ cache_path, "compat-" ++ build_options.compiler_compatibility_id, section });
    defer allocator.free(scope);
    var store = try artifact_store.Store.init(allocator, io, cache_path);
    defer store.deinit();
    const path = try store.groupPath(allocator, .{
        .namespace = artifact_store.hashBytes(build_options.compiler_compatibility_id),
        .family = family,
        .group = artifact_store.hashBytes(scope),
        .key = @splat(0),
    });
    defer allocator.free(path);
    var dir = std.Io.Dir.cwd().openDir(io, path, .{ .iterate = true }) catch |err| switch (err) {
        error.FileNotFound => return 0,
        else => return err,
    };
    defer dir.close(io);
    var iter = dir.iterate();
    var count: usize = 0;
    while (try iter.next(io)) |entry| {
        if (entry.kind == .file and std.mem.endsWith(u8, entry.name, ".data")) count += 1;
    }
    return count;
}

/// The `--timings` row that covers LLVM's optimization pipeline and object
/// emission for the app.
const llvm_emit_phase_name = "LLVM Optimize + Emit";

/// Procedure counts for the scaling comparison. The larger app is eight times
/// the smaller one, so its LLVM phase should cost about eight times as much.
const llvm_scaling_small_procs: usize = 500;
const llvm_scaling_large_procs: usize = 4000;

/// How much more than proportional growth the phase may cost. The slack
/// absorbs per-build fixed cost and host noise while staying far below the
/// growth an app-sized quadratic produces.
const llvm_scaling_slack_numerator: u64 = 3;
const llvm_scaling_slack_denominator: u64 = 2;

/// Growth ratios are only meaningful once the phase is long enough to measure,
/// so a large app that finishes this fast satisfies the guard outright. The
/// Windows CI host runs several test shards at once, which moves the phase's
/// fixed cost enough to matter at this size, so its floor is higher.
const llvm_scaling_floor_ms: u64 = if (builtin.os.tag == .windows) 7500 else 250;

fn customIssue11133LlvmEmitScaling(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
) ?TestResult {
    // Repro for https://github.com/roc-lang/roc/issues/11133.
    //
    // Both apps are the same shape - a binary call tree of one-statement
    // procedures - so the only thing that changes is how many procedures the
    // LLVM backend receives. Optimizing and emitting them must cost time
    // proportional to that count.
    var small_ms: u64 = 0;
    if (measureLlvmOptimizeEmitMs(io, allocator, env, timer, timeout_ms, "llvm_scaling_small.roc", llvm_scaling_small_procs, &small_ms)) |failure| return failure;

    var large_ms: u64 = 0;
    if (measureLlvmOptimizeEmitMs(io, allocator, env, timer, timeout_ms, "llvm_scaling_large.roc", llvm_scaling_large_procs, &large_ms)) |failure| return failure;

    const proportional_growth: u64 = @intCast(llvm_scaling_large_procs / llvm_scaling_small_procs);
    const budget_ms = @max(
        small_ms * proportional_growth * llvm_scaling_slack_numerator / llvm_scaling_slack_denominator,
        llvm_scaling_floor_ms,
    );
    if (large_ms > budget_ms) {
        return customFailure(
            allocator,
            timer,
            "{s} took {d}ms for {d} procedures and {d}ms for {d} procedures; {d}x the procedures may cost at most {d}ms",
            .{ llvm_emit_phase_name, large_ms, llvm_scaling_large_procs, small_ms, llvm_scaling_small_procs, proportional_growth, budget_ms },
        );
    }
    return null;
}

fn measureLlvmOptimizeEmitMs(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
    file_name: []const u8,
    proc_count: usize,
    out_ms: *u64,
) ?TestResult {
    const app_path = writeCallTreeApp(io, allocator, env.dirs.work_dir, file_name, proc_count) catch |err|
        return customInfraFailure(allocator, timer, "failed to write the {d}-procedure app: {}", .{ proc_count, err });
    const output_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "llvm_scaling_output" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate output path: {}", .{err});
    const out_arg = outputArg(allocator, output_path) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate output arg: {}", .{err});
    const child_timeout_ms = childCommandTimeoutMs(timer, timeout_ms) orelse
        return timeoutFailure(allocator, timer, .build, "case timeout exhausted before roc build started");

    const args: []const []const u8 = &.{ "build", "--no-cache", "--timings", out_arg };
    const result = runRocInEnv(io, allocator, env, args, app_path, .absolute, &.{}, null, child_timeout_ms) catch |err|
        return customInfraFailure(allocator, timer, "roc build spawn error: {}", .{err});
    if (checkCommandExpectation(allocator, result, .{ .args = args, .exit = .success })) |message| {
        return failureFromRun(allocator, timer, result, message);
    }

    out_ms.* = llvmOptimizeEmitMs(result.stderr) orelse
        return customFailure(allocator, timer, "roc build --timings reported no \"{s}\" row for the {d}-procedure app", .{ llvm_emit_phase_name, proc_count });
    return null;
}

/// Writes an app whose `proc_count` procedures form a binary call tree, each
/// with one `Str.concat` statement, so procedure count is the only thing that
/// grows between two sizes.
fn writeCallTreeApp(
    io: std.Io,
    allocator: Allocator,
    dir_path: []const u8,
    file_name: []const u8,
    proc_count: usize,
) CliRunnerError![]const u8 {
    const platform_absolute = try absoluteFromProjectRoot(allocator, "test/fx-open/platform/main.roc");
    const platform_path = try std.fs.path.relative(allocator, project_root_path, null, dir_path, platform_absolute);
    // Windows accepts forward slashes, which need no escaping in Roc strings.
    if (builtin.os.tag == .windows) std.mem.replaceScalar(u8, platform_path, '\\', '/');

    var dir = try std.Io.Dir.openDirAbsolute(io, dir_path, .{});
    defer dir.close(io);

    var file = try dir.createFile(io, file_name, .{});
    defer file.close(io);

    var write_buffer: [4096]u8 = undefined;
    var writer = file.writer(io, &write_buffer);
    const out = &writer.interface;

    try out.print("app [main!] {{ pf: platform \"{s}\" }}\n\nimport pf.Stdout\n\n", .{platform_path});

    var proc_idx: usize = 0;
    while (proc_idx < proc_count) : (proc_idx += 1) {
        const left = 2 * proc_idx + 1;
        const right = 2 * proc_idx + 2;
        try out.print("f{d} : Str -> Str\n", .{proc_idx});
        try out.print("f{d} = |s| {{\n", .{proc_idx});
        try out.writeAll("    a1 = Str.concat(s, \"1\")\n");
        if (right < proc_count) {
            try out.print("    Str.concat(f{d}(a1), f{d}(a1))\n", .{ left, right });
        } else if (left < proc_count) {
            try out.print("    f{d}(a1)\n", .{left});
        } else {
            try out.writeAll("    a1\n");
        }
        try out.writeAll("}\n\n");
    }

    try out.writeAll(
        \\main! : List(Str) => Try({}, [Exit(I32)])
        \\main! = |args| {
        \\    Stdout.line!(f0(args.len().to_str()))
        \\    Ok({})
        \\}
        \\
    );
    try out.flush();

    return try std.fs.path.join(allocator, &.{ dir_path, file_name });
}

/// Reads the duration off the `--timings` phase row, which always renders as
/// underscore-grouped milliseconds.
fn llvmOptimizeEmitMs(stderr: []const u8) ?u64 {
    const row_start = std.mem.find(u8, stderr, llvm_emit_phase_name) orelse return null;
    const after_name = stderr[row_start + llvm_emit_phase_name.len ..];
    const row = after_name[0 .. std.mem.findScalar(u8, after_name, '\n') orelse after_name.len];

    var idx = std.mem.findAny(u8, row, "0123456789") orelse return null;
    var ms: u64 = 0;
    while (idx < row.len) : (idx += 1) {
        const char = row[idx];
        if (char == '_') continue;
        if (char < '0' or char > '9') break;
        ms = ms * 10 + @as(u64, char - '0');
    }
    if (!std.mem.startsWith(u8, row[idx..], "ms")) return null;
    return ms;
}

fn customFmtReformatsFile(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, timeout_ms: u64) ?TestResult {
    const source = std.Io.Dir.cwd().readFileAlloc(io, "test/cli/needs_formatting.roc", allocator, .limited(10 * 1024)) catch |err|
        return customInfraFailure(allocator, timer, "failed to read source: {}", .{err});
    const temp_file_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "temp_format.roc" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate temp file path: {}", .{err});
    std.Io.Dir.cwd().writeFile(io, .{ .sub_path = temp_file_path, .data = source }) catch |err|
        return customInfraFailure(allocator, timer, "failed to write temp file: {}", .{err});

    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{ .args = &.{"fmt"}, .roc_file = temp_file_path })) |failure| return failure;

    const formatted = std.Io.Dir.cwd().readFileAlloc(io, temp_file_path, allocator, .limited(10 * 1024)) catch |err|
        return customInfraFailure(allocator, timer, "failed to read formatted temp file: {}", .{err});
    if (formatted.len == source.len) {
        return customFailure(allocator, timer, "formatting did not change file size", .{});
    }
    if (formatted.len == 0) {
        return customFailure(allocator, timer, "formatted file was empty", .{});
    }
    return null;
}

fn customFmtDoesNotChangeFile(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, timeout_ms: u64) ?TestResult {
    const source = std.Io.Dir.cwd().readFileAlloc(io, "test/cli/well_formatted.roc", allocator, .limited(10 * 1024)) catch |err|
        return customInfraFailure(allocator, timer, "failed to read source: {}", .{err});
    const temp_file_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "well_formatted.roc" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate temp file path: {}", .{err});
    std.Io.Dir.cwd().writeFile(io, .{ .sub_path = temp_file_path, .data = source }) catch |err|
        return customInfraFailure(allocator, timer, "failed to write temp file: {}", .{err});

    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{ .args = &.{"fmt"}, .roc_file = temp_file_path })) |failure| return failure;

    const after = std.Io.Dir.cwd().readFileAlloc(io, temp_file_path, allocator, .limited(10 * 1024)) catch |err|
        return customInfraFailure(allocator, timer, "failed to read temp file after formatting: {}", .{err});
    if (!std.mem.eql(u8, source, after)) {
        return customFailure(allocator, timer, "well-formatted file changed after roc fmt", .{});
    }
    return null;
}

fn customFmtStdin(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
    expect_same: bool,
) ?TestResult {
    const source_path = if (expect_same) "test/cli/well_formatted.roc" else "test/cli/needs_formatting.roc";
    const input = std.Io.Dir.cwd().readFileAlloc(io, source_path, allocator, .limited(10 * 1024)) catch |err|
        return customInfraFailure(allocator, timer, "failed to read stdin source: {}", .{err});
    const child_timeout_ms = childCommandTimeoutMs(timer, timeout_ms) orelse
        return timeoutFailure(allocator, timer, .run, "case timeout exhausted before roc fmt --stdin started");
    const result = runRocInEnv(io, allocator, env, &.{ "fmt", "--stdin" }, null, .absolute, &.{}, input, child_timeout_ms) catch |err|
        return customInfraFailure(allocator, timer, "roc fmt --stdin spawn error: {}", .{err});
    if (checkCommandExpectation(allocator, result, .{ .args = &.{ "fmt", "--stdin" } })) |message| {
        return failureFromRun(allocator, timer, result, message);
    }
    const same = std.mem.eql(u8, result.stdout, input);
    if (expect_same and !same) return customFailure(allocator, timer, "formatted stdin changed unexpectedly", .{});
    if (!expect_same and same) return customFailure(allocator, timer, "unformatted stdin was not changed", .{});
    if (result.stdout.len == 0) return customFailure(allocator, timer, "roc fmt --stdin produced empty output", .{});
    return null;
}

fn customBuildIntCreatesOutput(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
    backend: OptMode,
) ?TestResult {
    const output_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, if (backend == .dev) "test_app_dev_output" else "test_app" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate output path: {}", .{err});
    const out_arg = outputArg(allocator, output_path) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate output arg: {}", .{err});
    const opt_arg = backendOptArg(allocator, backend) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate opt arg: {}", .{err});
    const args: []const []const u8 = if (backend == .dev)
        &.{ "build", opt_arg, "--no-cache", out_arg }
    else
        &.{ "build", opt_arg, out_arg };
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = args,
        .roc_file = "test/int/app.roc",
        .contains = &.{.{ .stream = .stdout, .text = "successfully building" }},
        .stdout_min_len = 6,
    })) |failure| return failure;
    const size = fileExistsWithSize(io, output_path) catch |err|
        return customFailure(allocator, timer, "failed to stat output file: {}", .{err});
    if (size == 0) return customFailure(allocator, timer, "output file was empty", .{});
    return null;
}

fn customBuildIntOutputRuns(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
    backend: OptMode,
) ?TestResult {
    const output_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, if (backend == .dev) "test_app_dev" else "test_app" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate output path: {}", .{err});
    const out_arg = outputArg(allocator, output_path) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate output arg: {}", .{err});
    const opt_arg = backendOptArg(allocator, backend) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate opt arg: {}", .{err});

    const args: []const []const u8 = if (backend == .dev)
        &.{ "build", opt_arg, "--no-cache", out_arg }
    else
        &.{ "build", opt_arg, out_arg };
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{ .args = args, .roc_file = "test/int/app.roc" })) |failure| return failure;
    const size = fileExistsWithSize(io, output_path) catch |err|
        return customFailure(allocator, timer, "failed to stat output file: {}", .{err});
    if (size == 0) return customFailure(allocator, timer, "output file was empty", .{});

    const child_timeout_ms = childCommandTimeoutMs(timer, timeout_ms) orelse
        return timeoutFailure(allocator, timer, .run, "case timeout exhausted before built app started");
    const run_result = runRawInEnv(io, allocator, env, &.{output_path}, env.dirs.work_dir, null, child_timeout_ms) catch |err|
        return customInfraFailure(allocator, timer, "built app spawn error: {}", .{err});
    const expected_text = if (backend == .dev) "ALL TESTS PASSED" else "SUCCESS";
    const alternate_text = if (backend == .dev) "ALL TESTS PASSED" else "PASSED";
    if (checkCommandExpectation(allocator, run_result, .{
        .args = &.{},
        .contains_any = &.{.{ .needles = &.{ .{ .stream = .stdout, .text = expected_text }, .{ .stream = .stdout, .text = alternate_text } } }},
    })) |message| return failureFromRun(allocator, timer, run_result, message);
    return null;
}

fn customBuildDefaultAppArgs(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
    backend: OptMode,
    target: ?[]const u8,
) ?TestResult {
    const output_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "issue_10492_args" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate output path: {}", .{err});
    const out_arg = outputArg(allocator, output_path) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate output arg: {}", .{err});

    const opt_arg = backendOptArg(allocator, backend) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate opt arg: {}", .{err});

    const target_arg: ?[]const u8 = if (target) |name|
        std.fmt.allocPrint(allocator, "--target={s}", .{name}) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate target arg: {}", .{err})
    else
        null;
    const build_args: []const []const u8 = if (target_arg) |arg|
        &.{ "build", opt_arg, "--no-cache", arg, out_arg }
    else
        &.{ "build", opt_arg, "--no-cache", out_arg };

    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = build_args,
        .roc_file = "test/echo/issue_10492_build_args.roc",
        .contains = &.{.{ .stream = .stdout, .text = "successfully building" }},
    })) |failure| return failure;

    const executable_path = runnableOutputPath(io, allocator, output_path) catch |err|
        return customInfraFailure(allocator, timer, "failed to find built executable: {}", .{err});

    if (runRawAndCheck(io, allocator, env, timer, timeout_ms, &.{ executable_path, "aaa", "bbb", "ccc" }, env.dirs.work_dir, .{
        .args = &.{},
        .stdout_exact = "[aaa][bbb][ccc]",
        .stderr_exact = "",
    })) |failure| return failure;

    return null;
}

/// Where the object and bitcode files under a compiler cache root lie.
const CacheIntermediates = struct {
    /// Files inside registered scratch directories not yet retired.
    in_scratch: usize = 0,
    /// The first file found in a section that builds share, if any.
    first_shared: ?[]const u8 = null,
};

/// Find every object and bitcode file under `cache_path`. Those are build
/// intermediates: the sections that concurrent builds share hold only
/// content-addressed entries, none of which is an object or bitcode file.
fn findCacheIntermediates(io: std.Io, allocator: Allocator, cache_path: []const u8) CliRunnerError!CacheIntermediates {
    var cache_dir = try std.Io.Dir.cwd().openDir(io, cache_path, .{ .iterate = true });
    defer cache_dir.close(io);

    var walker = try cache_dir.walk(allocator);
    defer walker.deinit();

    var found: CacheIntermediates = .{};
    while (try walker.next(io)) |entry| {
        if (entry.kind != .file) continue;
        const extension = std.fs.path.extension(entry.basename);
        const is_intermediate = std.mem.eql(u8, extension, ".o") or
            std.mem.eql(u8, extension, ".obj") or
            std.mem.eql(u8, extension, ".bc");
        if (!is_intermediate) continue;
        const registered = std.mem.startsWith(u8, entry.path, "tmp" ++ std.fs.path.sep_str);
        if (registered) found.in_scratch += 1;
        if (!registered and found.first_shared == null) found.first_shared = try allocator.dupe(u8, entry.path);
    }
    return found;
}

/// Concurrent interpreter builds share one compiler cache, so every file a
/// build writes while it works must lie in a directory that build owns. A
/// build leaves no intermediate in a shared cache section and removes its
/// scratch ownership when it finishes; bounded maintenance removes its files.
/// `--keep-temp` keeps one scratch
/// directory per build, so two builds never write the same intermediate path.
fn customBuildInterpreterOwnsIntermediates(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
) ?TestResult {
    const output_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "owns_intermediates" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate output path: {}", .{err});
    const out_arg = outputArg(allocator, output_path) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate output arg: {}", .{err});

    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "build", "--opt=interpreter", "--no-cache", out_arg },
        .roc_file = "test/echo/hello.roc",
        .contains = &.{.{ .stream = .stdout, .text = "successfully building" }},
    })) |failure| return failure;

    const after_build = findCacheIntermediates(io, allocator, env.dirs.roc_cache_dir) catch |err|
        return customInfraFailure(allocator, timer, "failed to walk the compiler cache: {}", .{err});
    if (after_build.first_shared) |path| {
        return customFailure(allocator, timer, "interpreter build wrote the intermediate {s} into a cache section that concurrent builds share", .{path});
    }
    // Reclamation is bounded and may finish in later invocations. Every
    // intermediate must already belong to a registered scratch generation.

    var kept_after_first: usize = 0;
    for (0..2) |build_index| {
        if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
            .args = &.{ "build", "--opt=interpreter", "--no-cache", "--keep-temp", out_arg },
            .roc_file = "test/echo/hello.roc",
            .contains = &.{
                .{ .stream = .stdout, .text = "successfully building" },
                .{ .stream = .stderr, .text = "Kept temporary directory" },
            },
        })) |failure| return failure;

        const kept = findCacheIntermediates(io, allocator, env.dirs.roc_cache_dir) catch |err|
            return customInfraFailure(allocator, timer, "failed to walk the compiler cache: {}", .{err});
        if (kept.first_shared) |path| {
            return customFailure(allocator, timer, "interpreter build wrote the intermediate {s} into a cache section that concurrent builds share", .{path});
        }
        if (build_index == 0) {
            if (kept.in_scratch == 0) {
                return customFailure(allocator, timer, "interpreter build with --keep-temp kept no intermediate files in a scratch directory", .{});
            }
            kept_after_first = kept.in_scratch;
        } else if (kept.in_scratch != 2 * kept_after_first) {
            // A second build that reused the first build's paths would
            // overwrite its files rather than add its own.
            return customFailure(allocator, timer, "expected two --keep-temp builds to keep {d} intermediate files in separate scratch directories, found {d}", .{ 2 * kept_after_first, kept.in_scratch });
        }
    }

    return null;
}

/// A native target `roc build --opt=speed` builds for, and the routines LLVM's
/// code generator calls from the test program's code on that target.
const LlvmRuntimeTarget = struct {
    name: []const u8,
    called: []const []const u8,
    /// Routines the object must define although no relocation refers to them.
    defined: []const []const u8 = &.{},
    /// A glibc target links dynamically against libc, so roc builds for it
    /// only on a Linux host.
    glibc: bool = false,
};

const llvm_runtime_base = [_][]const u8{ "memcpy", "memmove", "memset", "fmod", "fmodf" };
const llvm_runtime_base_v1 = llvm_runtime_base ++ [_][]const u8{ "floor", "floorf", "ceil", "ceilf", "trunc", "truncf" };
const llvm_runtime_base_chkstk = llvm_runtime_base ++ [_][]const u8{"__chkstk"};

const llvm_runtime_targets = [_]LlvmRuntimeTarget{
    .{ .name = "x64musl", .called = &llvm_runtime_base },
    .{ .name = "x64v1musl", .called = &llvm_runtime_base_v1 },
    .{ .name = "x64glibc", .called = &llvm_runtime_base, .glibc = true },
    .{ .name = "x64v1glibc", .called = &llvm_runtime_base_v1, .glibc = true },
    .{ .name = "x64freebsd", .called = &llvm_runtime_base },
    .{ .name = "x64v1freebsd", .called = &llvm_runtime_base_v1 },
    .{ .name = "x64netbsd", .called = &llvm_runtime_base },
    .{ .name = "x64v1netbsd", .called = &llvm_runtime_base_v1 },
    .{ .name = "x64mac", .called = &llvm_runtime_base },
    .{ .name = "x64v1mac", .called = &llvm_runtime_base_v1 },
    .{ .name = "x64win", .called = &llvm_runtime_base_chkstk, .defined = &.{"_fltused"} },
    .{ .name = "x64v1win", .called = &(llvm_runtime_base_v1 ++ [_][]const u8{"__chkstk"}), .defined = &.{"_fltused"} },
    .{ .name = "x64mingw", .called = &(llvm_runtime_base ++ [_][]const u8{"___chkstk_ms"}) },
    .{ .name = "x64v1mingw", .called = &(llvm_runtime_base_v1 ++ [_][]const u8{"___chkstk_ms"}) },
    .{ .name = "arm64musl", .called = &llvm_runtime_base },
    .{ .name = "arm64v1musl", .called = &llvm_runtime_base },
    .{ .name = "arm64glibc", .called = &llvm_runtime_base, .glibc = true },
    .{ .name = "arm64v1glibc", .called = &llvm_runtime_base, .glibc = true },
    .{ .name = "arm64mac", .called = &(llvm_runtime_base ++ [_][]const u8{"bzero"}) },
    .{ .name = "arm64win", .called = &llvm_runtime_base_chkstk },
    .{ .name = "arm64v1win", .called = &llvm_runtime_base_chkstk },
    .{ .name = "arm64mingw", .called = &llvm_runtime_base_chkstk },
    .{ .name = "arm64v1mingw", .called = &llvm_runtime_base_chkstk },
};

const llvm_private_runtime_expected_stdout =
    "0.5 0.5 3 4 4 3 4 4 1.8708286933869707 1.8708287 7\n" ++
    "7999999999999999999972 399999999999999999998 3 400000000000000000001 2 0 7999999999999999999972 500000000000000000001 2e21 2e21 3 3\n" ++
    "1199999999 0 0 6000000005 6000000000 3 3\n" ++
    "9.0 0.6 3\n" ++
    "3998 1999 2003 2001 8192 134217728 1026.5";

/// The native target this host runs, if the test builds for it.
fn llvmRuntimeHostTarget() ?[]const u8 {
    const x64 = builtin.cpu.arch == .x86_64;
    const arm64 = builtin.cpu.arch == .aarch64;
    if (builtin.os.tag == .linux and x64) return "x64musl";
    if (builtin.os.tag == .linux and arm64) return "arm64musl";
    if (builtin.os.tag == .macos and x64) return "x64mac";
    if (builtin.os.tag == .macos and arm64) return "arm64mac";
    if (builtin.os.tag == .windows and x64) return "x64win";
    if (builtin.os.tag == .windows and arm64) return "arm64win";
    return null;
}

/// Whether `name` is defined by the private runtime itself, so a reference
/// from it is the runtime's own code rather than code generated for Roc.
fn isPrivateRuntimeCode(name: []const u8) bool {
    for (builtins.shim_symbols.llvm_private_runtime_set) |routine| {
        if (std.mem.eql(u8, name, routine)) return true;
    }
    return std.mem.startsWith(u8, name, "compiler_rt.") or std.mem.startsWith(u8, name, "llvm_private_runtime.");
}

/// The single kept app object a `--keep-temp` build for `target` left under `cache_path`.
fn findKeptLlvmAppObject(io: std.Io, allocator: Allocator, cache_path: []const u8, target: []const u8) CliRunnerError!?[]const u8 {
    const prefix = try std.fmt.allocPrint(allocator, "roc_app_llvm_{s}_speed_", .{target});
    var cache_dir = try std.Io.Dir.cwd().openDir(io, cache_path, .{ .iterate = true });
    defer cache_dir.close(io);
    var walker = try cache_dir.walk(allocator);
    defer walker.deinit();
    var found: ?[]const u8 = null;
    while (try walker.next(io)) |entry| {
        if (entry.kind != .file or !std.mem.startsWith(u8, entry.basename, prefix)) continue;
        // The kept directory also holds the object's bitcode under the same name.
        if (!std.mem.endsWith(u8, entry.basename, ".o")) continue;
        if (found != null) return null;
        found = try std.fs.path.join(allocator, &.{ cache_path, entry.path });
    }
    return found;
}

/// LLVM's code generator lowers some operations to calls (block copies and
/// fills, float remainders, rounding on a CPU without rounding instructions,
/// stack probes on Windows). For every native target, the test program's
/// object must call each of those routines from its own code, define each
/// one locally, and leave no symbol but a `roc_*` one undefined. The program
/// built for this host must also print the right results.
fn customLlvmObjectsLeaveOnlyRocSymbols(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
) ?TestResult {
    const roc_file = "test/cli/LlvmPrivateRuntimeRoutines.roc";
    for (llvm_runtime_targets) |target| {
        if (target.glibc and builtin.os.tag != .linux) continue;
        const output_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, target.name }) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate output path: {}", .{err});
        const out_arg = outputArg(allocator, output_path) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate output arg: {}", .{err});
        const target_arg = std.fmt.allocPrint(allocator, "--target={s}", .{target.name}) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate target arg: {}", .{err});

        if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
            .args = &.{ "build", "--opt=speed", "--no-cache", "--keep-temp", target_arg, out_arg },
            .roc_file = roc_file,
            .contains = &.{.{ .stream = .stdout, .text = "successfully building" }},
        })) |failure| return failure;

        const object_path = (findKeptLlvmAppObject(io, allocator, env.dirs.roc_cache_dir, target.name) catch |err|
            return customInfraFailure(allocator, timer, "failed to search the compiler cache: {}", .{err})) orelse
            return customFailure(allocator, timer, "{s}: expected exactly one kept LLVM app object in {s}", .{ target.name, env.dirs.roc_cache_dir });
        const bytes = std.Io.Dir.cwd().readFileAlloc(io, object_path, allocator, .unlimited) catch |err|
            return customInfraFailure(allocator, timer, "failed to read {s}: {}", .{ object_path, err });
        const object = object_symbols.read(allocator, bytes) catch |err|
            return customFailure(allocator, timer, "{s}: failed to read {s}: {}", .{ target.name, object_path, err });

        for (object.undefined) |name| {
            if (!std.mem.startsWith(u8, name, "roc_")) {
                return customFailure(allocator, timer, "{s}: {s} leaves {s} for its platform to supply", .{ target.name, object_path, name });
            }
        }
        for (target.called) |routine| {
            if (!object.definesLocally(routine)) {
                return customFailure(allocator, timer, "{s}: {s} does not define {s} locally", .{ target.name, object_path, routine });
            }
            const called = for (object.references) |reference| {
                if (std.mem.eql(u8, reference.target, routine) and !isPrivateRuntimeCode(reference.source)) break true;
            } else false;
            if (!called) {
                return customFailure(allocator, timer, "{s}: no code generated for the program in {s} calls {s}", .{ target.name, object_path, routine });
            }
        }
        for (target.defined) |routine| {
            if (!object.defines(routine)) {
                return customFailure(allocator, timer, "{s}: {s} does not define {s}", .{ target.name, object_path, routine });
            }
        }

        const host_target = llvmRuntimeHostTarget() orelse continue;
        if (!std.mem.eql(u8, host_target, target.name)) continue;
        const executable_path = runnableOutputPath(io, allocator, output_path) catch |err|
            return customInfraFailure(allocator, timer, "failed to find built executable: {}", .{err});
        if (runRawAndCheck(io, allocator, env, timer, timeout_ms, &.{ executable_path, "a", "b" }, env.dirs.work_dir, .{
            .args = &.{},
            .stdout_exact = llvm_private_runtime_expected_stdout,
            .stderr_exact = "",
        })) |failure| return failure;
    }
    return null;
}

/// The default platform makes no libc calls, so a default app built for a
/// glibc target must be a static executable that runs on any Linux host of
/// that architecture, whichever libc the host ships.
fn customBuildDefaultAppGlibcDev(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
) ?TestResult {
    if (builtin.os.tag != .linux) return null;
    const target: []const u8 = if (builtin.cpu.arch == .x86_64)
        "x64glibc"
    else if (builtin.cpu.arch == .aarch64)
        "arm64glibc"
    else
        return null;
    return customBuildDefaultAppArgs(io, allocator, env, timer, timeout_ms, .dev, target);
}

const BoxyBuiltEchoApp = struct {
    roc_file: []const u8,
    output_name: []const u8,
    exit: ExitExpectation,
    stdout_exact: []const u8,
};

/// A built platform executable installs the Boxy runtime and registers every
/// dictionary worker's dispatch thunk from its entrypoint, which in-process
/// `roc run` never does.
fn customBoxyBuiltEchoApp(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
    app: BoxyBuiltEchoApp,
) ?TestResult {
    const output_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, app.output_name }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate output path: {}", .{err});
    const out_arg = outputArg(allocator, output_path) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate output arg: {}", .{err});

    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "build", "--opt=size", "--specialize=no", "--no-cache", out_arg },
        .roc_file = app.roc_file,
        .contains = &.{.{ .stream = .stdout, .text = "successfully building" }},
        .not_contains = &.{ .{ .stream = .stderr, .text = "panic" }, .{ .stream = .stderr, .text = "invariant violated" } },
    })) |failure| return failure;

    const executable_path = runnableOutputPath(io, allocator, output_path) catch |err|
        return customInfraFailure(allocator, timer, "failed to find built executable: {}", .{err});

    if (runRawAndCheck(io, allocator, env, timer, timeout_ms, &.{executable_path}, env.dirs.work_dir, .{
        .args = &.{},
        .exit = app.exit,
        .stdout_exact = app.stdout_exact,
        .stderr_exact = "",
    })) |failure| return failure;

    return null;
}

/// Building the module's object-cache pack must preserve alias transparency.
/// `roc check` evaluates the fixture's constants with the specialized
/// evaluator and files them in the checked module, so the `--specialize=no`
/// run that follows restores the stored codecs instead of evaluating them.
fn customIssue12787RestoredCodecs(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
    opt_arg: []const u8,
) ?TestResult {
    const fixture = "test/fx/issue_12787_stored_codec.roc";
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{"check"},
        .roc_file = fixture,
        .exit = .success,
    })) |failure| return failure;
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = allocator.dupe([]const u8, &.{ opt_arg, "--specialize=no" }) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate args: {}", .{err}),
        .roc_file = fixture,
        .exit = .success,
        .stdout_exact = issue_12787_stored_codec_stdout,
    })) |failure| return failure;
    return null;
}

