/// Shared output on COFF: link the dylib test app and its host into one DLL.
/// lld-link resolves the app/host symbol references in a single pass, the
/// same as the ELF and Mach-O shared-library links. Windows-only: it builds
/// for the native target.
fn customWindowsSharedLibrary(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, timeout_ms: u64) ?TestResult {
    if (builtin.os.tag != .windows) return null;

    const dll_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "app.dll" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate dll path: {}", .{err});
    const output_arg = std.fmt.allocPrint(allocator, "--output={s}", .{dll_path}) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate output arg: {}", .{err});

    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "build", "--no-cache", output_arg },
        .roc_file = "test/dylib/app.roc",
        .contains = &.{.{ .stream = .stdout, .text = "successfully building" }},
    })) |failure| return failure;

    const dll_bytes = std.Io.Dir.cwd().readFileAlloc(io, dll_path, allocator, .limited(256 * 1024 * 1024)) catch |err|
        return customInfraFailure(allocator, timer, "failed to read built DLL {s}: {}", .{ dll_path, err });

    // The host's unused canary blob must be dead-stripped from the DLL. A
    // presence check on the used hosted symbol's name would prove nothing
    // here: linked PE images carry no symbol table, so internal names vanish
    // even though the code survives; the ELF and Mach-O shared-library tests
    // cover the positive side.
    if (std.mem.find(u8, dll_bytes, "ROC_DCE_CANARY_BLOB_7f3a9c") != null) {
        return customFailure(allocator, timer, "unused host canary blob was not dead-stripped from the DLL", .{});
    }
    return null;
}

fn customDefaultAppAllSyntaxCheckedCache(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, timeout_ms: u64) ?TestResult {
    const command = CommandCase{
        .args = &.{"--opt=interpreter"},
        .roc_file = "test/echo/all_syntax_test.roc",
        .stdout_exact = all_syntax_expected_stdout,
        .stderr_exact = all_syntax_expected_stderr,
    };

    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, command)) |failure| return failure;

    const cached_module_count_after_first_run = countModuleCacheFiles(io, allocator, env.dirs.roc_cache_dir, "mod") catch |err|
        return customInfraFailure(allocator, timer, "failed to count module cache files: {}", .{err});
    if (cached_module_count_after_first_run == 0) {
        return customFailure(allocator, timer, "expected default app run to populate checked module cache entries before the second run, found 0", .{});
    }

    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, command)) |failure| return failure;

    const cached_module_count_after_second_run = countModuleCacheFiles(io, allocator, env.dirs.roc_cache_dir, "mod") catch |err|
        return customInfraFailure(allocator, timer, "failed to count module cache files after second run: {}", .{err});
    if (cached_module_count_after_second_run != cached_module_count_after_first_run) {
        return customFailure(allocator, timer, "expected second default app run to reuse {d} checked module cache entries, found {d}", .{ cached_module_count_after_first_run, cached_module_count_after_second_run });
    }

    return null;
}

/// An interpreter-mode executable runs every program the interpreter run path
/// runs. The default platform's executable starts without libc and without
/// thread-local storage, so this covers every low-level operation the program
/// reaches in a process where touching a thread-local faults.
fn customBuildAllSyntaxInterpreterOutputRuns(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, timeout_ms: u64) ?TestResult {
    const output_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "all_syntax_interpreter" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate output path: {}", .{err});
    const out_arg = outputArg(allocator, output_path) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate output arg: {}", .{err});

    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "build", "--opt=interpreter", "--no-cache", out_arg },
        .roc_file = "test/echo/all_syntax_test.roc",
        .contains = &.{.{ .stream = .stdout, .text = "successfully building" }},
    })) |failure| return failure;

    const executable_path = runnableOutputPath(io, allocator, output_path) catch |err|
        return customInfraFailure(allocator, timer, "failed to find built executable: {}", .{err});

    if (runRawAndCheck(io, allocator, env, timer, timeout_ms, &.{executable_path}, env.dirs.work_dir, .{
        .args = &.{},
        .stdout_exact = all_syntax_expected_stdout,
        .stderr_exact = all_syntax_expected_stderr,
    })) |failure| return failure;

    return null;
}

/// Only a built executable links list literals as internal static data, so
/// each static-or-fresh list program of issue 12221 is built and then run.
fn customIssue12221StaticOrFreshList(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, timeout_ms: u64, opt: []const u8) ?TestResult {
    const programs = [_]struct { name: []const u8, stdout: []const u8 }{
        .{ .name = "append", .stdout = "0!1!" },
        .{ .name = "return", .stdout = "d0!d1!" },
    };
    const opt_arg = std.fmt.allocPrint(allocator, "--opt={s}", .{opt}) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate opt arg: {}", .{err});
    for (programs) |program| {
        const roc_file = std.fmt.allocPrint(allocator, "test/echo/issue_12221_static_or_fresh_{s}.roc", .{program.name}) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate roc file path: {}", .{err});
        const output_name = std.fmt.allocPrint(allocator, "static_or_fresh_{s}_{s}", .{ program.name, opt }) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate output name: {}", .{err});
        const output_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, output_name }) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate output path: {}", .{err});
        const out_arg = outputArg(allocator, output_path) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate output arg: {}", .{err});

        if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
            .args = &.{ "build", opt_arg, "--no-cache", out_arg },
            .roc_file = roc_file,
            .contains = &.{.{ .stream = .stdout, .text = "successfully building" }},
        })) |failure| return failure;

        const executable_path = runnableOutputPath(io, allocator, output_path) catch |err|
            return customInfraFailure(allocator, timer, "failed to find built executable: {}", .{err});

        if (runRawAndCheck(io, allocator, env, timer, timeout_ms, &.{executable_path}, env.dirs.work_dir, .{
            .args = &.{},
            .stdout_exact = program.stdout,
        })) |failure| return failure;
    }
    return null;
}

/// Normalize one verb's stderr for cross-verb comparison: strip ANSI, cut the
/// per-verb summary header, reduce source-location
/// lines to basename:line:col (check prints absolute paths where the other
/// verbs embed workspace-relative ones), and drop trailing blank lines.
fn parityNormalizedReports(allocator: Allocator, stderr_bytes: []const u8) Allocator.Error![]u8 {
    const stripped = try stripAnsiEscapes(allocator, stderr_bytes);
    const pre_test_summary = preSummaryBytes(stripped);
    const pre_trailer = if (diagnosticSummaryStart(pre_test_summary)) |idx| pre_test_summary[0..idx] else pre_test_summary;

    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    var lines = std.mem.splitScalar(u8, pre_trailer, '\n');
    while (lines.next()) |line| {
        const trimmed = std.mem.trimEnd(u8, line, " \t\r");
        if (std.mem.find(u8, trimmed, ".roc:") != null) {
            if (std.mem.findScalarLast(u8, trimmed, '/')) |slash| {
                try out.appendSlice(allocator, std.mem.trimStart(u8, trimmed[slash + 1 ..], " "));
                try out.append(allocator, '\n');
                continue;
            }
        }
        try out.appendSlice(allocator, trimmed);
        try out.append(allocator, '\n');
    }
    while (std.mem.endsWith(u8, out.items, "\n\n")) _ = out.pop();
    return out.toOwnedSlice(allocator);
}

fn parityCompareVerbs(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
    fixture: []const u8,
    build_output_name: []const u8,
    expected_exits: [4]u32,
    expect_no_ansi: bool,
) ?TestResult {
    const build_out = std.fs.path.join(allocator, &.{ env.dirs.work_dir, build_output_name }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate build output path: {}", .{err});
    const build_out_arg = std.fmt.allocPrint(allocator, "--output={s}", .{build_out}) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate build output arg: {}", .{err});

    const verbs = [_]struct {
        name: []const u8,
        args: []const []const u8,
    }{
        .{ .name = "check", .args = &.{ "--no-color", "check", "--no-cache" } },
        .{ .name = "build", .args = &.{ "--no-color", "build", "--no-cache", build_out_arg } },
        .{ .name = "run", .args = &.{ "--no-color", "--no-cache" } },
        .{ .name = "test", .args = &.{ "--no-color", "test", "--no-cache" } },
    };

    var normalized: [verbs.len][]u8 = undefined;
    for (verbs, 0..) |verb, i| {
        const captured = captureRocRun(io, allocator, env, timer, timeout_ms, .{
            .args = verb.args,
            .roc_file = fixture,
            .exit = .{ .code = expected_exits[i] },
        });
        const result = switch (captured) {
            .failure => |failure| return failure,
            .result => |result| result,
        };
        if (expect_no_ansi) {
            if (expectNoAnsiInPreSummary(allocator, timer, verb.name, result)) |failure| return failure;
        }
        normalized[i] = parityNormalizedReports(allocator, result.stderr) catch |err|
            return customInfraFailure(allocator, timer, "parity normalization failed: {}", .{err});
    }

    for (verbs[1..], 1..) |verb, i| {
        if (!std.mem.eql(u8, normalized[0], normalized[i])) {
            return customFailure(
                allocator,
                timer,
                "pipeline parity violated for {s}: `roc {s}` diagnostics differ from `roc check`\n--- check ---\n{s}\n--- {s} ---\n{s}",
                .{ fixture, verb.name, normalized[0], verb.name, normalized[i] },
            );
        }
    }
    return null;
}

fn customPipelineParityDiagnostics(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, timeout_ms: u64) ?TestResult {
    // Warnings retain the shared exit-2 policy after every verb completes.
    if (parityCompareVerbs(io, allocator, env, timer, timeout_ms, "test/cli/pipeline_parity/warn_app/main.roc", "parity-warn-build-out", .{ 2, 2, 2, 2 }, true)) |failure| return failure;
    // Every verb reports failure for the shared check-phase error, but only
    // after completing all independent work, including build artifact output.
    // Repro for https://github.com/roc-lang/roc/issues/10545.
    if (parityCompareVerbs(io, allocator, env, timer, timeout_ms, "test/cli/pipeline_parity/error_app/main.roc", "parity-error-build-out", .{ 1, 1, 1, 1 }, false)) |failure| return failure;

    const build_out = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "parity-error-build-out" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate build output path: {}", .{err});
    if (!builtOutputExists(io, allocator, build_out)) {
        return customFailure(allocator, timer, "roc build did not emit its requested artifact after reporting a check-phase error", .{});
    }
    return null;
}

/// Count only checked-module cache entries (`.../mod/...`), excluding the shim
/// and linked-executable caches that the run verb also writes under the root.
fn countCheckedModuleCacheFiles(io: std.Io, allocator: Allocator, cache_path: []const u8) CliRunnerError!usize {
    return countModuleCacheFiles(io, allocator, cache_path, "mod");
}

fn customIssue11344Diagnostics(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, timeout_ms: u64) ?TestResult {
    const fixture = "test/cli/issue_11344_shared_ctfe/diagnostics_main.roc";
    const captured = captureRocRun(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "check", "--no-color", "--no-cache", "--jobs=1" },
        .roc_file = fixture,
        .exit = .{ .code = 1 },
        .occurrences = &.{
            .{ .stream = .stderr, .text = "[dbg] \"issue11344-observed\"", .count = 1 },
            .{ .stream = .stderr, .text = "compile time expect failed", .count = 1 },
            .{ .stream = .stderr, .text = "compile time crash", .count = 1 },
        },
        .contains = &.{.{ .stream = .stderr, .text = "Diagnostics.roc" }},
        .not_contains = &.{.{ .stream = .stderr, .text = "panic" }},
    });
    const baseline = switch (captured) {
        .failure => |failure| return failure,
        .result => |result| result,
    };
    // Compare complete transcripts, including root order and dbg observations.
    // The last two invocations share the case's checked-module cache.
    for ([_][]const []const u8{
        &.{ "check", "--no-color", "--no-cache", "--jobs=4" },
        &.{ "check", "--no-color", "--jobs=1" },
        &.{ "check", "--no-color", "--jobs=4" },
    }) |args| {
        if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
            .args = args,
            .roc_file = fixture,
            .exit = .{ .code = 1 },
            .stdout_exact = baseline.stdout,
            .stderr_exact = baseline.stderr,
        })) |failure| return failure;
    }
    return null;
}

fn customIssue11344SharedHelper(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, timeout_ms: u64) ?TestResult {
    const fixture = "test/cli/issue_11344_shared_ctfe/main.roc";
    // The literal call and the runtime argument call request the same Str -> Str
    // specialization. Check must finalize the literal before executable modes.
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "check", "--jobs=4" },
        .roc_file = fixture,
    })) |failure| return failure;
    const checked_cache_entries = countCheckedModuleCacheFiles(io, allocator, env.dirs.roc_cache_dir) catch |err|
        return customInfraFailure(allocator, timer, "failed to count shared-helper module cache entries: {}", .{err});
    if (checked_cache_entries == 0) {
        return customFailure(allocator, timer, "expected shared-helper check to populate the checked-module cache", .{});
    }
    for ([_][]const []const u8{
        &.{ "--opt=dev", "--no-cache", "--jobs=1" },
        &.{ "--opt=dev", "--no-cache", "--jobs=4" },
        &.{ "--opt=dev", "--jobs=1" },
        &.{ "--opt=dev", "--jobs=4" },
    }) |args| {
        if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
            .args = args,
            .roc_file = fixture,
            .app_args = &.{"runtime"},
            .stdout_exact = "shared:constantshared:runtime",
        })) |failure| return failure;
    }
    const archive_out = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "issue11344-archive.a" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate archive output: {}", .{err});
    const archive_out_arg = outputArg(allocator, archive_out) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate archive output arg: {}", .{err});
    // Cross-width layouts must be produced for the runtime target while CTFE
    // still evaluates with the native host layout. Reuse one checked cache.
    for ([_][]const u8{ "--target=x64musl", "--target=wasm32", "--target=x64musl" }) |target_arg| {
        if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
            .args = &.{ "build", "--opt=dev", "--jobs=4", target_arg, archive_out_arg },
            .roc_file = "test/cli/issue_11344_shared_ctfe/archive.roc",
        })) |failure| return failure;
    }
    return null;
}

