fn customSourceFileIdentity(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, timeout_ms: u64) ?TestResult {
    // First and Second are checked independently with the same import list,
    // so their module-local indices collide. Both crashes are local: neither
    // report should invent a foreign origin. Shared can be cached between runs.
    const cases = [_]struct { name: []const u8, args: []const []const u8 }{
        .{ .name = "serial", .args = &.{ "check", "--jobs=1" } },
        .{ .name = "parallel", .args = &.{ "check", "--jobs=4" } },
        .{ .name = "glue", .args = &.{ "glue", "test/cli/source_file_identity/MinimalGlue.roc", env.dirs.work_dir } },
    };
    for (cases) |case| {
        const case_dir = std.fs.path.join(allocator, &.{ env.dirs.work_dir, case.name }) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate source identity case path: {}", .{err});
        const cache_dir = std.fs.path.join(allocator, &.{ case_dir, "roc-cache" }) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate source identity cache path: {}", .{err});
        for (0..2) |run_index| {
            const child_timeout_ms = childCommandTimeoutMs(timer, timeout_ms) orelse
                return timeoutFailure(allocator, timer, .run, "source identity case timed out");
            const result = runRocInCaseEnv(io, allocator, env, case_dir, case.args, "test/cli/source_file_identity/main.roc", child_timeout_ms) catch |err|
                return customInfraFailure(allocator, timer, "source identity command failed to run: {}", .{err});
            if (checkCommandExpectation(allocator, result, .{
                .args = case.args,
                .exit = .{ .code = 1 },
                .contains = &.{
                    .{ .stream = .stderr, .text = "First.roc:5:" },
                    .{ .stream = .stderr, .text = "Second.roc:5:" },
                    .{ .stream = .stderr, .text = "first module failed" },
                    .{ .stream = .stderr, .text = "second module failed" },
                },
                .not_contains = &.{.{ .stream = .stderr, .text = "happened in the module" }},
                .occurrences = &.{.{ .stream = .stderr, .text = "compile time crash", .count = 2 }},
            })) |message| return failureFromRun(allocator, timer, result, message);
            if (run_index == 0) {
                const cached_modules = countCheckedModuleCacheFiles(io, allocator, cache_dir) catch |err|
                    return customInfraFailure(allocator, timer, "failed to count source identity cache files: {}", .{err});
                if (cached_modules == 0) return customFailure(allocator, timer, "source identity case did not populate the module cache", .{});
            }
        }
    }
    return null;
}

fn customPipelineParitySharedCache(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, timeout_ms: u64) ?TestResult {
    const fixture = "test/cli/pipeline_parity/app/main.roc";
    const build_out = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "parity-cache-build-out" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate build output path: {}", .{err});
    const build_out_arg = std.fmt.allocPrint(allocator, "--output={s}", .{build_out}) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate build output arg: {}", .{err});

    // roc check populates the checked-module cache.
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{ .args = &.{"check"}, .roc_file = fixture })) |failure| return failure;
    const after_check = countCheckedModuleCacheFiles(io, allocator, env.dirs.roc_cache_dir) catch |err|
        return customInfraFailure(allocator, timer, "failed to count module cache files: {}", .{err});
    if (after_check == 0) {
        return customFailure(allocator, timer, "expected roc check to populate checked-module cache entries, found 0", .{});
    }

    // Running reuses the same immutable platform module; every
    // executable pipeline hits check's entries without extra module writes.
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{ .args = &.{}, .roc_file = fixture, .contains = &.{.{ .stream = .stdout, .text = "alpha[beta:parity]" }} })) |failure| return failure;
    const after_first_run = countCheckedModuleCacheFiles(io, allocator, env.dirs.roc_cache_dir) catch |err|
        return customInfraFailure(allocator, timer, "failed to count module cache files after run: {}", .{err});
    if (after_first_run != after_check) {
        return customFailure(allocator, timer, "run changed checked-module cache entries: {d} -> {d}", .{ after_check, after_first_run });
    }

    const follow_ups = [_]struct {
        name: []const u8,
        args: []const []const u8,
        /// Entries this step is expected to add the first time it runs. Every
        /// program-producing pipeline reuses exactly what `check` already
        /// wrote, so they add nothing. `roc test` links no program: it checks
        /// the root under explicitly requested roots rather than its app
        /// entrypoint contract, and publishes no executable artifacts, so its
        /// app root has a distinct checking context. Its parametric platform
        /// root is shared by every pipeline, so only the app entry is added.
        added_entries: usize,
    }{
        .{ .name = "run (second)", .args = &.{}, .added_entries = 0 },
        .{ .name = "build", .args = &.{ "build", build_out_arg }, .added_entries = 0 },
        .{ .name = "test", .args = &.{"test"}, .added_entries = 1 },
        .{ .name = "test (second)", .args = &.{"test"}, .added_entries = 0 },
        .{ .name = "check (second)", .args = &.{"check"}, .added_entries = 0 },
        .{ .name = "run (third)", .args = &.{}, .added_entries = 0 },
    };
    var expected_entries = after_first_run;
    for (follow_ups) |step| {
        if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{ .args = step.args, .roc_file = fixture })) |failure| return failure;
        expected_entries += step.added_entries;
        const after = countCheckedModuleCacheFiles(io, allocator, env.dirs.roc_cache_dir) catch |err|
            return customInfraFailure(allocator, timer, "failed to count module cache files after {s}: {}", .{ step.name, err });
        if (after != expected_entries) {
            return customFailure(allocator, timer, "`roc {s}` did not reuse the shared checked-module cache: expected {d} entries, found {d}", .{ step.name, expected_entries, after });
        }
    }
    return null;
}

/// Damage only this case's isolated cache. Command records and referenced
/// module payloads must both be admitted before any observation is replayed.
/// `SharedVal`'s constant is evaluated while `Main` reads it at two joined
/// rows that hold `Conflict` at two payload types. Editing only `Main` makes
/// the second run restore the constant from the cache, at the row its
/// declaring module gives it, and widen it into `Main`'s joined row.
fn customStoredRootDeclaredRow(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, timeout_ms: u64, backend: OptMode) ?TestResult {
    const opt_arg = backendOptArg(allocator, backend) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate opt arg: {}", .{err});
    const dir = createWorkSubdir(io, allocator, env, "stored_root_declared_row") catch |err|
        return customInfraFailure(allocator, timer, "failed to create fixture dir: {}", .{err});
    var main_source: []const u8 = "";
    for ([_][]const u8{ "SharedVal.roc", "Main.roc" }) |name| {
        const from = std.fs.path.join(allocator, &.{ "test/cli/stored_root_declared_row", name }) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate fixture path: {}", .{err});
        const from_abs = absoluteFromProjectRoot(allocator, from) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate fixture path: {}", .{err});
        const source = std.Io.Dir.cwd().readFileAlloc(io, from_abs, allocator, .limited(1024 * 1024)) catch |err|
            return customInfraFailure(allocator, timer, "failed to read {s}: {}", .{ from_abs, err });
        if (writeCaseFile(io, allocator, timer, dir, name, source)) |failure| return failure;
        if (std.mem.eql(u8, name, "Main.roc")) main_source = source;
    }
    const main_path = std.fs.path.join(allocator, &.{ dir, "Main.roc" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate main path: {}", .{err});
    const not_contains = [_]OutputNeedle{
        .{ .stream = .stderr, .text = "panic" },
        .{ .stream = .stderr, .text = "invariant violated" },
    };
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "test", opt_arg },
        .roc_file = main_path,
        .exit = .success,
        .contains = &.{.{ .stream = .stdout, .text = "All (2) tests passed" }},
        .not_contains = &not_contains,
    })) |failure| return failure;
    const edited = std.fmt.allocPrint(allocator, "{s}\nexpect describe_b(fwd_b({{}})) != \"conflict\"\n", .{main_source}) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate edited main: {}", .{err});
    if (writeCaseFile(io, allocator, timer, dir, "Main.roc", edited)) |failure| return failure;
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "test", opt_arg },
        .roc_file = main_path,
        .exit = .success,
        .contains = &.{.{ .stream = .stdout, .text = "All (3) tests passed" }},
        .not_contains = &not_contains,
    })) |failure| return failure;
    return null;
}

// Each module stores encoders built at one instantiation of a builder whose
// local format type's string method reads the builder's type variable. The
// first run evaluates and caches them; the second restores them from that
// cache. Both must encode with the instantiated variable.
fn customLocalFormatOuterTypeVarCache(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
) ?TestResult {
    const modules = [_][]const u8{
        "test/cli/local_format_outer_type_var/ApplesOuterTypeVar.roc",
        "test/cli/local_format_outer_type_var/PearsOuterTypeVar.roc",
    };
    for (modules) |module| {
        for (0..2) |_| {
            if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
                .args = &.{ "test", "--specialize=yes" },
                .roc_file = module,
                .exit = .success,
                .contains = &.{.{ .stream = .stdout, .text = "All (2) tests passed" }},
                .not_contains = &.{
                    .{ .stream = .stderr, .text = "invariant violated" },
                    .{ .stream = .stderr, .text = "panic" },
                },
            })) |failure| return failure;
        }
    }
    return null;
}

// Test and executable checking must accept each other's partial module caches.
/// `roc build` leaves the app's unread initializer pending and caches the
/// `Color` module it imports; `roc test` then makes `Color` the program root
/// and validates that initializer, whose type is the nominal `Color`
/// declares. Repeating the test runs it against a fully cached program.
fn customIssue12859BuildThenTest(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
    backend: OptMode,
    specialize: []const u8,
) ?TestResult {
    const app = "test/cli/issue_12859_build_then_test/main.roc";
    const opt_arg = backendOptArg(allocator, backend) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate opt arg: {}", .{err});
    const output_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "issue_12859_app" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate output path: {}", .{err});
    const output = outputArg(allocator, output_path) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate output arg: {}", .{err});
    const not_contains = [_]OutputNeedle{
        .{ .stream = .stderr, .text = "panic" },
        .{ .stream = .stderr, .text = "invariant violated" },
    };
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "build", opt_arg, specialize, output },
        .roc_file = app,
        .exit = .success,
        .not_contains = &not_contains,
    })) |failure| return failure;
    for (0..2) |_| {
        if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
            .args = &.{ "test", opt_arg, specialize, "-j1" },
            .roc_file = app,
            .exit = .success,
            .contains = &.{.{ .stream = .stdout, .text = "All (1) tests passed" }},
            .not_contains = &not_contains,
        })) |failure| return failure;
    }
    return null;
}

