fn customBuildIssue9435(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, timeout_ms: u64) ?TestResult {
    const output_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "hosted_nominal_return" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate output path: {}", .{err});
    const out_arg = outputArg(allocator, output_path) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate output arg: {}", .{err});
    const child_timeout_ms = childCommandTimeoutMs(timer, timeout_ms) orelse
        return timeoutFailure(allocator, timer, .run, "case timeout exhausted before roc build started");
    const result = runRocInEnv(io, allocator, env, &.{ "build", "--opt=dev", "--no-cache", out_arg }, "test/hosted_nominal_return/repro.roc", .absolute, &.{}, null, child_timeout_ms) catch |err|
        return customInfraFailure(allocator, timer, "roc build spawn error: {}", .{err});
    if (result.term == .signal or (result.term == .exited and result.term.exited == 134)) {
        return failureFromRun(allocator, timer, result, "roc build panicked or aborted");
    }
    if (std.mem.find(u8, result.stderr, "panic") != null or
        std.mem.find(u8, result.stderr, "mono nominal materialization") != null or
        std.mem.find(u8, result.stderr, "published instantiated nominal backing") != null)
    {
        return failureFromRun(allocator, timer, result, "roc build output contained forbidden panic/regression text");
    }
    return null;
}

fn customBundleComplexPackage(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, timeout_ms: u64) ?TestResult {
    const out_dir = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "bundle-out" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate bundle output dir: {}", .{err});
    std.Io.Dir.cwd().createDirPath(io, out_dir) catch |err|
        return customInfraFailure(allocator, timer, "failed to create bundle output dir: {}", .{err});
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "bundle", "--output-dir", out_dir, "test/complex_package/main.roc" },
        .contains = &.{.{ .stream = .stdout, .text = "Created:" }},
        .not_contains = &.{.{ .stream = .stderr, .text = "missing from bundle" }},
    })) |failure| return failure;
    return null;
}

/// Repro for https://github.com/roc-lang/roc/issues/10845
fn customBundleEntrypointSubdirectory(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, timeout_ms: u64) ?TestResult {
    const package_dir = createWorkSubdir(io, allocator, env, "bundle-subdir") catch |err|
        return customInfraFailure(allocator, timer, "failed to create package dir: {}", .{err});
    const src_dir = std.fs.path.join(allocator, &.{ package_dir, "src" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate src dir: {}", .{err});
    std.Io.Dir.cwd().createDirPath(io, src_dir) catch |err|
        return customInfraFailure(allocator, timer, "failed to create src dir: {}", .{err});

    const package_main = std.fs.path.join(allocator, &.{ src_dir, "main.roc" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate main.roc path: {}", .{err});
    std.Io.Dir.cwd().writeFile(io, .{ .sub_path = package_main, .data = "package [Helper] {}\n" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to write main.roc: {}", .{err});
    const package_helper = std.fs.path.join(allocator, &.{ src_dir, "Helper.roc" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate Helper.roc path: {}", .{err});
    std.Io.Dir.cwd().writeFile(io, .{ .sub_path = package_helper, .data = "module []\n\nhelper : U64\nhelper = 42\n" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to write Helper.roc: {}", .{err});
    const outside_module = std.fs.path.join(allocator, &.{ package_dir, "Outside.roc" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate outside module path: {}", .{err});
    std.Io.Dir.cwd().writeFile(io, .{ .sub_path = outside_module, .data = "module []\n" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to write outside module: {}", .{err});

    const out_dir = createWorkSubdir(io, allocator, env, "bundle-subdir-out") catch |err|
        return customInfraFailure(allocator, timer, "failed to create bundle output dir: {}", .{err});
    const extract_dir = createWorkSubdir(io, allocator, env, "bundle-subdir-extract") catch |err|
        return customInfraFailure(allocator, timer, "failed to create extract dir: {}", .{err});

    const roc_abs = if (std.fs.path.isAbsolute(roc_binary_path))
        roc_binary_path
    else
        std.fs.path.join(allocator, &.{ project_root_path, roc_binary_path }) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate roc path: {}", .{err});

    const bundle_timeout = childCommandTimeoutMs(timer, timeout_ms) orelse
        return timeoutFailure(allocator, timer, .run, "case timeout exhausted before bundling");
    const bundle_result = runRawInEnv(io, allocator, env, &.{ roc_abs, "bundle", "--output-dir", out_dir, "src/main.roc" }, package_dir, null, bundle_timeout) catch |err|
        return customInfraFailure(allocator, timer, "bundle spawn error: {}", .{err});
    if (exitCode(bundle_result.term) != 0) {
        return failureFromRun(allocator, timer, bundle_result, "roc bundle failed");
    }
    const created_prefix = "Created: ";
    const created_idx = std.mem.find(u8, bundle_result.stdout, created_prefix) orelse
        return failureFromRun(allocator, timer, bundle_result, "roc bundle did not report a created file");
    const created_rest = bundle_result.stdout[created_idx + created_prefix.len ..];
    const created_eol = std.mem.find(u8, created_rest, "\n") orelse created_rest.len;
    const bundle_path = std.mem.trim(u8, created_rest[0..created_eol], " \r");
    const bundle_filename = std.fs.path.basename(bundle_path);
    if (!std.mem.endsWith(u8, bundle_filename, ".tar.zst")) {
        return failureFromRun(allocator, timer, bundle_result, "roc bundle did not create a .tar.zst archive");
    }
    const extracted_name = bundle_filename[0 .. bundle_filename.len - ".tar.zst".len];

    const unbundle_timeout = childCommandTimeoutMs(timer, timeout_ms) orelse
        return timeoutFailure(allocator, timer, .run, "case timeout exhausted before unbundling");
    const unbundle_result = runRawInEnv(io, allocator, env, &.{ roc_abs, "unbundle", bundle_path }, extract_dir, null, unbundle_timeout) catch |err|
        return customInfraFailure(allocator, timer, "unbundle spawn error: {}", .{err});
    if (exitCode(unbundle_result.term) != 0) {
        return failureFromRun(allocator, timer, unbundle_result, "roc unbundle failed");
    }

    const extracted_root = std.fs.path.join(allocator, &.{ extract_dir, extracted_name }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate extracted root path: {}", .{err});

    for ([_][]const u8{ "main.roc", "Helper.roc" }) |entry| {
        const entry_path = std.fs.path.join(allocator, &.{ extracted_root, entry }) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate extracted entry path: {}", .{err});
        std.Io.Dir.cwd().access(io, entry_path, .{}) catch |err|
            return customFailure(allocator, timer, "bundle of src/main.roc is missing {s} at its root: {}", .{ entry, err });
    }

    const extracted_src = std.fs.path.join(allocator, &.{ extracted_root, "src" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate extracted src path: {}", .{err});
    if (std.Io.Dir.cwd().access(io, extracted_src, .{})) |_| {
        return customFailure(allocator, timer, "bundle of src/main.roc kept the src/ directory inside the archive", .{});
    } else |_| {}

    // Raising the archive root to include an outside file would put main.roc
    // below src/ again. Refuse that unrepresentable layout explicitly.
    const outside_timeout = childCommandTimeoutMs(timer, timeout_ms) orelse
        return timeoutFailure(allocator, timer, .run, "case timeout exhausted before outside-root bundle check");
    const outside_result = runRawInEnv(io, allocator, env, &.{ roc_abs, "bundle", "--output-dir", out_dir, "src/main.roc", "Outside.roc" }, package_dir, null, outside_timeout) catch |err|
        return customInfraFailure(allocator, timer, "outside-root bundle spawn error: {}", .{err});
    if (exitCode(outside_result.term) == 0) {
        return failureFromRun(allocator, timer, outside_result, "roc bundle accepted a file outside the entry point directory");
    }
    if (std.mem.find(u8, outside_result.stderr, "outside the entry point directory") == null) {
        return failureFromRun(allocator, timer, outside_result, "roc bundle did not explain the outside-root file error");
    }

    return null;
}

/// Repro for https://github.com/roc-lang/roc/issues/12565
fn customBundleIssue12565MainRocRoot(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, timeout_ms: u64) ?TestResult {
    const platform_dir = createWorkSubdir(io, allocator, env, "bundle-12565") catch |err|
        return customInfraFailure(allocator, timer, "failed to create platform dir: {}", .{err});
    const target_dir = std.fs.path.join(allocator, &.{ platform_dir, "targets", "x64musl" }) catch |err|
        return customInfraFailure(allocator, timer, "target dir path: {}", .{err});
    std.Io.Dir.cwd().createDirPath(io, target_dir) catch |err|
        return customInfraFailure(allocator, timer, "create target dir: {}", .{err});

    // `User` calls the hosted `Sink.push!`, which only has a value when the
    // build roots at the platform header that publishes it.
    const files = [_]struct { path: []const u8, contents: []const u8 }{
        .{ .path = "main.roc", .contents =
        \\platform ""
        \\    requires {} { main! : () => {} }
        \\    exposes [Sink, User]
        \\    packages {}
        \\    provides { "roc_main": main_for_host! }
        \\    hosted {
        \\        "roc_sink_push": Sink.push!,
        \\    }
        \\    targets: {
        \\        inputs_dir: "targets/",
        \\        x64musl: { inputs: ["libhost.a", app] },
        \\    }
        \\
        \\import Sink
        \\import User
        \\
        \\main_for_host! : () => {}
        \\main_for_host! = main!
        \\
        },
        .{ .path = "Sink.roc", .contents = "Sink := [].{\n    push! : Str => {}\n}\n" },
        .{ .path = "User.roc", .contents = "import Sink\n\nUser := [].{\n    go! : Str => {}\n    go! = |s| Sink.push!(s)\n}\n" },
        .{ .path = "targets/x64musl/libhost.a", .contents = "" },
    };
    for (files) |file| {
        const path = std.fs.path.join(allocator, &.{ platform_dir, file.path }) catch |err|
            return customInfraFailure(allocator, timer, "fixture path: {}", .{err});
        std.Io.Dir.cwd().writeFile(io, .{ .sub_path = path, .data = file.contents }) catch |err|
            return customInfraFailure(allocator, timer, "write fixture: {}", .{err});
    }

    const out_dir = createWorkSubdir(io, allocator, env, "bundle-12565-out") catch |err|
        return customInfraFailure(allocator, timer, "failed to create bundle output dir: {}", .{err});

    const roc_abs = if (std.fs.path.isAbsolute(roc_binary_path))
        roc_binary_path
    else
        std.fs.path.join(allocator, &.{ project_root_path, roc_binary_path }) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate roc path: {}", .{err});

    const orders = [_][]const []const u8{
        &.{ "User.roc", "Sink.roc", "main.roc" },
        &.{ "main.roc", "User.roc", "Sink.roc" },
    };
    var first_bundle_filename: ?[]const u8 = null;
    for (orders) |order| {
        const bundle_timeout = childCommandTimeoutMs(timer, timeout_ms) orelse
            return timeoutFailure(allocator, timer, .run, "case timeout exhausted before bundling");
        const argv = std.mem.concat(allocator, []const u8, &.{ &.{ roc_abs, "bundle", "--output-dir", out_dir }, order }) catch |err|
            return customInfraFailure(allocator, timer, "bundle argv: {}", .{err});
        const bundle_result = runRawInEnv(io, allocator, env, argv, platform_dir, null, bundle_timeout) catch |err|
            return customInfraFailure(allocator, timer, "bundle spawn error: {}", .{err});
        if (exitCode(bundle_result.term) != 0) {
            return failureFromRun(allocator, timer, bundle_result, "roc bundle failed");
        }
        if (std.mem.find(u8, bundle_result.stderr, "has no value") != null) {
            return failureFromRun(allocator, timer, bundle_result, "roc bundle checked hosted declarations without their platform");
        }
        const created_prefix = "Created: ";
        const created_idx = std.mem.find(u8, bundle_result.stdout, created_prefix) orelse
            return failureFromRun(allocator, timer, bundle_result, "roc bundle did not report a created file");
        const created_rest = bundle_result.stdout[created_idx + created_prefix.len ..];
        const created_eol = std.mem.find(u8, created_rest, "\n") orelse created_rest.len;
        const bundle_filename = std.fs.path.basename(std.mem.trim(u8, created_rest[0..created_eol], " \r"));
        if (first_bundle_filename) |first| {
            if (!std.mem.eql(u8, first, bundle_filename)) {
                return customFailure(allocator, timer, "argument order changed the bundle: {s} vs {s}", .{ first, bundle_filename });
            }
        } else {
            first_bundle_filename = bundle_filename;
        }
    }

    // Without a main.roc the bundle has no package root consumers could load.
    const rootless_timeout = childCommandTimeoutMs(timer, timeout_ms) orelse
        return timeoutFailure(allocator, timer, .run, "case timeout exhausted before rootless bundle check");
    const rootless_result = runRawInEnv(io, allocator, env, &.{ roc_abs, "bundle", "--output-dir", out_dir, "User.roc", "Sink.roc" }, platform_dir, null, rootless_timeout) catch |err|
        return customInfraFailure(allocator, timer, "rootless bundle spawn error: {}", .{err});
    if (exitCode(rootless_result.term) == 0) {
        return failureFromRun(allocator, timer, rootless_result, "roc bundle accepted files without their package's main.roc");
    }
    if (std.mem.find(u8, rootless_result.stderr, "must include its package's main.roc") == null) {
        return failureFromRun(allocator, timer, rootless_result, "roc bundle did not explain the missing main.roc");
    }

    return null;
}

/// Repro for https://github.com/roc-lang/roc/issues/11907
fn customBundleFileImports(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, timeout_ms: u64) ?TestResult {
    const package_dir = createWorkSubdir(io, allocator, env, "bundle-files") catch |err|
        return customInfraFailure(allocator, timer, "failed to create package dir: {}", .{err});
    const src_dir = std.fs.path.join(allocator, &.{ package_dir, "src" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate src dir: {}", .{err});
    std.Io.Dir.cwd().createDirPath(io, src_dir) catch |err|
        return customInfraFailure(allocator, timer, "failed to create src dir: {}", .{err});

    const nested_dir = std.fs.path.join(allocator, &.{ src_dir, "Nested" }) catch |err|
        return customInfraFailure(allocator, timer, "nested path: {}", .{err});
    std.Io.Dir.cwd().createDirPath(io, nested_dir) catch |err|
        return customInfraFailure(allocator, timer, "create nested dir: {}", .{err});
    const files = [_]struct { path: []const u8, contents: []const u8 }{
        .{ .path = "main.roc", .contents = "package [Helper] { nested: \"Nested/main.roc\" }\n" },
        .{ .path = "Helper.roc", .contents = "import nested.Data\nimport \"bytes.bin\" as bytes : List(U8)\nHelper :: [].{\n    size : {} -> U64\n    size = |_| bytes.len() + Data.size({})\n}\n" },
        .{ .path = "Nested/main.roc", .contents = "package [Data] {}\n" },
        .{ .path = "Nested/Data.roc", .contents = "import \"../bytes.bin\" as bytes : List(U8)\nimport \"text.txt\" as text : Str\nData :: [].{\n    size : {} -> U64\n    size = |_| bytes.len() + text.count_utf8_bytes()\n}\n" },
        .{ .path = "bytes.bin", .contents = "\x00\xff\x80\x01" },
        .{ .path = "Nested/text.txt", .contents = "bundled text\n" },
    };
    for (files) |file| {
        const path = std.fs.path.join(allocator, &.{ src_dir, file.path }) catch |err|
            return customInfraFailure(allocator, timer, "fixture path: {}", .{err});
        std.Io.Dir.cwd().writeFile(io, .{ .sub_path = path, .data = file.contents }) catch |err|
            return customInfraFailure(allocator, timer, "write fixture: {}", .{err});
    }

    const out_dir = createWorkSubdir(io, allocator, env, "bundle-files-out") catch |err|
        return customInfraFailure(allocator, timer, "failed to create bundle output dir: {}", .{err});
    const extract_dir = createWorkSubdir(io, allocator, env, "bundle-files-extract") catch |err|
        return customInfraFailure(allocator, timer, "failed to create extract dir: {}", .{err});

    const roc_abs = if (std.fs.path.isAbsolute(roc_binary_path))
        roc_binary_path
    else
        std.fs.path.join(allocator, &.{ project_root_path, roc_binary_path }) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate roc path: {}", .{err});

    const bundle_timeout = childCommandTimeoutMs(timer, timeout_ms) orelse
        return timeoutFailure(allocator, timer, .run, "case timeout exhausted before bundling");
    const bundle_result = runRawInEnv(io, allocator, env, &.{ roc_abs, "bundle", "--output-dir", out_dir, "src/main.roc" }, package_dir, null, bundle_timeout) catch |err|
        return customInfraFailure(allocator, timer, "bundle spawn error: {}", .{err});
    if (exitCode(bundle_result.term) != 0) {
        return failureFromRun(allocator, timer, bundle_result, "roc bundle failed");
    }
    const created_prefix = "Created: ";
    const created_idx = std.mem.find(u8, bundle_result.stdout, created_prefix) orelse
        return failureFromRun(allocator, timer, bundle_result, "roc bundle did not report a created file");
    const created_rest = bundle_result.stdout[created_idx + created_prefix.len ..];
    const created_eol = std.mem.find(u8, created_rest, "\n") orelse created_rest.len;
    const bundle_path = std.mem.trim(u8, created_rest[0..created_eol], " \r");
    const bundle_filename = std.fs.path.basename(bundle_path);
    if (!std.mem.endsWith(u8, bundle_filename, ".tar.zst")) {
        return failureFromRun(allocator, timer, bundle_result, "roc bundle did not create a .tar.zst archive");
    }
    const extracted_name = bundle_filename[0 .. bundle_filename.len - ".tar.zst".len];

    const checked_entries = countCheckedModuleCacheFiles(io, allocator, env.dirs.roc_cache_dir) catch |err|
        return customInfraFailure(allocator, timer, "count checked cache entries: {}", .{err});
    if (checked_entries == 0) {
        return customFailure(allocator, timer, "bundle did not populate the checked-module cache", .{});
    }

    // A second build uses the checked cache; both bundles must have the
    // same content hash, including dependencies shared by two modules.
    const warm_timeout = childCommandTimeoutMs(timer, timeout_ms) orelse
        return timeoutFailure(allocator, timer, .run, "timeout before warm bundle");
    const warm_result = runRawInEnv(io, allocator, env, &.{ roc_abs, "bundle", "--output-dir", out_dir, "src/main.roc", "src/Helper.roc", "src/bytes.bin" }, package_dir, null, warm_timeout) catch |err|
        return customInfraFailure(allocator, timer, "warm bundle: {}", .{err});
    if (exitCode(warm_result.term) != 0 or std.mem.find(u8, warm_result.stdout, bundle_filename) == null) {
        return failureFromRun(allocator, timer, warm_result, "warm bundle with explicit duplicate changed the archive");
    }

    const unbundle_timeout = childCommandTimeoutMs(timer, timeout_ms) orelse
        return timeoutFailure(allocator, timer, .run, "case timeout exhausted before unbundling");
    const unbundle_result = runRawInEnv(io, allocator, env, &.{ roc_abs, "unbundle", bundle_path }, extract_dir, null, unbundle_timeout) catch |err|
        return customInfraFailure(allocator, timer, "unbundle spawn error: {}", .{err});
    if (exitCode(unbundle_result.term) != 0) {
        return failureFromRun(allocator, timer, unbundle_result, "roc unbundle failed");
    }

    const extracted_root = std.fs.path.join(allocator, &.{ extract_dir, extracted_name }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate extracted root path: {}", .{err});

    for (files) |file| {
        const path = std.fs.path.join(allocator, &.{ extracted_root, file.path }) catch |err|
            return customInfraFailure(allocator, timer, "extracted path: {}", .{err});
        const contents = std.Io.Dir.cwd().readFileAlloc(io, path, allocator, .limited(4096)) catch |err|
            return customFailure(allocator, timer, "missing extracted {s}: {}", .{ file.path, err });
        if (!std.mem.eql(u8, contents, file.contents)) {
            return customFailure(allocator, timer, "extracted {s} contents differ", .{file.path});
        }
    }
    const check_timeout = childCommandTimeoutMs(timer, timeout_ms) orelse
        return timeoutFailure(allocator, timer, .run, "timeout before extracted package check");
    const check_result = runRawInEnv(io, allocator, env, &.{ roc_abs, "check", "--no-cache", "main.roc" }, extracted_root, null, check_timeout) catch |err|
        return customInfraFailure(allocator, timer, "check extracted package: {}", .{err});
    if (exitCode(check_result.term) != 0) {
        return failureFromRun(allocator, timer, check_result, "extracted package failed to check");
    }

    const bytes_path = std.fs.path.join(allocator, &.{ src_dir, "bytes.bin" }) catch |err|
        return customInfraFailure(allocator, timer, "bytes path: {}", .{err});
    std.Io.Dir.cwd().deleteFile(io, bytes_path) catch |err|
        return customInfraFailure(allocator, timer, "remove imported file: {}", .{err});
    const missing_timeout = childCommandTimeoutMs(timer, timeout_ms) orelse
        return timeoutFailure(allocator, timer, .run, "timeout before missing file check");
    const missing_result = runRawInEnv(io, allocator, env, &.{ roc_abs, "bundle", "--output-dir", out_dir, "src/main.roc" }, package_dir, null, missing_timeout) catch |err|
        return customInfraFailure(allocator, timer, "missing file bundle: {}", .{err});
    if (exitCode(missing_result.term) == 0 or
        std.mem.find(u8, missing_result.stderr, "bytes.bin") == null or
        std.mem.find(u8, missing_result.stdout, "Created: ") != null)
    {
        return failureFromRun(allocator, timer, missing_result, "missing imported file must fail bundling with a diagnostic");
    }

    std.Io.Dir.cwd().writeFile(io, .{ .sub_path = bytes_path, .data = "\x00\xff\x80\x01" }) catch |err|
        return customInfraFailure(allocator, timer, "restore imported file: {}", .{err});

    // An imported file outside the entry directory cannot retain its relative
    // path in a portable archive. Reject it rather than silently omitting it.
    const helper_path = std.fs.path.join(allocator, &.{ src_dir, "Helper.roc" }) catch |err|
        return customInfraFailure(allocator, timer, "helper path: {}", .{err});
    std.Io.Dir.cwd().writeFile(io, .{ .sub_path = helper_path, .data = "import \"../outside.txt\" as text : Str\nHelper :: [].{\n    size : {} -> U64\n    size = |_| text.count_utf8_bytes()\n}\n" }) catch |err|
        return customInfraFailure(allocator, timer, "write outside import: {}", .{err});
    const outside_path = std.fs.path.join(allocator, &.{ package_dir, "outside.txt" }) catch |err|
        return customInfraFailure(allocator, timer, "outside path: {}", .{err});
    std.Io.Dir.cwd().writeFile(io, .{ .sub_path = outside_path, .data = "outside" }) catch |err|
        return customInfraFailure(allocator, timer, "write outside file: {}", .{err});
    const outside_timeout = childCommandTimeoutMs(timer, timeout_ms) orelse
        return timeoutFailure(allocator, timer, .run, "timeout before outside import check");
    const outside_result = runRawInEnv(io, allocator, env, &.{ roc_abs, "bundle", "--output-dir", out_dir, "src/main.roc" }, package_dir, null, outside_timeout) catch |err|
        return customInfraFailure(allocator, timer, "outside import bundle: {}", .{err});
    if (exitCode(outside_result.term) == 0 or
        std.mem.find(u8, outside_result.stderr, "outside the entry point directory") == null or
        std.mem.find(u8, outside_result.stdout, "Created: ") != null)
    {
        return failureFromRun(allocator, timer, outside_result, "outside import must fail bundling with a diagnostic");
    }

    return null;
}

/// Repro for https://github.com/roc-lang/roc/issues/11608
/// `roc bundle --output-dir <dir>` must succeed even when the output directory
/// lives on a different filesystem than the working directory. Expected:
/// the archive is created inside the output directory and the command exits 0.
/// (When the bug was live, the bundler renamed a cwd-local temp file into the
/// output directory and failed with error.CrossDevice.)
fn customBundleIssue11608OutputDirCrossDevice(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, timeout_ms: u64) ?TestResult {
    if (builtin.os.tag != .linux) {
        return .{ .status = .skip, .phase = .setup, .duration_ns = timer.read(), .message = "cross-device bundle fixture requires Linux /dev/shm" };
    }
    const package_dir = createWorkSubdir(io, allocator, env, "bundle-crossfs") catch |err|
        return customInfraFailure(allocator, timer, "failed to create package dir: {}", .{err});

    const package_main = std.fs.path.join(allocator, &.{ package_dir, "main.roc" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate main.roc path: {}", .{err});
    std.Io.Dir.cwd().writeFile(io, .{ .sub_path = package_main, .data = "package [Helper] {}\n" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to write main.roc: {}", .{err});
    const package_helper = std.fs.path.join(allocator, &.{ package_dir, "Helper.roc" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate Helper.roc path: {}", .{err});
    std.Io.Dir.cwd().writeFile(io, .{ .sub_path = package_helper, .data = "module []\n\nhelper : U64\nhelper = 42\n" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to write Helper.roc: {}", .{err});

    // Linux CI supplies /dev/shm as a separate tmpfs mount. Prove the fixture
    // crosses filesystems so this test cannot silently become same-device coverage.
    var output_root = std.Io.Dir.openDirAbsolute(io, "/dev/shm", .{}) catch |err|
        return customInfraFailure(allocator, timer, "cross-device bundle test requires /dev/shm: {}", .{err});
    defer output_root.close(io);
    var random: [16]u8 = undefined;
    io.random(&random);
    const hex = std.fmt.bytesToHex(random, .lower);
    const out_name = std.fmt.allocPrint(allocator, "roc-bundle-11608-{s}", .{hex}) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate output name: {}", .{err});
    // createDir (not createDirPath) establishes ownership before cleanup is armed.
    output_root.createDir(io, out_name, .default_dir) catch |err|
        return customInfraFailure(allocator, timer, "failed to create cross-device output directory: {}", .{err});
    defer output_root.deleteTree(io, out_name) catch {};
    const out_dir_final = std.fs.path.join(allocator, &.{ "/dev/shm", out_name }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate output path: {}", .{err});
    var output_dir = output_root.openDir(io, out_name, .{ .iterate = true }) catch |err|
        return customInfraFailure(allocator, timer, "failed to open output directory: {}", .{err});
    defer output_dir.close(io);
    var package_dir_handle = std.Io.Dir.openDirAbsolute(io, package_dir, .{}) catch |err|
        return customInfraFailure(allocator, timer, "failed to open package directory: {}", .{err});
    defer package_dir_handle.close(io);
    const probe_name = "cross-device-probe";
    package_dir_handle.writeFile(io, .{ .sub_path = probe_name, .data = "probe" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to write cross-device probe: {}", .{err});
    defer package_dir_handle.deleteFile(io, probe_name) catch {};
    var cross_device = false;
    package_dir_handle.rename(probe_name, output_dir, probe_name, io) catch |err| switch (err) {
        error.CrossDevice => cross_device = true,
        else => return customInfraFailure(allocator, timer, "cross-device probe failed: {}", .{err}),
    };
    if (!cross_device) return customInfraFailure(allocator, timer, "/dev/shm must be on a different filesystem from the test workspace", .{});

    const roc_abs = if (std.fs.path.isAbsolute(roc_binary_path))
        roc_binary_path
    else
        std.fs.path.join(allocator, &.{ project_root_path, roc_binary_path }) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate roc path: {}", .{err});

    const bundle_timeout = childCommandTimeoutMs(timer, timeout_ms) orelse
        return timeoutFailure(allocator, timer, .run, "case timeout exhausted before bundling");
    const bundle_result = runRawInEnv(io, allocator, env, &.{ roc_abs, "bundle", "--output-dir", out_dir_final, "main.roc" }, package_dir, null, bundle_timeout) catch |err|
        return customInfraFailure(allocator, timer, "bundle spawn error: {}", .{err});
    if (exitCode(bundle_result.term) != 0) {
        return failureFromRun(allocator, timer, bundle_result, "roc bundle failed when --output-dir is on a different filesystem than the working directory");
    }
    const created_prefix = "Created: ";
    const created_idx = std.mem.find(u8, bundle_result.stdout, created_prefix) orelse
        return failureFromRun(allocator, timer, bundle_result, "roc bundle did not report a created file");
    const created_rest = bundle_result.stdout[created_idx + created_prefix.len ..];
    const created_eol = std.mem.find(u8, created_rest, "\n") orelse created_rest.len;
    // roc names the archive relative to the directory it ran in.
    const created_path = std.fs.path.resolve(allocator, &.{ package_dir, std.mem.trim(u8, created_rest[0..created_eol], " \r") }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate created path: {}", .{err});
    if (!std.mem.eql(u8, std.fs.path.dirname(created_path) orelse "", out_dir_final)) {
        return customFailure(allocator, timer, "roc bundle reported the archive at '{s}' instead of inside the requested output dir '{s}'", .{ created_path, out_dir_final });
    }
    const archive_filename = std.fs.path.basename(created_path);
    const archive_path = std.fs.path.join(allocator, &.{ out_dir_final, archive_filename }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate archive path: {}", .{err});
    std.Io.Dir.cwd().access(io, archive_path, .{}) catch |err|
        return customFailure(allocator, timer, "roc bundle did not leave the archive in the output dir: {}", .{err});

    var output_iter = output_dir.iterate();
    while (output_iter.next(io) catch |err|
        return customInfraFailure(allocator, timer, "failed to list bundle output: {}", .{err})) |entry|
    {
        if (!std.mem.eql(u8, entry.name, archive_filename)) {
            return customFailure(allocator, timer, "bundle left unexpected output '{s}'", .{entry.name});
        }
    }

    return null;
}

/// Serves one HTTP request from a background thread: reads whatever arrives,
/// responds with the bundle bytes, and exits. `roc install` performs exactly
/// one download in the roundtrip below; every later step must work offline.
const InstallBundleServer = struct {
    server: *std.Io.net.Server,
    bundle_data: []const u8,
    io: std.Io,

    const ServeError = std.Io.net.Server.AcceptError || std.Io.net.Stream.Reader.Error || std.Io.net.Stream.Writer.Error || std.Io.Writer.Error || error{ NoSpaceLeft, ReadFailed };

    fn run(ctx: *@This()) void {
        ctx.serveOne() catch {};
    }

    fn serveOne(ctx: *@This()) ServeError!void {
        const stream = try ctx.server.accept(ctx.io);
        defer stream.close(ctx.io);

        var request_buf: [4096]u8 = undefined;
        var recv_buffer: [512]u8 = undefined;
        var conn_reader = stream.reader(ctx.io, &recv_buffer);
        var slices = [_][]u8{request_buf[0..]};
        _ = std.Io.Reader.readVec(&conn_reader.interface, &slices) catch |err| switch (err) {
            error.EndOfStream => {},
            error.ReadFailed => return error.ReadFailed,
        };

        var header_buf: [160]u8 = undefined;
        const header = try std.fmt.bufPrint(&header_buf, "HTTP/1.1 200 OK\r\nContent-Length: {d}\r\nContent-Type: application/octet-stream\r\nConnection: close\r\n\r\n", .{ctx.bundle_data.len});
        var write_buf: [4096]u8 = undefined;
        var stream_writer = stream.writer(ctx.io, &write_buf);
        try stream_writer.interface.writeAll(header);
        try stream_writer.interface.writeAll(ctx.bundle_data);
        try stream_writer.interface.flush();
    }
};

/// Unblock an InstallBundleServer thread stuck in accept() when the roc
/// command under test failed before ever connecting, so a clean assertion
/// failure is reported instead of a join hang that the harness times out.
fn pokeInstallBundleServer(io: std.Io, port: u16) void {
    var address = std.Io.net.IpAddress.parse("127.0.0.1", port) catch return;
    const stream = std.Io.net.IpAddress.connect(&address, io, .{ .mode = .stream }) catch return;
    stream.close(io);
}

fn customInstallRunRoundtrip(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, timeout_ms: u64) ?TestResult {
    // Bundle a headerless default app from its own directory so main.roc sits
    // at the bundle root.
    const app_dir = createWorkSubdir(io, allocator, env, "install-app") catch |err|
        return customInfraFailure(allocator, timer, "failed to create app dir: {}", .{err});
    const app_main = std.fs.path.join(allocator, &.{ app_dir, "main.roc" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate app path: {}", .{err});
    std.Io.Dir.cwd().writeFile(io, .{ .sub_path = app_main, .data = "main! = |_args| {\n    echo!(\"installed tool ran\")\n    Ok({})\n}\n\nexpect True\n" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to write app main.roc: {}", .{err});

    const serve_dir = createWorkSubdir(io, allocator, env, "install-serve") catch |err|
        return customInfraFailure(allocator, timer, "failed to create serve dir: {}", .{err});

    const roc_abs = if (std.fs.path.isAbsolute(roc_binary_path))
        roc_binary_path
    else
        std.fs.path.join(allocator, &.{ project_root_path, roc_binary_path }) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate roc path: {}", .{err});

    const bundle_timeout = childCommandTimeoutMs(timer, timeout_ms) orelse
        return timeoutFailure(allocator, timer, .run, "case timeout exhausted before bundling");
    const bundle_result = runRawInEnv(io, allocator, env, &.{ roc_abs, "bundle", "--output-dir", serve_dir, "main.roc" }, app_dir, null, bundle_timeout) catch |err|
        return customInfraFailure(allocator, timer, "bundle spawn error: {}", .{err});
    if (exitCode(bundle_result.term) != 0) {
        return failureFromRun(allocator, timer, bundle_result, "roc bundle failed");
    }
    const created_prefix = "Created: ";
    const created_idx = std.mem.find(u8, bundle_result.stdout, created_prefix) orelse
        return failureFromRun(allocator, timer, bundle_result, "roc bundle did not report a created file");
    const created_rest = bundle_result.stdout[created_idx + created_prefix.len ..];
    const created_eol = std.mem.find(u8, created_rest, "\n") orelse created_rest.len;
    // roc names the archive relative to the directory it ran in.
    const bundle_path = std.fs.path.resolve(allocator, &.{ app_dir, std.mem.trim(u8, created_rest[0..created_eol], " \r") }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate bundle path: {}", .{err});
    const bundle_filename = std.fs.path.basename(bundle_path);

    const bundle_bytes = std.Io.Dir.cwd().readFileAlloc(io, bundle_path, allocator, .unlimited) catch |err|
        return customInfraFailure(allocator, timer, "failed to read bundle {s}: {}", .{ bundle_path, err });

    const loopback = std.Io.net.IpAddress.parse("127.0.0.1", 0) catch |err|
        return customInfraFailure(allocator, timer, "failed to parse loopback address: {}", .{err});
    var server = loopback.listen(io, .{ .reuse_address = true }) catch |err|
        return customInfraFailure(allocator, timer, "failed to listen on loopback: {}", .{err});
    defer server.deinit(io);
    const port = server.socket.address.getPort();

    var server_ctx = InstallBundleServer{
        .server = &server,
        .bundle_data = bundle_bytes,
        .io = io,
    };
    const server_thread = std.Thread.spawn(.{}, InstallBundleServer.run, .{&server_ctx}) catch |err|
        return customInfraFailure(allocator, timer, "failed to spawn server thread: {}", .{err});

    const url = std.fmt.allocPrint(allocator, "http://127.0.0.1:{d}/{s}", .{ port, bundle_filename }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate url: {}", .{err});

    // 1. Install: downloads (the only network access in this test), builds
    //    with --opt=speed, and publishes the entry.
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "install", "hello_tool", url },
        .contains = &.{.{ .stream = .stdout, .text = "Installed hello_tool" }},
    })) |failure| {
        pokeInstallBundleServer(io, port);
        server_thread.join();
        return failure;
    }
    server_thread.join();

    // 2. Test the installed shorthand's explicitly requested root.
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "test", "hello_tool", "--no-cache" },
        .contains = &.{.{ .stream = .stdout, .text = "All (1) tests passed" }},
    })) |failure| return failure;

    // 3. Run the installed shorthand.
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "run", "hello_tool" },
        .contains = &.{.{ .stream = .stdout, .text = "installed tool ran" }},
    })) |failure| return failure;

    // 4. Desert island: delete the package cache; the installed tool must
    //    still run (and must not touch the network—the server is gone).
    std.Io.Dir.cwd().deleteTree(io, env.dirs.roc_cache_dir) catch |err|
        return customInfraFailure(allocator, timer, "failed to delete cache dir: {}", .{err});
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "run", "hello_tool" },
        .contains = &.{.{ .stream = .stdout, .text = "installed tool ran" }},
    })) |failure| return failure;

    // 5. Same name + same URL is an idempotent no-op (no download).
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "install", "hello_tool", url },
        .contains = &.{.{ .stream = .stdout, .text = "already installed" }},
    })) |failure| return failure;

    // 6. Same name + different URL fails without touching the entry
    //    (detected before any download).
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "install", "hello_tool", "https://example.com/other/1.2.3/AQmoxbAY7eQfXMbi9XUxBvBGZcxZCs1tdNeFriRRkwSc.tar.zst" },
        .exit = .{ .code = 1 },
        .contains = &.{.{ .stream = .stderr, .text = "already installed from a different URL" }},
    })) |failure| return failure;
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "run", "hello_tool" },
        .contains = &.{.{ .stream = .stdout, .text = "installed tool ran" }},
    })) |failure| return failure;

    // 7. Build flags that cannot apply to a prebuilt binary are rejected.
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "run", "--opt=speed", "hello_tool" },
        .exit = .failure,
        .contains = &.{.{ .stream = .stderr, .text = "--opt has no effect" }},
    })) |failure| return failure;

    return null;
}

fn customInstallGlueRoundtrip(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, timeout_ms: u64) ?TestResult {
    // A glue spec on the compiler-owned glue platform, bundled from its own
    // directory. The bundle carries only the spec: the platform is embedded
    // in every compiler.
    const spec_dir = createWorkSubdir(io, allocator, env, "glue-spec") catch |err|
        return customInfraFailure(allocator, timer, "failed to create spec dir: {}", .{err});
    const spec_main = std.fs.path.join(allocator, &.{ spec_dir, "main.roc" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate spec path: {}", .{err});
    const source = std.Io.Dir.cwd().readFileAlloc(io, "test/glue/frozen-generator/main.roc", allocator, .limited(1024 * 1024)) catch |err|
        return customInfraFailure(allocator, timer, "failed to read frozen generator: {}", .{err});
    std.Io.Dir.cwd().writeFile(io, .{ .sub_path = spec_main, .data = source }) catch |err|
        return customInfraFailure(allocator, timer, "failed to write glue spec: {}", .{err});

    const serve_dir = createWorkSubdir(io, allocator, env, "glue-serve") catch |err|
        return customInfraFailure(allocator, timer, "failed to create serve dir: {}", .{err});

    const roc_abs = if (std.fs.path.isAbsolute(roc_binary_path))
        roc_binary_path
    else
        std.fs.path.join(allocator, &.{ project_root_path, roc_binary_path }) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate roc path: {}", .{err});

    const bundle_timeout = childCommandTimeoutMs(timer, timeout_ms) orelse
        return timeoutFailure(allocator, timer, .run, "case timeout exhausted before bundling");
    const bundle_result = runRawInEnv(io, allocator, env, &.{ roc_abs, "bundle", "--output-dir", serve_dir, "main.roc" }, spec_dir, null, bundle_timeout) catch |err|
        return customInfraFailure(allocator, timer, "bundle spawn error: {}", .{err});
    if (exitCode(bundle_result.term) != 0) {
        return failureFromRun(allocator, timer, bundle_result, "roc bundle of glue spec failed");
    }
    const created_prefix = "Created: ";
    const created_idx = std.mem.find(u8, bundle_result.stdout, created_prefix) orelse
        return failureFromRun(allocator, timer, bundle_result, "roc bundle did not report a created file");
    const created_rest = bundle_result.stdout[created_idx + created_prefix.len ..];
    const created_eol = std.mem.find(u8, created_rest, "\n") orelse created_rest.len;
    // roc names the archive relative to the directory it ran in.
    const bundle_path = std.fs.path.resolve(allocator, &.{ spec_dir, std.mem.trim(u8, created_rest[0..created_eol], " \r") }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate bundle path: {}", .{err});
    const bundle_filename = std.fs.path.basename(bundle_path);

    const bundle_bytes = std.Io.Dir.cwd().readFileAlloc(io, bundle_path, allocator, .unlimited) catch |err|
        return customInfraFailure(allocator, timer, "failed to read bundle {s}: {}", .{ bundle_path, err });

    const loopback = std.Io.net.IpAddress.parse("127.0.0.1", 0) catch |err|
        return customInfraFailure(allocator, timer, "failed to parse loopback address: {}", .{err});
    var server = loopback.listen(io, .{ .reuse_address = true }) catch |err|
        return customInfraFailure(allocator, timer, "failed to listen on loopback: {}", .{err});
    defer server.deinit(io);
    const port = server.socket.address.getPort();

    var server_ctx = InstallBundleServer{
        .server = &server,
        .bundle_data = bundle_bytes,
        .io = io,
    };
    const server_thread = std.Thread.spawn(.{}, InstallBundleServer.run, .{&server_ctx}) catch |err|
        return customInfraFailure(allocator, timer, "failed to spawn server thread: {}", .{err});

    const url = std.fmt.allocPrint(allocator, "http://127.0.0.1:{d}/{s}", .{ port, bundle_filename }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate url: {}", .{err});

    // 1. Install: detects the glue spec and builds the self-contained object with
    //    --opt=speed (the only download in this test).
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "install", "glue_tool", url },
        .contains = &.{ .{ .stream = .stdout, .text = "glue plugin" }, .{ .stream = .stdout, .text = "Installed glue_tool" }, .{ .stream = .stdout, .text = "roc glue glue_tool" } },
    })) |failure| {
        pokeInstallBundleServer(io, port);
        server_thread.join();
        return failure;
    }
    server_thread.join();

    // 2. Use the installed shorthand against a real platform.
    const glue_out = createWorkSubdir(io, allocator, env, "glue-out") catch |err|
        return customInfraFailure(allocator, timer, "failed to create glue out dir: {}", .{err});
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "glue", "glue_tool", glue_out, "test/fx/platform/main.roc" },
        .contains = &.{.{ .stream = .stdout, .text = "callable.txt" }},
    })) |failure| return failure;
    if (checkFrozenGlueOutput(io, allocator, timer, glue_out)) |failure| return failure;

    // 3. Desert island: delete the cache; the installed spec source and
    //    prebuilt object must still work (the glue platform is embedded, and
    //    the server is gone).
    std.Io.Dir.cwd().deleteTree(io, env.dirs.roc_cache_dir) catch |err|
        return customInfraFailure(allocator, timer, "failed to delete cache dir: {}", .{err});
    const glue_out2 = createWorkSubdir(io, allocator, env, "glue-out2") catch |err|
        return customInfraFailure(allocator, timer, "failed to create glue out dir: {}", .{err});
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "glue", "glue_tool", glue_out2, "test/fx/platform/main.roc" },
        .contains = &.{.{ .stream = .stdout, .text = "callable.txt" }},
    })) |failure| return failure;
    if (checkFrozenGlueOutput(io, allocator, timer, glue_out2)) |failure| return failure;

    // 4. Kind mismatch is a specific error, not a fallback.
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "run", "glue_tool" },
        .exit = .failure,
        .contains = &.{.{ .stream = .stderr, .text = "installed as a glue spec" }},
    })) |failure| return failure;

    return null;
}

/// A small Zstandard frame expanding to a tar file just over the shared cap.
/// RLE blocks avoid allocating or storing the expanded fixture in the runner.
fn oversizedUrlBundle(allocator: Allocator) (std.Io.Writer.Error || std.fmt.BufPrintError || Allocator.Error)![]const u8 {
    var bytes: std.Io.Writer.Allocating = .init(allocator);
    defer bytes.deinit();
    // Zstandard magic, no content-size/checksum, 1 MiB window.
    try bytes.writer.writeAll(&.{ 0x28, 0xb5, 0x2f, 0xfd, 0, 0x50 });
    var header = @as([512]u8, @splat(0));
    @memcpy(header[0..11], "payload.bin");
    _ = try std.fmt.bufPrint(header[124..135], "{o:0>11}", .{base.max_bundle_expanded_bytes + 512});
    @memset(header[148..156], ' ');
    header[156] = '0';
    var checksum: u32 = 0;
    for (header) |byte| checksum += byte;
    _ = try std.fmt.bufPrint(header[148..154], "{o:0>6}", .{checksum});
    header[154] = 0;
    header[155] = ' ';
    // One raw block containing the tar header.
    try bytes.writer.writeInt(u24, 512 << 3, .little);
    try bytes.writer.writeAll(&header);
    var remaining: u64 = base.max_bundle_expanded_bytes + 512 + 1024;
    while (remaining > 0) {
        const size: u24 = @intCast(@min(remaining, 128 * 1024));
        remaining -= size;
        // Block type 1 is RLE; bit zero marks the last block.
        try bytes.writer.writeInt(u24, (size << 3) | 2 | @intFromBool(remaining == 0), .little);
        try bytes.writer.writeByte(0);
    }
    return bytes.toOwnedSlice();
}

fn customUrlBundleExpandedLimit(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, timeout_ms: u64) ?TestResult {
    const bundle_bytes = oversizedUrlBundle(allocator) catch |err|
        return customInfraFailure(allocator, timer, "failed to create oversized bundle: {}", .{err});
    const loopback = std.Io.net.IpAddress.parse("127.0.0.1", 0) catch |err|
        return customInfraFailure(allocator, timer, "failed to parse loopback: {}", .{err});
    var server = loopback.listen(io, .{ .reuse_address = true }) catch |err|
        return customInfraFailure(allocator, timer, "failed to listen: {}", .{err});
    defer server.deinit(io);
    const port = server.socket.address.getPort();
    // Extraction must hit its cap before reaching hash verification.
    const url = std.fmt.allocPrint(allocator, "http://127.0.0.1:{d}/AQmoxbAY7eQfXMbi9XUxBvBGZcxZCs1tdNeFriRRkwSc.tar.zst", .{port}) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate URL: {}", .{err});
    const app_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "main.roc" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate app path: {}", .{err});
    const app_source = std.fmt.allocPrint(allocator, "app [main!] {{ pf: platform \"{s}\" }}\nmain! = || {{}}\n", .{url}) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate app source: {}", .{err});
    std.Io.Dir.cwd().writeFile(io, .{ .sub_path = app_path, .data = app_source }) catch |err|
        return customInfraFailure(allocator, timer, "failed to write app: {}", .{err});
    for ([_]bool{ false, true }) |platform| {
        var server_ctx = InstallBundleServer{ .server = &server, .bundle_data = bundle_bytes, .io = io };
        const thread = std.Thread.spawn(.{}, InstallBundleServer.run, .{&server_ctx}) catch |err|
            return customInfraFailure(allocator, timer, "failed to spawn bundle server: {}", .{err});
        if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
            .args = if (platform) &.{ "check", "--max-transitive-mb=1", app_path } else &.{ "run", url },
            .exit = .{ .code = 1 },
            .contains = if (platform)
                &.{ .{ .stream = .stderr, .text = "1048576 bytes" }, .{ .stream = .stderr, .text = "--max-transitive-mb" } }
            else
                &.{.{ .stream = .stderr, .text = "ExpandedSizeLimitExceeded" }},
        })) |failure| {
            pokeInstallBundleServer(io, port);
            thread.join();
            return failure;
        }
        thread.join();
    }
    // Neither a published bundle nor a partially extracted staging directory survives.
    const cache_path = std.fs.path.join(allocator, &.{ env.dirs.roc_cache_dir, "roc", "packages" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate package cache path: {}", .{err});
    var cache = std.Io.Dir.cwd().openDir(io, cache_path, .{ .iterate = true }) catch |err|
        return customInfraFailure(allocator, timer, "failed to open package cache: {}", .{err});
    defer cache.close(io);
    var entries = cache.iterate();
    while (entries.next(io) catch |err| return customInfraFailure(allocator, timer, "failed to inspect cache: {}", .{err})) |entry| {
        if (std.mem.startsWith(u8, entry.name, "AQmoxbAY7eQfXMbi9XUxBvBGZcxZCs1tdNeFriRRkwSc"))
            return customInfraFailure(allocator, timer, "failed extraction left a cache entry: {s}", .{entry.name});
    }
    return null;
}

fn customInstallHashMismatch(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, timeout_ms: u64) ?TestResult {
    // Serve a well-formed bundle under a URL whose filename hash does not
    // match its content: decompression succeeds but BLAKE3 verification must
    // fail, and the failed install must leave no visible entry.
    const app_dir = createWorkSubdir(io, allocator, env, "mismatch-app") catch |err|
        return customInfraFailure(allocator, timer, "failed to create app dir: {}", .{err});
    const app_main = std.fs.path.join(allocator, &.{ app_dir, "main.roc" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate app path: {}", .{err});
    std.Io.Dir.cwd().writeFile(io, .{ .sub_path = app_main, .data = "main! = |_args| {\n    echo!(\"should never run\")\n    Ok({})\n}\n" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to write app main.roc: {}", .{err});

    const serve_dir = createWorkSubdir(io, allocator, env, "mismatch-serve") catch |err|
        return customInfraFailure(allocator, timer, "failed to create serve dir: {}", .{err});

    const roc_abs = if (std.fs.path.isAbsolute(roc_binary_path))
        roc_binary_path
    else
        std.fs.path.join(allocator, &.{ project_root_path, roc_binary_path }) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate roc path: {}", .{err});

    const bundle_timeout = childCommandTimeoutMs(timer, timeout_ms) orelse
        return timeoutFailure(allocator, timer, .run, "case timeout exhausted before bundling");
    const bundle_result = runRawInEnv(io, allocator, env, &.{ roc_abs, "bundle", "--output-dir", serve_dir, "main.roc" }, app_dir, null, bundle_timeout) catch |err|
        return customInfraFailure(allocator, timer, "bundle spawn error: {}", .{err});
    if (exitCode(bundle_result.term) != 0) {
        return failureFromRun(allocator, timer, bundle_result, "roc bundle failed");
    }
    const created_prefix = "Created: ";
    const created_idx = std.mem.find(u8, bundle_result.stdout, created_prefix) orelse
        return failureFromRun(allocator, timer, bundle_result, "roc bundle did not report a created file");
    const created_rest = bundle_result.stdout[created_idx + created_prefix.len ..];
    const created_eol = std.mem.find(u8, created_rest, "\n") orelse created_rest.len;
    // roc names the archive relative to the directory it ran in.
    const bundle_path = std.fs.path.resolve(allocator, &.{ app_dir, std.mem.trim(u8, created_rest[0..created_eol], " \r") }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate bundle path: {}", .{err});

    const bundle_bytes = std.Io.Dir.cwd().readFileAlloc(io, bundle_path, allocator, .unlimited) catch |err|
        return customInfraFailure(allocator, timer, "failed to read bundle {s}: {}", .{ bundle_path, err });

    // A fixed valid base58 hash that cannot match this bundle's real content
    // hash (the bundle's own filename is derived from its BLAKE3 hash, so any
    // other valid hash string mismatches).
    const wrong_hash_filename = "AQmoxbAY7eQfXMbi9XUxBvBGZcxZCs1tdNeFriRRkwSc.tar.zst";
    if (std.mem.eql(u8, std.fs.path.basename(bundle_path), wrong_hash_filename)) {
        return customInfraFailure(allocator, timer, "fixture bundle unexpectedly matches the wrong-hash filename", .{});
    }

    const loopback = std.Io.net.IpAddress.parse("127.0.0.1", 0) catch |err|
        return customInfraFailure(allocator, timer, "failed to parse loopback address: {}", .{err});
    var server = loopback.listen(io, .{ .reuse_address = true }) catch |err|
        return customInfraFailure(allocator, timer, "failed to listen on loopback: {}", .{err});
    defer server.deinit(io);
    const port = server.socket.address.getPort();

    var server_ctx = InstallBundleServer{
        .server = &server,
        .bundle_data = bundle_bytes,
        .io = io,
    };
    const server_thread = std.Thread.spawn(.{}, InstallBundleServer.run, .{&server_ctx}) catch |err|
        return customInfraFailure(allocator, timer, "failed to spawn server thread: {}", .{err});

    const url = std.fmt.allocPrint(allocator, "http://127.0.0.1:{d}/{s}", .{ port, wrong_hash_filename }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate url: {}", .{err});

    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "install", "badtool", url },
        .exit = .{ .code = 1 },
        .contains = &.{ .{ .stream = .stderr, .text = "Failed to download from" }, .{ .stream = .stderr, .text = "HashMismatch" } },
    })) |failure| {
        pokeInstallBundleServer(io, port);
        server_thread.join();
        return failure;
    }
    server_thread.join();

    // "Nothing is installed" (rather than a corrupt-entry report) proves the
    // failed install left no visible entry behind.
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "run", "badtool" },
        .exit = .{ .code = 1 },
        .contains = &.{.{ .stream = .stderr, .text = "Nothing is installed under the name" }},
    })) |failure| return failure;

    return null;
}

fn createWorkSubdir(io: std.Io, allocator: Allocator, env: *const CaseEnv, name: []const u8) CliRunnerError![]const u8 {
    const path = try std.fs.path.join(allocator, &.{ env.dirs.work_dir, name });
    try std.Io.Dir.cwd().createDirPath(io, path);
    return path;
}

fn runGlueCommandInEnv(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
    glue_spec: []const u8,
    output_dir: []const u8,
) ?TestResult {
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "glue", glue_spec, output_dir, "test/fx/platform/main.roc" },
        .not_contains = &.{ .{ .stream = .stderr, .text = "panic" }, .{ .stream = .stderr, .text = "unreachable" } },
    })) |failure| return failure;
    return null;
}

fn copyGlueRuntimeFile(
    io: std.Io,
    allocator: Allocator,
    platform: GlueRuntimePlatform,
    filename: []const u8,
    dest_dir: []const u8,
) CliRunnerError!void {
    try copyGlueRuntimeFileAs(io, allocator, platform, filename, filename, dest_dir);
}

fn copyGlueRuntimeFileAs(
    io: std.Io,
    allocator: Allocator,
    platform: GlueRuntimePlatform,
    src_filename: []const u8,
    dest_filename: []const u8,
    dest_dir: []const u8,
) CliRunnerError!void {
    const src = try std.fs.path.join(allocator, &.{ project_root_path, platform.dir_path, src_filename });
    defer allocator.free(src);
    const dest = try std.fs.path.join(allocator, &.{ dest_dir, dest_filename });
    defer allocator.free(dest);
    try std.Io.Dir.cwd().copyFile(src, std.Io.Dir.cwd(), dest, io, .{});
}

const GlueRuntimeWasmInterface = struct {
    module_def: *bytebox.ModuleDefinition,
    module_instance: *bytebox.ModuleInstance,
    wasm_main_handle: bytebox.FunctionHandle,
    wasm_result_len_handle: bytebox.FunctionHandle,
    memory: *bytebox.MemoryInstance,
    env_imports: bytebox.ModuleImportPackage,

    fn deinit(self: *GlueRuntimeWasmInterface) void {
        self.module_instance.destroy();
        self.module_def.destroy();
        self.env_imports.deinit();
    }
};

const GlueRuntimeWasmSetupError = std.Io.Dir.ReadFileAllocError ||
    std.mem.Allocator.Error ||
    bytebox.MalformedError ||
    bytebox.ValidationError ||
    bytebox.UnlinkableError ||
    bytebox.UninstantiableError ||
    bytebox.TrapError ||
    bytebox.ExportError;

const GlueRuntimeWasmCallError = bytebox.TrapError || error{
    GlueWasmResultOutOfBounds,
};

const GlueRuntimeWasmHostContext = struct {
    memory: ?*bytebox.MemoryInstance = null,

    fn readString(self: *GlueRuntimeWasmHostContext, ptr: i32, len: i32) []const u8 {
        if (self.memory) |memory| {
            const buffer = memory.buffer();
            const start: usize = @intCast(ptr);
            const byte_len: usize = @intCast(len);
            const end = start + byte_len;
            if (end <= buffer.len) return buffer[start..end];
        }
        return "(invalid wasm memory access)";
    }

    pub fn roc_panic(ctx: ?*anyopaque, _: *bytebox.ModuleInstance, params: [*]const bytebox.Val, _: [*]bytebox.Val) HostFunctionError!void {
        const self: *GlueRuntimeWasmHostContext = @ptrCast(@alignCast(ctx));
        const msg = self.readString(params[0].I32, params[1].I32);
        std.debug.print("[glue wasm panic] {s}\n", .{msg});
        return error.RocPanic;
    }

    pub fn roc_dbg(ctx: ?*anyopaque, _: *bytebox.ModuleInstance, params: [*]const bytebox.Val, _: [*]bytebox.Val) error{}!void {
        const self: *GlueRuntimeWasmHostContext = @ptrCast(@alignCast(ctx));
        const msg = self.readString(params[0].I32, params[1].I32);
        std.debug.print("[glue wasm dbg] {s}\n", .{msg});
    }

    pub fn roc_expect_failed(ctx: ?*anyopaque, _: *bytebox.ModuleInstance, params: [*]const bytebox.Val, _: [*]bytebox.Val) error{}!void {
        const self: *GlueRuntimeWasmHostContext = @ptrCast(@alignCast(ctx));
        const msg = self.readString(params[0].I32, params[1].I32);
        std.debug.print("[glue wasm expect failed] {s}\n", .{msg});
    }
};

var glue_runtime_wasm_host_context: GlueRuntimeWasmHostContext = .{};

fn setupGlueRuntimeWasm(io: std.Io, allocator: Allocator, wasm_path: []const u8) GlueRuntimeWasmSetupError!GlueRuntimeWasmInterface {
    const wasm_data = try std.Io.Dir.cwd().readFileAlloc(io, wasm_path, allocator, .limited(256 * 1024 * 1024));

    var module_def = try bytebox.createModuleDefinition(allocator, .{ .debug_name = "glue_runtime_contract" });
    errdefer module_def.destroy();
    try module_def.decode(wasm_data);

    var module_instance = try bytebox.createModuleInstance(.Stack, module_def, allocator);
    errdefer module_instance.destroy();

    var env_imports = try bytebox.ModuleImportPackage.init("env", null, &glue_runtime_wasm_host_context, allocator);
    errdefer env_imports.deinit();
    try env_imports.addHostFunction("roc_panic", &[_]bytebox.ValType{ .I32, .I32 }, &[_]bytebox.ValType{}, GlueRuntimeWasmHostContext.roc_panic, &glue_runtime_wasm_host_context);
    try env_imports.addHostFunction(shim_symbols.roc_dbg, &[_]bytebox.ValType{ .I32, .I32 }, &[_]bytebox.ValType{}, GlueRuntimeWasmHostContext.roc_dbg, &glue_runtime_wasm_host_context);
    try env_imports.addHostFunction(shim_symbols.roc_expect_failed, &[_]bytebox.ValType{ .I32, .I32 }, &[_]bytebox.ValType{}, GlueRuntimeWasmHostContext.roc_expect_failed, &glue_runtime_wasm_host_context);

    const imports = [_]bytebox.ModuleImportPackage{env_imports};
    try module_instance.instantiate(.{
        .stack_size = 1024 * 256,
        .imports = &imports,
    });

    const memory = module_instance.store.getMemory(0);
    glue_runtime_wasm_host_context.memory = memory;

    return .{
        .module_def = module_def,
        .module_instance = module_instance,
        .wasm_main_handle = try module_instance.getFunctionHandle("wasm_main"),
        .wasm_result_len_handle = try module_instance.getFunctionHandle("wasm_result_len"),
        .memory = memory,
        .env_imports = env_imports,
    };
}

fn callGlueRuntimeWasmMain(wasm: *const GlueRuntimeWasmInterface, allocator: Allocator) GlueRuntimeWasmCallError![]const u8 {
    var params_main: [0]bytebox.Val = undefined;
    var returns_main: [1]bytebox.Val = undefined;
    _ = wasm.module_instance.invoke(wasm.wasm_main_handle, &params_main, &returns_main, .{}) catch |err| {
        var backtrace = wasm.module_instance.formatBacktrace(2, allocator) catch null;
        if (backtrace) |*bt| {
            defer bt.deinit();
            std.debug.print("[glue wasm backtrace]\n{s}\n", .{bt.items});
        }
        return err;
    };

    var params_len: [0]bytebox.Val = undefined;
    var returns_len: [1]bytebox.Val = undefined;
    _ = try wasm.module_instance.invoke(wasm.wasm_result_len_handle, &params_len, &returns_len, .{});

    const result_ptr: usize = @intCast(returns_main[0].I32);
    const result_len: usize = @intCast(returns_len[0].I32);
    const wasm_memory = wasm.memory.buffer();
    if (result_ptr + result_len > wasm_memory.len) return error.GlueWasmResultOutOfBounds;
    return wasm_memory[result_ptr .. result_ptr + result_len];
}

fn runGlueRuntimeWasmModule(
    io: std.Io,
    allocator: Allocator,
    timer: *harness.Timer,
    timeout_ms: u64,
    wasm_path: []const u8,
) ?TestResult {
    _ = childCommandTimeoutMs(timer, timeout_ms) orelse
        return timeoutFailure(allocator, timer, .run, "case timeout exhausted before wasm module started");

    var run_timer = harness.Timer.start() catch return customInfraFailure(allocator, timer, "no clock", .{});
    var wasm = setupGlueRuntimeWasm(io, allocator, wasm_path) catch |err|
        return customInfraFailure(allocator, timer, "failed to load glue runtime wasm module: {}", .{err});
    defer wasm.deinit();

    const result = callGlueRuntimeWasmMain(&wasm, allocator) catch |err|
        return customFailure(allocator, timer, "glue runtime wasm execution failed: {}", .{err});
    const owned_result = allocator.dupe(u8, result) catch result;
    const run_ns = run_timer.read();

    if (std.mem.find(u8, result, "PASS glue-runtime") == null) {
        return .{
            .status = .run_failed,
            .phase = .run,
            .duration_ns = timer.read(),
            .run_ns = run_ns,
            .stdout_capture = owned_result,
            .message = "glue runtime wasm result did not contain PASS marker",
        };
    }
    for ([_][]const u8{ "FAIL", "panic" }) |forbidden| {
        if (std.mem.find(u8, result, forbidden) != null) {
            return .{
                .status = .run_failed,
                .phase = .run,
                .duration_ns = timer.read(),
                .run_ns = run_ns,
                .stdout_capture = owned_result,
                .message = "glue runtime wasm result contained forbidden text",
            };
        }
    }

    return null;
}

fn runGlueRuntimeCase(
    io: std.Io,
    allocator: Allocator,
    runtime: GlueRuntimeCase,
    timeout_ms: u64,
) TestResult {
    var timer = harness.Timer.start() catch return .{ .status = .infra_error, .phase = .setup, .message = "no clock" };

    const native_target: ?GlueNativeTarget = switch (runtime.target) {
        .native => nativeGlueTarget() orelse {
            return .{ .status = .skip, .phase = .setup, .duration_ns = timer.read(), .message = "glue runtime native contracts do not support this host target" };
        },
        .wasm32 => null,
    };

    // Zig 0.17 rejects `@Vector` fields in `extern struct`/`extern union`
    // (compiler commit 6d2c8349c5), so ZigGlue cannot declare the vector
    // aggregates layout-probe exchanges with its host on any target. Roc's
    // host ABI contract is unchanged and CGlue and RustGlue still exercise
    // it. Aligned-array and f128 stand-ins change the C calling convention,
    // so no substitute is generated.
    // Unsupported pending a future design for Zig vector aggregates.
    if (zigGlueUnsupportedVectorAggregates(runtime.language, runtime.platform.name)) {
        return .{
            .status = .skip,
            .phase = .setup,
            .duration_ns = timer.read(),
            .message = "ZigGlue does not support SIMD vectors inside extern aggregates with Zig 0.17",
        };
    }

    // Zig 0.17 mislowers a natural C ABI aggregate signature exercised by
    // layout-probe on arm64musl: after five integer arguments occupy x0-x4,
    // Zig passes the 16-byte-aligned Dec aggregate in x5/x6 instead of
    // rounding up to the even pair x6/x7 as AAPCS64 requires. CGlue and
    // RustGlue continue to exercise this signature on arm64musl.
    // TODO #10392: Remove this skip after Roc uses a Zig version that lowers this signature correctly.
    if (native_target) |target| {
        if (runtime.language == .zig and std.mem.eql(u8, runtime.platform.name, "layout-probe")) {
            if (zigCompilerMislowersLayoutProbeAbi(target.roc_target)) {
                return .{
                    .status = .skip,
                    .phase = .setup,
                    .duration_ns = timer.read(),
                    .message = "Zig compiler mislowers an aggregate argument in this target's natural C ABI",
                };
            }
        }
    }

    const roc_target_name = switch (runtime.target) {
        .native => native_target.?.roc_target,
        .wasm32 => "wasm32",
    };
    const host_file_name = glueRuntimeHostFileName(runtime.language, runtime.target);
    const platform_source_file = runtime.platform.platform_file;

    var env = buildCaseEnv(io, allocator) catch
        return .{ .status = .infra_error, .phase = .setup, .duration_ns = timer.read(), .message = "failed to create test environment" };
    defer env.deinit(allocator);

    const platform_dir = std.fs.path.join(allocator, &.{ env.dirs.work_dir, runtime.platform.name }) catch |err|
        return addPreservedWorkDirMessage(allocator, customInfraFailure(allocator, &timer, "failed to allocate glue runtime platform dir: {}", .{err}), env.dirs.work_dir);
    const target_dir = std.fs.path.join(allocator, &.{ platform_dir, "targets", roc_target_name }) catch |err|
        return addPreservedWorkDirMessage(allocator, customInfraFailure(allocator, &timer, "failed to allocate glue runtime target dir: {}", .{err}), env.dirs.work_dir);
    const platform_path = std.fs.path.join(allocator, &.{ platform_dir, runtime.platform.platform_file }) catch |err|
        return addPreservedWorkDirMessage(allocator, customInfraFailure(allocator, &timer, "failed to allocate glue runtime platform path: {}", .{err}), env.dirs.work_dir);
    const app_path = std.fs.path.join(allocator, &.{ platform_dir, runtime.platform.app_file }) catch |err|
        return addPreservedWorkDirMessage(allocator, customInfraFailure(allocator, &timer, "failed to allocate glue runtime app path: {}", .{err}), env.dirs.work_dir);
    const host_path = std.fs.path.join(allocator, &.{ platform_dir, host_file_name }) catch |err|
        return addPreservedWorkDirMessage(allocator, customInfraFailure(allocator, &timer, "failed to allocate glue runtime host path: {}", .{err}), env.dirs.work_dir);
    const host_o_path = std.fs.path.join(allocator, &.{ target_dir, "host.o" }) catch |err|
        return addPreservedWorkDirMessage(allocator, customInfraFailure(allocator, &timer, "failed to allocate glue runtime host object path: {}", .{err}), env.dirs.work_dir);
    const host_lib_name = if (native_target) |target| target.host_library else "libhost.a";
    const host_lib_path = std.fs.path.join(allocator, &.{ target_dir, host_lib_name }) catch |err|
        return addPreservedWorkDirMessage(allocator, customInfraFailure(allocator, &timer, "failed to allocate glue runtime host archive path: {}", .{err}), env.dirs.work_dir);
    const host_wasm_path = std.fs.path.join(allocator, &.{ target_dir, "host.wasm" }) catch |err|
        return addPreservedWorkDirMessage(allocator, customInfraFailure(allocator, &timer, "failed to allocate glue runtime host wasm path: {}", .{err}), env.dirs.work_dir);
    const output_name = switch (runtime.target) {
        .native => native_target.?.output_name,
        .wasm32 => "glue-runtime-app.wasm",
    };
    const output_path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, output_name }) catch |err|
        return addPreservedWorkDirMessage(allocator, customInfraFailure(allocator, &timer, "failed to allocate glue runtime app output path: {}", .{err}), env.dirs.work_dir);
    const target_arg = std.fmt.allocPrint(allocator, "--target={s}", .{roc_target_name}) catch |err|
        return addPreservedWorkDirMessage(allocator, customInfraFailure(allocator, &timer, "failed to allocate glue runtime target arg: {}", .{err}), env.dirs.work_dir);
    const output_arg = outputArg(allocator, output_path) catch |err|
        return addPreservedWorkDirMessage(allocator, customInfraFailure(allocator, &timer, "failed to allocate glue runtime output arg: {}", .{err}), env.dirs.work_dir);

    std.Io.Dir.cwd().createDirPath(io, target_dir) catch |err|
        return addPreservedWorkDirMessage(allocator, customInfraFailure(allocator, &timer, "failed to create glue runtime target dir: {}", .{err}), env.dirs.work_dir);
    copyGlueRuntimeFileAs(io, allocator, runtime.platform, platform_source_file, runtime.platform.platform_file, platform_dir) catch |err|
        return addPreservedWorkDirMessage(allocator, customInfraFailure(allocator, &timer, "failed to copy glue runtime platform file: {}", .{err}), env.dirs.work_dir);
    for (runtime.platform.module_files) |module_file| {
        copyGlueRuntimeFile(io, allocator, runtime.platform, module_file, platform_dir) catch |err|
            return addPreservedWorkDirMessage(allocator, customInfraFailure(allocator, &timer, "failed to copy glue runtime platform module {s}: {}", .{ module_file, err }), env.dirs.work_dir);
    }
    copyGlueRuntimeFile(io, allocator, runtime.platform, runtime.platform.app_file, platform_dir) catch |err|
        return addPreservedWorkDirMessage(allocator, customInfraFailure(allocator, &timer, "failed to copy glue runtime app file: {}", .{err}), env.dirs.work_dir);
    copyGlueRuntimeFile(io, allocator, runtime.platform, host_file_name, platform_dir) catch |err|
        return addPreservedWorkDirMessage(allocator, customInfraFailure(allocator, &timer, "failed to copy glue runtime host file: {}", .{err}), env.dirs.work_dir);
    switch (runtime.target) {
        .native => {
            const target = native_target.?;
            if (target.kind == .musl) {
                const musl_target = NativeMuslTarget{
                    .roc_target = target.roc_target,
                    .zig_target = target.zig_target,
                    .rust_target = target.rust_target,
                    .c_host_needs_compiler_rt = target.c_host_needs_compiler_rt,
                };
                copyNativeMuslTargetFile(io, allocator, musl_target, "rcrt1.o", target_dir) catch |err|
                    return addPreservedWorkDirMessage(allocator, customInfraFailure(allocator, &timer, "failed to copy glue runtime rcrt1.o: {}", .{err}), env.dirs.work_dir);
                copyNativeMuslTargetFile(io, allocator, musl_target, "libc.a", target_dir) catch |err|
                    return addPreservedWorkDirMessage(allocator, customInfraFailure(allocator, &timer, "failed to copy glue runtime libc.a: {}", .{err}), env.dirs.work_dir);
            }
            if (target.kind == .windows) {
                // An MSVC link uses only the inputs the platform declares, so
                // the startup archive and import libraries the build prepared
                // for fx sit beside the host library built below.
                for (msvc_runtime.files) |filename| {
                    copyFxTargetFile(io, allocator, target.roc_target, filename, target_dir) catch |err|
                        return addPreservedWorkDirMessage(allocator, customInfraFailure(allocator, &timer, "failed to copy glue runtime {s}: {}", .{ filename, err }), env.dirs.work_dir);
                }
            }
        },
        .wasm32 => {},
    }

    if (runGlueRuntimeCommand(io, allocator, &env, &timer, timeout_ms, runtime, platform_dir, platform_path)) |failure| {
        return addPreservedWorkDirMessage(allocator, failure, env.dirs.work_dir);
    }

    const compile_failure = switch (runtime.target) {
        .native => blk: {
            const target = native_target.?;
            break :blk switch (runtime.language) {
                .zig => compileGlueRuntimeZigHost(io, allocator, &env, &timer, timeout_ms, target, host_path, host_o_path, host_lib_path),
                .rust => compileGlueRuntimeRustHost(io, allocator, &env, &timer, timeout_ms, target, host_path, host_lib_path),
                .c => compileGlueRuntimeCHost(io, allocator, &env, &timer, timeout_ms, target, platform_dir, host_path, host_o_path, host_lib_path),
            };
        },
        .wasm32 => switch (runtime.language) {
            .zig => compileGlueRuntimeZigWasmHost(io, allocator, &env, &timer, timeout_ms, host_path, host_wasm_path),
            .c => compileGlueRuntimeCWasmHost(io, allocator, &env, &timer, timeout_ms, platform_dir, host_path, host_wasm_path),
            .rust => compileGlueRuntimeRustWasmHost(io, allocator, &env, &timer, timeout_ms, host_path, host_wasm_path),
        },
    };
    if (compile_failure) |failure| {
        return addPreservedWorkDirMessage(allocator, failure, env.dirs.work_dir);
    }

    if (runRocAndCheck(io, allocator, &env, &timer, timeout_ms, .{
        .args = &.{ "build", "--no-cache", target_arg, output_arg },
        .roc_file = app_path,
        .not_contains = &.{ .{ .stream = .stderr, .text = "panic" }, .{ .stream = .stderr, .text = "unreachable" } },
    })) |failure| {
        return addPreservedWorkDirMessage(allocator, failure, env.dirs.work_dir);
    }

    if (!builtOutputExists(io, allocator, output_path)) {
        return addPreservedWorkDirMessage(allocator, .{
            .status = .build_failed,
            .phase = .build,
            .duration_ns = timer.read(),
            .message = "glue runtime build succeeded but output file was not created",
        }, env.dirs.work_dir);
    }

    switch (runtime.target) {
        .native => {
            if (runRawAndCheck(io, allocator, &env, &timer, timeout_ms, &.{output_path}, env.dirs.work_dir, .{
                .args = &.{},
                .contains = &.{.{ .stream = .stderr, .text = "PASS glue-runtime" }},
                .not_contains = &.{
                    .{ .stream = .stderr, .text = "fail" },
                    .{ .stream = .stderr, .text = "panic" },
                    .{ .stream = .stdout, .text = "fail" },
                },
            })) |failure| {
                return addPreservedWorkDirMessage(allocator, failure, env.dirs.work_dir);
            }
        },
        .wasm32 => {
            if (runGlueRuntimeWasmModule(io, allocator, &timer, timeout_ms, output_path)) |failure| {
                return addPreservedWorkDirMessage(allocator, failure, env.dirs.work_dir);
            }
        },
    }

    util.cleanupTestWorkDir(io, env.dirs.work_dir);
    const elapsed = timer.read();
    return .{ .status = .pass, .phase = .run, .duration_ns = elapsed, .run_ns = elapsed };
}

fn zigGlueUnsupportedVectorAggregates(language: GlueLanguage, platform_name: []const u8) bool {
    return language == .zig and std.mem.eql(u8, platform_name, "layout-probe");
}

fn zigCompilerMislowersLayoutProbeAbi(roc_target_name: []const u8) bool {
    return std.mem.eql(u8, roc_target_name, "arm64musl");
}

fn runGlueRuntimeCommand(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
    runtime: GlueRuntimeCase,
    output_dir: []const u8,
    platform_path: []const u8,
) ?TestResult {
    var args: std.ArrayListUnmanaged([]const u8) = .empty;
    args.append(allocator, "glue") catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate glue runtime command args: {}", .{err});
    if (runtime.execution_mode.optArg()) |opt_arg| {
        args.append(allocator, opt_arg) catch |err|
            return customInfraFailure(allocator, timer, "failed to allocate glue runtime command args: {}", .{err});
    }
    args.append(allocator, runtime.language.glueSpec()) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate glue runtime command args: {}", .{err});
    args.append(allocator, output_dir) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate glue runtime command args: {}", .{err});
    args.append(allocator, platform_path) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate glue runtime command args: {}", .{err});

    const owned_args = args.toOwnedSlice(allocator) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate glue runtime command args: {}", .{err});

    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = owned_args,
        .not_contains = &.{ .{ .stream = .stderr, .text = "panic" }, .{ .stream = .stderr, .text = "unreachable" } },
    })) |failure| return failure;

    return null;
}

fn compileGlueRuntimeCHost(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
    target: GlueNativeTarget,
    include_dir: []const u8,
    host_path: []const u8,
    host_o_path: []const u8,
    host_lib_path: []const u8,
) ?TestResult {
    const include_flag = std.fmt.allocPrint(allocator, "-I{s}", .{include_dir}) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate glue runtime C include flag: {}", .{err});
    const cc_command = std.mem.concat(allocator, []const u8, &.{
        &.{ "zig", "cc" },
        if (target.kind == .musl) &.{"-fPIC"} else &.{},
        &.{
            "-target",
            target.zig_target,
            "-O2",
            "-std=c11",
            "-Wall",
            "-Wextra",
            "-Werror",
            include_flag,
            "-c",
            host_path,
            "-o",
            host_o_path,
        },
    }) catch |err| return customInfraFailure(allocator, timer, "failed to allocate glue host C command: {}", .{err});
    defer allocator.free(cc_command);
    if (runRawAndCheck(io, allocator, env, timer, timeout_ms, cc_command, project_root_path, .{ .args = &.{} })) |failure| return failure;

    // `zig cc -c` emits only the host translation unit; unlike the Zig host
    // (`zig build-obj -fcompiler-rt`) and the Rust host (`rustc --crate-type
    // staticlib`, which bundles compiler-builtins), it carries no compiler_rt.
    // roc's final static link (`-nostdlib -static`, adding no compiler_rt) then
    // leaves the soft-float libcalls that musl's `libc.a` references undefined.
    // On aarch64 `long double` is IEEE-128, so `vfprintf` pulls in `__addtf3`,
    // `__extenddftf2`, `__netf2`, ... and the link fails. (On x86_64 `long
    // double` is 80-bit x87, so those f128 libcalls are never referenced.)
    //
    // So the merge is needed only on aarch64. On x86_64 the host object links
    // cleanly on its own, so we archive it directly—which also matters
    // because the merge itself is broken there: `zig cc -r` (and the LLD `-r`
    // it drives) aborts when fed the `-fcompiler-rt` object on x86_64, so
    // merging would be both pointless and a hard crash.
    if (!target.c_host_needs_compiler_rt) {
        if (runRawAndCheck(io, allocator, env, timer, timeout_ms, &.{
            "zig",
            "ar",
            "rcs",
            host_lib_path,
            host_o_path,
        }, project_root_path, .{ .args = &.{} })) |failure| return failure;

        return null;
    }

    // aarch64: merge a compiler_rt object into the host object so `libhost.a`
    // is self-contained, exactly like the Zig host. A separate archive member
    // would not suffice: `libhost.a` is linked before `libc.a` (and lazily for
    // symbol-ABI hosts), so its compiler_rt member would never be pulled to
    // satisfy `libc.a`'s later references.
    const target_dir = std.fs.path.dirname(host_o_path) orelse project_root_path;
    const compiler_rt_root_path = std.fs.path.join(allocator, &.{ target_dir, "compiler_rt_root.zig" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate glue runtime compiler_rt root path: {}", .{err});
    const compiler_rt_o_path = std.fs.path.join(allocator, &.{ target_dir, "compiler_rt.o" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate glue runtime compiler_rt object path: {}", .{err});
    const host_combined_o_path = std.fs.path.join(allocator, &.{ target_dir, "host_combined.o" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate glue runtime combined host object path: {}", .{err});

    // An empty root module is enough: `-fcompiler-rt` emits the full compiler_rt
    // (as weak symbols) regardless of what the module itself references.
    std.Io.Dir.cwd().writeFile(io, .{ .sub_path = compiler_rt_root_path, .data = "" }) catch |err|
        return customInfraFailure(allocator, timer, "failed to write glue runtime compiler_rt root: {}", .{err});
    const compiler_rt_emit_flag = std.fmt.allocPrint(allocator, "-femit-bin={s}", .{compiler_rt_o_path}) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate glue runtime compiler_rt emit flag: {}", .{err});
    if (runRawAndCheck(io, allocator, env, timer, timeout_ms, &.{
        "zig",
        "build-obj",
        "-target",
        target.zig_target,
        "-fPIC",
        "-fcompiler-rt",
        compiler_rt_root_path,
        compiler_rt_emit_flag,
    }, project_root_path, .{ .args = &.{} })) |failure| return failure;

    // Relocatable-link the host object and compiler_rt into a single object so
    // one `libhost.a` member carries both.
    if (runRawAndCheck(io, allocator, env, timer, timeout_ms, &.{
        "zig",
        "cc",
        "-target",
        target.zig_target,
        "-r",
        host_o_path,
        compiler_rt_o_path,
        "-o",
        host_combined_o_path,
    }, project_root_path, .{ .args = &.{} })) |failure| return failure;

    if (runRawAndCheck(io, allocator, env, timer, timeout_ms, &.{
        "zig",
        "ar",
        "rcs",
        host_lib_path,
        host_combined_o_path,
    }, project_root_path, .{ .args = &.{} })) |failure| return failure;

    return null;
}

fn compileGlueRuntimeCWasmHost(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
    include_dir: []const u8,
    host_path: []const u8,
    host_wasm_path: []const u8,
) ?TestResult {
    const include_flag = std.fmt.allocPrint(allocator, "-I{s}", .{include_dir}) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate glue runtime C wasm include flag: {}", .{err});
    if (runRawAndCheck(io, allocator, env, timer, timeout_ms, &.{
        "zig",
        "cc",
        "-target",
        "wasm32-freestanding",
        "-msimd128",
        "-O2",
        "-std=c11",
        "-Wall",
        "-Wextra",
        "-Werror",
        "-fvisibility=default",
        "-ffunction-sections",
        "-fdata-sections",
        "-fPIC",
        include_flag,
        "-c",
        host_path,
        "-o",
        host_wasm_path,
    }, project_root_path, .{ .args = &.{} })) |failure| return failure;

    return null;
}

fn compileGlueRuntimeZigHost(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
    target: GlueNativeTarget,
    host_path: []const u8,
    host_o_path: []const u8,
    host_lib_path: []const u8,
) ?TestResult {
    const emit_flag = std.fmt.allocPrint(allocator, "-femit-bin={s}", .{host_o_path}) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate glue runtime Zig emit flag: {}", .{err});
    const root_module_arg = std.fmt.allocPrint(allocator, "-Mroot={s}", .{host_path}) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate glue host module argument: {}", .{err});
    const symbols_module_arg = std.fmt.allocPrint(allocator, "-Mshim_symbols={s}/src/builtins/shim_symbols.zig", .{project_root_path}) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate glue host symbols argument: {}", .{err});
    const allocator_module_arg = std.fmt.allocPrint(allocator, "-Mhost_alloc={s}/src/host_alloc/tracking.zig", .{project_root_path}) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate glue host allocator argument: {}", .{err});
    const io_module_arg = std.fmt.allocPrint(allocator, "-Mshim_io={s}/src/shim_io.zig", .{project_root_path}) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate glue host IO argument: {}", .{err});
    if (runRawAndCheck(io, allocator, env, timer, timeout_ms, &.{
        "zig",
        "build-obj",
        "-target",
        target.zig_target,
        "-fPIC",
        "-fcompiler-rt",
        "-lc",
        "--dep",
        "shim_symbols",
        "--dep",
        "host_alloc",
        "--dep",
        "shim_io",
        root_module_arg,
        symbols_module_arg,
        allocator_module_arg,
        io_module_arg,
        emit_flag,
    }, project_root_path, .{ .args = &.{} })) |failure| return failure;

    if (runRawAndCheck(io, allocator, env, timer, timeout_ms, &.{
        "zig",
        "ar",
        "rcs",
        host_lib_path,
        host_o_path,
    }, project_root_path, .{ .args = &.{} })) |failure| return failure;

    return null;
}

fn compileGlueRuntimeZigWasmHost(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
    host_path: []const u8,
    host_wasm_path: []const u8,
) ?TestResult {
    const emit_flag = std.fmt.allocPrint(allocator, "-femit-bin={s}", .{host_wasm_path}) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate glue runtime Zig wasm emit flag: {}", .{err});
    const root_module_arg = std.fmt.allocPrint(allocator, "-Mroot={s}", .{host_path}) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate glue host module argument: {}", .{err});
    const symbols_module_arg = std.fmt.allocPrint(allocator, "-Mshim_symbols={s}/src/builtins/shim_symbols.zig", .{project_root_path}) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate glue host symbols argument: {}", .{err});
    const allocator_module_arg = std.fmt.allocPrint(allocator, "-Mhost_alloc={s}/src/host_alloc/tracking.zig", .{project_root_path}) catch |err|
        return customInfraFailure(allocator, timer, "failed to allocate glue host allocator argument: {}", .{err});
    if (runRawAndCheck(io, allocator, env, timer, timeout_ms, &.{
        "zig",
        "build-obj",
        "-target",
        "wasm32-freestanding-none",
        "-mcpu",
        "baseline+simd128",
        "-OReleaseSmall",
        "-fPIC",
        "-ffunction-sections",
        "-fdata-sections",
        "--dep",
        "shim_symbols",
        "--dep",
        "host_alloc",
        root_module_arg,
        symbols_module_arg,
        allocator_module_arg,
        emit_flag,
    }, project_root_path, .{ .args = &.{} })) |failure| return failure;

    return null;
}

fn compileGlueRuntimeRustHost(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
    target: GlueNativeTarget,
    host_path: []const u8,
    host_lib_path: []const u8,
) ?TestResult {
    if (runRawAndCheck(io, allocator, env, timer, timeout_ms, &.{
        "rustc",
        "--edition=2021",
        "-D",
        "warnings",
        "--target",
        target.rust_target,
        "--cfg",
        "no_roc_std_helpers",
        "-C",
        "panic=abort",
        "--crate-type",
        "staticlib",
        host_path,
        "-o",
        host_lib_path,
    }, project_root_path, .{ .args = &.{} })) |failure| return failure;

    return null;
}

fn compileGlueRuntimeRustWasmHost(
    io: std.Io,
    allocator: Allocator,
    env: *const CaseEnv,
    timer: *harness.Timer,
    timeout_ms: u64,
    host_path: []const u8,
    host_wasm_path: []const u8,
) ?TestResult {
    // Have rustc resolve core and compiler_builtins, but keep the result
    // relocatable for Roc's surgical linker. link-dead-code disables the
    // gc-sections flag that wasm-ld rejects when combined with -r.
    if (runRawAndCheck(io, allocator, env, timer, timeout_ms, &.{
        "rustc",
        "--edition=2021",
        "-D",
        "warnings",
        "--target",
        "wasm32-unknown-unknown",
        "--cfg",
        "no_roc_std_helpers",
        "-C",
        "panic=abort",
        "-C",
        "opt-level=s",
        "-C",
        "target-feature=+simd128",
        "-C",
        "link-dead-code=yes",
        "-C",
        "link-arg=-r",
        "-C",
        "link-arg=--allow-undefined",
        "-C",
        "link-arg=--strip-debug",
        "--crate-type",
        "cdylib",
        host_path,
        "-o",
        host_wasm_path,
    }, project_root_path, .{ .args = &.{} })) |failure| return failure;

    return null;
}

fn customGlueDebug(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, timeout_ms: u64) ?TestResult {
    const output_dir = createWorkSubdir(io, allocator, env, "glue-out") catch |err|
        return customInfraFailure(allocator, timer, "failed to create glue output dir: {}", .{err});
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "glue", "src/glue/src/DebugGlue.roc", output_dir, "test/fx/platform/main.roc" },
        .contains = &.{.{ .stream = .stderr, .text = "name: \"print_value!\"" }},
        .not_contains = &.{
            .{ .stream = .stderr, .text = "panic" },
            .{ .stream = .stderr, .text = "unreachable" },
            .{ .stream = .stderr, .text = "entrypoints" },
            .{ .stream = .stderr, .text = "name: \"\"" },
        },
    })) |failure| return failure;
    return null;
}

fn customGlueDebugDev(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, timeout_ms: u64) ?TestResult {
    const output_dir = createWorkSubdir(io, allocator, env, "glue-out") catch |err|
