test "cross target builds one build-only case per matching platform spec" {
    var arena = collections.SingleThreadArena.init(std.testing.allocator);
    defer arena.deinit();

    var suites = SuiteSelection{};
    suites.add(.platforms);
    const cases = try buildCases(
        std.testing.io,
        arena.allocator(),
        &.{"test/fx/"},
        .base,
        suites,
        .{},
        "x64musl",
    );

    const fx = platform_config.findPlatform("fx").?;
    if (std.meta.activeTag(fx.test_apps) != .spec_list) return error.TestUnexpectedResult;
    const expected_count = fx.test_apps.spec_list.len;
    try std.testing.expectEqual(expected_count, cases.len);
    for (cases) |case| {
        try std.testing.expectEqual(@as(?OptMode, null), case.backend);
        try std.testing.expect(std.mem.startsWith(u8, case.body.platform.roc_file, "test/fx/"));
        if (std.meta.activeTag(case.body.platform.test_kind) != .cross_compile) return error.TestUnexpectedResult;
        try std.testing.expectEqualStrings("x64musl", case.body.platform.test_kind.cross_compile);
    }
}

/// Entry point for the parallel CLI test runner.
pub fn main(init: std.process.Init) CliRunnerError!void {
    var gpa_impl: std.heap.DebugAllocator(.{ .stack_trace_frames = build_options.debug_gpa_stack_trace_frames }) = .init;
    defer _ = build_options.debugGpaOk(gpa_impl.deinit());
    const gpa = gpa_impl.allocator();

    var spec_arena = collections.SingleThreadArena.init(gpa);
    defer spec_arena.deinit();

    const parsed = parseRunnerArgs(spec_arena.allocator(), init.minimal.args) catch |err| {
        printUsage();
        return err;
    };
    const args = parsed.standard;

    if (args.help_requested) {
        printUsage();
        return;
    }

    if (args.positional.len < 1) {
        printUsage();
        std.process.exit(1);
    }

    project_root_path = try std.Io.Dir.cwd().realPathFileAlloc(init.io, ".", spec_arena.allocator());
    roc_binary_path = if (std.fs.path.isAbsolute(args.positional[0]))
        args.positional[0]
    else
        try std.fs.path.join(spec_arena.allocator(), &.{ project_root_path, args.positional[0] });
    glue_roc_binary_path = if (parsed.glue_roc) |path|
        if (std.fs.path.isAbsolute(path))
            path
        else
            try std.fs.path.join(spec_arena.allocator(), &.{ project_root_path, path })
    else
        roc_binary_path;
    glue_execution_mode = parsed.glue_options.execution_mode;
    platform_specialization_arg = parsed.specialization_arg;

    const tests = try buildCases(init.io, spec_arena.allocator(), args.filters, parsed.backends(), parsed.suites, parsed.glue_options, parsed.cross_target);
    if (tests.len == 0) return;
    const timeout_ms = effectiveTimeoutMs(args, parsed.suites);

    // Worker modes: on Windows the harness pool spawned this process with
    // `--worker <idx>` (single test) or `--worker-stream` (persistent). The
    // worker rebuilt the same case list above, so indices stay aligned with
    // the parent's. Handling these before the parent path matters: a worker
    // that fell through would reentrantly spawn its own pool of workers—
    // fork-bombing the box.
    if (Pool.runWorkerMode(init.io, args, tests, timeout_ms)) return;

    const cpu_count = std.Thread.getCpuCount() catch 4;
    const max_children = args.max_threads orelse @min(cpu_count, tests.len);

    std.debug.print("=== CLI Test Runner ===\n", .{});
    std.debug.print("{d} tests, {d} workers, {d}s timeout", .{ tests.len, max_children, timeout_ms / 1000 });
    if (parsed.cross_target) |target| {
        std.debug.print(", cross target: {s}\n\n", .{target});
    } else {
        switch (parsed.backends()) {
            .base => std.debug.print(", backends: interpreter, dev\n\n", .{}),
            .base_and_llvm => std.debug.print(", backends: interpreter, dev, size, speed\n\n", .{}),
            .llvm => std.debug.print(", backends: size, speed\n\n", .{}),
        }
    }
    if (parsed.suites.includes(.glue)) {
        std.debug.print("Glue generator: {s}, glue-opt={s}\n\n", .{
            glue_roc_binary_path,
            parsed.glue_options.execution_mode.cliName(),
        });
    }

    const results = try gpa.alloc(TestResult, tests.len);
    defer gpa.free(results);
    @memset(results, .{ .status = .crash });
    const spans = try gpa.alloc(?harness.PoolSpan, tests.len);
    defer gpa.free(spans);
    @memset(spans, null);

    // Build a worker_argv_template so Windows can re-invoke this binary as a
    // single-test Child worker. On POSIX it's unused (fork path doesn't
    // re-exec). Always pass the positional `roc_binary` path through so the
    // child uses the same binary.
    const worker_argv_template = try harness.buildWorkerArgvTemplate(init.io, spec_arena.allocator(), init.minimal.args);

    var wall_timer = harness.Timer.start() catch @panic("no clock");
    // Drain each parallel batch before a case that requires exclusive timing.
    // Keep the original case indices for re-executed Windows workers and the
    // original run timeline for statistics across all batches.
    var batch_start: usize = 0;
    while (batch_start < tests.len) {
        var batch_end = batch_start + 1;
        if (tests[batch_start].scheduling == .parallel) {
            while (batch_end < tests.len and tests[batch_end].scheduling == .parallel) : (batch_end += 1) {}
        }
        const batch_offset_ns = wall_timer.read();
        const batch_workers = @min(max_children, batch_end - batch_start);
        Pool.runWithSpans(init.io, tests[batch_start..batch_end], results[batch_start..batch_end], spans[batch_start..batch_end], batch_workers, timeout_ms, gpa, worker_argv_template, args.child_debug);
        for (spans[batch_start..batch_end]) |*maybe_span| {
            if (maybe_span.*) |*span| {
                span.start_ns += batch_offset_ns;
                span.end_ns += batch_offset_ns;
            }
        }
        batch_start = batch_end;
    }
    const wall_ns = wall_timer.read();

    printResults(tests, results, args.verbose, gpa, wall_ns, max_children);

    if (args.stats_json_path) |path| {
        try writeStatsJson(gpa, init.io, path, tests, results, spans);
    }

    for (results) |r| {
        if (r.stderr_capture) |s| gpa.free(s);
        if (r.stdout_capture) |s| gpa.free(s);
        if (r.message) |m| gpa.free(m);
    }

    for (results) |r| {
        if (r.status == .build_failed or
            r.status == .run_failed or
            r.status == .crash or
            r.status == .timeout or
            r.status == .infra_error) std.process.exit(1);
    }
}

test "static CLI cases honor LLVM availability before name filters" {
    var arena = collections.SingleThreadArena.init(std.testing.allocator);
    defer arena.deinit();
    var suites = SuiteSelection{};
    suites.add(.subcommands);
    for ([_]BackendSelection{ .base, .base_and_llvm, .llvm }) |backends| {
        const cases = try buildCases(std.testing.io, arena.allocator(), &.{"issue 11563:"}, backends, suites, .{}, null);
        var speed_count: usize = 0;
        var other_count: usize = 0;
        for (cases) |case| {
            if (case.backend == .speed) {
                speed_count += 1;
            } else {
                other_count += 1;
            }
        }
        try std.testing.expectEqual(@as(usize, @intFromBool(backends != .base)), speed_count);
        try std.testing.expectEqual(@as(usize, if (backends == .llvm) 0 else 3), other_count);
    }
}

test "the LLVM-only selection builds every size and speed case and nothing else" {
    var arena = collections.SingleThreadArena.init(std.testing.allocator);
    defer arena.deinit();
    var suites = SuiteSelection{};
    suites.addAll();
    const all = try buildCases(std.testing.io, arena.allocator(), &.{}, .base_and_llvm, suites, .{}, null);
    const llvm = try buildCases(std.testing.io, arena.allocator(), &.{}, .llvm, suites, .{}, null);
    var expected: usize = 0;
    for (all) |case| {
        if (case.backend == .size or case.backend == .speed) expected += 1;
    }
    try std.testing.expectEqual(expected, llvm.len);
    for (llvm, 0..) |case, index| {
        try std.testing.expect(case.backend == .size or case.backend == .speed);
        try std.testing.expectEqual(index, case.id);
    }
}

fn customBidiSourceSecurity(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, timeout_ms: u64) ?TestResult {
    const path = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "Bidi\u{202e}.roc" }) catch |err|
        return customInfraFailure(allocator, timer, "bidi path allocation: {}", .{err});
    for (base.bidi.controls, 0..) |control, index| {
        // Exercise both headerless modules and app headers. The missing
        // platform must never be resolved before the source-policy error.
        const prefix = if (index % 2 == 0)
            "main! = || { 1 } # "
        else
            "app [main!] { pf: platform \"missing-platform/main.roc\" }\nmain! = || { 1 } # ";
        const source = std.mem.concat(allocator, u8, &.{ prefix, control.utf8, "\n" }) catch |err|
            return customInfraFailure(allocator, timer, "bidi fixture allocation: {}", .{err});
        std.Io.Dir.cwd().writeFile(io, .{ .sub_path = path, .data = source }) catch |err|
            return customInfraFailure(allocator, timer, "bidi fixture write: {}", .{err});
        const commands = [_][]const []const u8{ &.{ "check", "--no-cache" }, &.{"check"}, &.{"check"}, &.{ "run", "--no-cache" }, &.{ "build", "--no-cache" }, &.{ "test", "--no-cache" }, &.{"fmt"}, &.{ "fmt", "--check" }, &.{ "fmt", "--stdin" } };
        for (commands) |args| {
            const stdin = std.mem.eql(u8, args[args.len - 1], "--stdin");
            const remaining = childCommandTimeoutMs(timer, timeout_ms) orelse
                return timeoutFailure(allocator, timer, .run, "bidi source checks timed out");
            const result = runRocInEnv(io, allocator, env, args, if (stdin) null else path, .absolute, &.{}, if (stdin) source else null, remaining) catch |err|
                return customInfraFailure(allocator, timer, "bidi command: {}", .{err});
            if (checkCommandExpectation(allocator, result, .{
                .args = args,
                .exit = .{ .code = 1 },
                .contains = &.{.{ .stream = .stderr, .text = "bidirectional control" }},
            })) |message| return failureFromRun(allocator, timer, result, message);
            for ([_][]const u8{ result.stdout, result.stderr }) |output| {
                var iter = base.bidi.Iterator{ .bytes = output };
                if (iter.next() != null) return customFailure(allocator, timer, "bidi control leaked into diagnostics", .{});
            }
            if (stdin and result.stdout.len != 0) return customFailure(allocator, timer, "unsafe formatted source emitted on stdout", .{});
            const after = std.Io.Dir.cwd().readFileAlloc(io, path, allocator, .limited(4096)) catch |err|
                return customInfraFailure(allocator, timer, "bidi fixture read: {}", .{err});
            if (!std.mem.eql(u8, after, source)) return customFailure(allocator, timer, "unsafe file changed by formatter", .{});
        }
    }
    return null;
}

/// Boxy is the positive control for the instrumentation, then the same cache
/// is consumed by default and explicitly specialized builds, cold and warm.
fn customSpecializedCallables(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, timeout_ms: u64) ?TestResult {
    var isolated = CaseEnv{ .dirs = env.dirs, .env_map = env.env_map.clone(allocator) catch |err| return customInfraFailure(allocator, timer, "clone environment: {}", .{err}) };
    defer isolated.env_map.deinit();
    isolated.env_map.put("ROC_TRACE_BOXY_WORK", "1") catch |err| return customInfraFailure(allocator, timer, "set diagnostic: {}", .{err});
    const output = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "specialized-callables" }) catch |err| return customInfraFailure(allocator, timer, "output path: {}", .{err});
    const out_arg = outputArg(allocator, output) catch |err| return customInfraFailure(allocator, timer, "output argument: {}", .{err});
    for ([_]?[]const u8{ "--specialize=no", null, "--specialize=yes", "--specialize=yes", "--specialize=no", null }) |strategy| {
        const args: []const []const u8 = if (strategy) |flag| &.{ "build", "--opt=dev", "--no-color", flag, out_arg } else &.{ "build", "--opt=dev", "--no-color", out_arg };
        const remaining = childCommandTimeoutMs(timer, timeout_ms) orelse return timeoutFailure(allocator, timer, .run, "specialization test timed out");
        const run = runRocInEnv(io, allocator, &isolated, args, "test/echo/issue_12569_specialized_callables.roc", .relative, &.{}, null, remaining) catch |err| return customInfraFailure(allocator, timer, "build: {}", .{err});
        if (!processSucceeded(run.term)) return failureFromRun(allocator, timer, run, "callable build failed");
        const is_boxy = if (strategy) |flag| std.mem.eql(u8, flag, "--specialize=no") else false;
        const traced = std.mem.find(u8, run.stderr, "boxy-work:") != null;
        if (traced != is_boxy) return failureFromRun(allocator, timer, run, "runtime strategy performed the wrong Boxy work");
        const exe = runnableOutputPath(io, allocator, output) catch |err| return customInfraFailure(allocator, timer, "executable: {}", .{err});
        const bytes = std.Io.Dir.cwd().readFileAlloc(io, exe, allocator, .limited(64 * 1024 * 1024)) catch |err| return customInfraFailure(allocator, timer, "read executable: {}", .{err});
        if (!is_boxy and std.mem.find(u8, bytes, "roc_boxy_") != null) return customFailure(allocator, timer, "specialized executable contains a Boxy symbol", .{});
        if (runRawAndCheck(io, allocator, env, timer, timeout_ms, &.{exe}, env.dirs.work_dir, .{ .args = &.{}, .stdout_exact = "a captured string longer than inline storage: 8\n42\n", .stderr_exact = "" })) |failure| return failure;
    }
    return null;
}

fn customSpecializedWasmCallables(io: std.Io, allocator: Allocator, env: *const CaseEnv, timer: *harness.Timer, timeout_ms: u64) ?TestResult {
    const output = std.fs.path.join(allocator, &.{ env.dirs.work_dir, "specialized-callables.wasm" }) catch |err| return customInfraFailure(allocator, timer, "output path: {}", .{err});
    const out_arg = outputArg(allocator, output) catch |err| return customInfraFailure(allocator, timer, "output argument: {}", .{err});
    if (runRocAndCheck(io, allocator, env, timer, timeout_ms, .{
        .args = &.{ "build", "--target=wasm32", "--opt=dev", "--specialize=yes", "--no-cache", out_arg },
        .roc_file = "test/wasm/issue_12569_specialized_callables.roc",
        .exit = .success,
    })) |failure| return failure;
    if (validateWasmOutput(io, allocator, timer, output)) |failure| return failure;
    const bytes = std.Io.Dir.cwd().readFileAlloc(io, output, allocator, .unlimited) catch |err| return customInfraFailure(allocator, timer, "read wasm: {}", .{err});
    if (std.mem.find(u8, bytes, "roc_boxy_") != null) return customFailure(allocator, timer, "specialized wasm contains a Boxy symbol", .{});
    var wasm = setupGlueRuntimeWasm(io, allocator, output) catch |err| return customFailure(allocator, timer, "load wasm: {}", .{err});
    defer wasm.deinit();
    const result = callGlueRuntimeWasmMain(&wasm, allocator) catch |err| return customFailure(allocator, timer, "execute wasm: {}", .{err});
    const expected = "a returned string longer than inline storage: 42a captured string longer than inline storage: 8";
    if (!std.mem.eql(u8, result, expected)) return customFailure(allocator, timer, "specialized wasm returned {s}", .{result});
    return null;
}
